INSERT INTO platform_private.learning_modules (id, module_key, version, metadata)
VALUES ('de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-start', '1.0.0', '{"title_ru":"Английский. Модуль 1 — старт","title_ky":"Англис тили. 1-модуль — старт","level_note_ru":"Для тех, кто начинает с нуля или почти всё забыл. Модуль ведёт от приветствия до рассказа о себе, своей семье и планах на учёбу.","level_note_ky":"Нөлдөн баштагандар же дээрлик баарын унутуп калгандар үчүн. Модуль саламдашуудан баштап, өзүң, үй-бүлөң жана окуу пландарың жөнүндө айтууга чейин алып барат."}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('87c8be87-fcc1-5480-8de4-1b5731a87de0', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l01', 1, '{"title_ru":"Приветствие и знакомство","title_ky":"Саламдашуу жана таанышуу","goal_ru":"Поздороваться по-английски, назвать своё имя и спросить имя собеседника.","goal_ky":"Англисче саламдашып, өз атыңды айтып, маектешиңдин атын сурайсың."}'::JSONB, '[{"text_ru":"Hello — приветствие на любое время суток и для любой ситуации. Hi — то же самое, короче и дружелюбнее. Good morning говорят утром, good evening — вечером.","text_ky":"Hello — каалаган убакта жана каалаган кырдаалда айтылуучу саламдашуу. Hi — ошол эле, бирок кыскараак жана достук мааниде. Good morning эртең менен, good evening кечинде айтылат.","examples":[{"en":"Hello!","ru":"Здравствуйте!","ky":"Саламатсызбы!"},{"en":"Hi!","ru":"Привет!","ky":"Салам!"},{"en":"Good morning!","ru":"Доброе утро!","ky":"Кутман таң!"},{"en":"Good evening!","ru":"Добрый вечер!","ky":"Кутман кеч!"}]},{"text_ru":"Назвать себя: My name is… («меня зовут…») или короче — I''m… Спросить имя: What''s your name? После знакомства говорят Nice to meet you.","text_ky":"Өзүңдү тааныштыруу: My name is… («менин атым…») же кыскараак — I''m… Атын суроо: What''s your name? Таанышкандан кийин Nice to meet you дешет.","examples":[{"en":"My name is Aidana.","ru":"Меня зовут Айдана.","ky":"Менин атым Айдана."},{"en":"I''m Nurlan.","ru":"Я Нурлан.","ky":"Мен Нурланмын."},{"en":"What''s your name?","ru":"Как тебя зовут?","ky":"Атың ким?"},{"en":"Nice to meet you!","ru":"Приятно познакомиться!","ky":"Таанышканыма кубанычтамын!"}]},{"text_ru":"How are you? — «как дела?». Обычный ответ: I''m fine, thanks. And you? Прощание — Goodbye или короче Bye. Good night — пожелание перед сном, а не приветствие.","text_ky":"How are you? — «кандайсың?». Кадимки жооп: I''m fine, thanks. And you? Коштошуу — Goodbye же кыскараак Bye. Good night уктаар алдында айтылат, саламдашуу эмес.","examples":[{"en":"How are you?","ru":"Как дела?","ky":"Кандайсың?"},{"en":"I''m fine, thanks. And you?","ru":"Хорошо, спасибо. А у тебя?","ky":"Жакшы, рахмат. Өзүңчү?"},{"en":"Goodbye!","ru":"До свидания!","ky":"Кош болуңуз!"},{"en":"Good night!","ru":"Спокойной ночи!","ky":"Жакшы жат!"}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('dd76de91-f1c5-52a5-8828-7dce1fe9c98c', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e01', 1, 'choice', '{"prompt_ru":"Выберите приветствие, которое подходит в любое время суток.","prompt_ky":"Күндүн каалаган убагына туура келген саламдашууну тандаңыз.","options":[{"id":"a","label":"Good morning","explain_ru":"Неверно: good morning говорят только утром.","explain_ky":"Туура эмес: good morning эртең менен гана айтылат."},{"id":"b","label":"Hello","explain_ru":"Верно: hello подходит утром, днём и вечером, знакомым и незнакомым людям.","explain_ky":"Туура: hello эртең менен да, күндүз да, кечинде да, тааныш да, бейтааныш адамга да айтылат."},{"id":"c","label":"Good evening","explain_ru":"Неверно: good evening — приветствие только для вечера.","explain_ky":"Туура эмес: good evening кечинде гана айтылуучу саламдашуу."},{"id":"d","label":"Good night","explain_ru":"Неверно: good night — прощание перед сном, а не приветствие.","explain_ky":"Туура эмес: good night — уктаар алдындагы коштошуу, саламдашуу эмес."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('48a8568c-ef7f-555b-8741-016f8756b5f7', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e02', 2, 'choice', '{"prompt_en":"— What''s your name? — ___","options":[{"id":"a","label":"I''m fine.","explain_ru":"Неверно: I''m fine — ответ на вопрос How are you? («как дела?»), а не на вопрос об имени.","explain_ky":"Туура эмес: I''m fine — How are you? («кандайсың?») деген суроонун жообу, ат жөнүндө эмес."},{"id":"b","label":"My name is Aidana.","explain_ru":"Верно: на вопрос об имени отвечают My name is… или I''m…","explain_ky":"Туура: ат суралганда My name is… же I''m… деп жооп беришет."},{"id":"c","label":"Good night.","explain_ru":"Неверно: good night — прощание перед сном, имя в нём не звучит.","explain_ky":"Туура эмес: good night — уктаар алдындагы коштошуу, анда ат айтылбайт."},{"id":"d","label":"Thank you.","explain_ru":"Неверно: thank you — «спасибо», это благодарность, а не ответ про имя.","explain_ky":"Туура эмес: thank you — «рахмат», бул ыраазычылык, ат жөнүндө жооп эмес."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('018fed91-abcf-53f6-86aa-f32c455ace26', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e03', 3, 'choice', '{"prompt_ru":"Что означает фраза Nice to meet you?","prompt_ky":"Nice to meet you деген фраза эмнени билдирет?","options":[{"id":"a","label_ru":"Приятно познакомиться","label_ky":"Таанышканыма кубанычтамын","explain_ru":"Верно: эту фразу говорят сразу после знакомства.","explain_ky":"Туура: бул фраза таанышкандан кийин дароо айтылат."},{"id":"b","label_ru":"Как дела?","label_ky":"Кандайсың?","explain_ru":"Неверно: «как дела?» — это How are you?","explain_ky":"Туура эмес: «кандайсың?» — англисче How are you?"},{"id":"c","label_ru":"До свидания","label_ky":"Кош болуңуз","explain_ru":"Неверно: «до свидания» — это Goodbye.","explain_ky":"Туура эмес: «кош болуңуз» — англисче Goodbye."},{"id":"d","label_ru":"Доброе утро","label_ky":"Кутман таң","explain_ru":"Неверно: «доброе утро» — это Good morning.","explain_ky":"Туура эмес: «кутман таң» — англисче Good morning."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('07f3a07d-f993-5ded-8a0e-857ba655eaa8', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e04', 4, 'matching', '{"instruction_ru":"Соедините фразу с переводом.","instruction_ky":"Фразаны котормосу менен дал келтириңиз.","pairs":[{"left_en":"Hello","right_ru":"Здравствуйте","right_ky":"Саламатсызбы"},{"left_en":"Good morning","right_ru":"Доброе утро","right_ky":"Кутман таң"},{"left_en":"Good night","right_ru":"Спокойной ночи","right_ky":"Жакшы жат"},{"left_en":"How are you?","right_ru":"Как дела?","right_ky":"Кандайсың?"},{"left_en":"Nice to meet you","right_ru":"Приятно познакомиться","right_ky":"Таанышканыма кубанычтамын"}],"explain_ru":"Самая коварная пара — good night: это не «добрый вечер», а пожелание перед сном. «Добрый вечер» — good evening.","explain_ky":"Эң алдамчы жуп — good night: бул «кутман кеч» эмес, уктаар алдында айтылат. «Кутман кеч» — good evening."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('4f69dabd-b675-5a0f-873f-3889811b3366', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e05', 5, 'choice', '{"prompt_en":"— How are you? — ___","options":[{"id":"a","label":"I''m fine, thanks.","explain_ru":"Верно: на How are you? отвечают I''m fine / I''m OK, thanks.","explain_ky":"Туура: How are you? дегенге I''m fine / I''m OK, thanks деп жооп беришет."},{"id":"b","label":"My name is Nurlan.","explain_ru":"Неверно: имя называют в ответ на What''s your name?, а здесь спросили «как дела?».","explain_ky":"Туура эмес: ат What''s your name? дегенге айтылат, бул жерде «кандайсың?» деп сурашты."},{"id":"c","label":"Nice to meet you.","explain_ru":"Неверно: так говорят при знакомстве, а не в ответ на «как дела?».","explain_ky":"Туура эмес: бул фраза таанышканда айтылат, «кандайсың?» деген суроого эмес."},{"id":"d","label":"Goodbye.","explain_ru":"Неверно: goodbye — прощание, разговор только начинается.","explain_ky":"Туура эмес: goodbye — коштошуу, сүйлөшүү эми эле башталып жатат."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('9fec39a7-df20-5158-8ace-b520381045c2', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e06', 6, 'short_answer', '{"prompt_ru":"Напишите по-английски: «Меня зовут Айдана».","prompt_ky":"Англисче жазыңыз: «Менин атым Айдана».","accepted":["My name is Aidana","My name is Aidana.","I''m Aidana","I''m Aidana.","I am Aidana","I am Aidana."],"explain_ru":"My name is Aidana. Короткий вариант — I''m Aidana. Частая ошибка — пропустить is: в английском связка обязательна.","explain_ky":"My name is Aidana. Кыска варианты — I''m Aidana. Көп кетчү ката — is этишин түшүрүп коюу: англисчеде ал милдеттүү."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('42d2067b-ad07-5e6b-8273-76b8f3f714c4', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e07', 7, 'choice', '{"prompt_ru":"Выберите фразу для прощания.","prompt_ky":"Коштошуу үчүн фразаны тандаңыз.","options":[{"id":"a","label":"Hello","explain_ru":"Неверно: hello — приветствие при встрече.","explain_ky":"Туура эмес: hello — жолукканда айтылуучу саламдашуу."},{"id":"b","label":"Hi","explain_ru":"Неверно: hi — тоже приветствие, как hello, только дружеское.","explain_ky":"Туура эмес: hi да саламдашуу, hello сыяктуу, бирок достук мааниде."},{"id":"c","label":"Goodbye","explain_ru":"Верно: goodbye говорят, когда уходят. Короткий вариант — bye.","explain_ky":"Туура: goodbye кетип жатканда айтылат. Кыска варианты — bye."},{"id":"d","label":"How are you?","explain_ru":"Неверно: это вопрос «как дела?», его задают в начале разговора.","explain_ky":"Туура эмес: бул «кандайсың?» деген суроо, ал сүйлөшүүнүн башында берилет."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('bf41bb1f-34cc-5ded-87de-37091b1e993b', '87c8be87-fcc1-5480-8de4-1b5731a87de0', 'en-m1-l01-e08', 8, 'choice', '{"prompt_ru":"Вы встречаете учителя в девять утра. Что вы скажете?","prompt_ky":"Мугалимди эртең мененки саат тогузда жолуктурдуңуз. Эмне дейсиз?","options":[{"id":"a","label":"Good night.","explain_ru":"Неверно: good night говорят перед сном, а не при встрече утром.","explain_ky":"Туура эмес: good night уктаар алдында айтылат, эртең менен жолукканда эмес."},{"id":"b","label":"Good morning.","explain_ru":"Верно: утром при встрече говорят good morning.","explain_ky":"Туура: эртең менен жолукканда good morning дешет."},{"id":"c","label":"Good evening.","explain_ru":"Неверно: good evening — вечернее приветствие, а сейчас утро.","explain_ky":"Туура эмес: good evening — кечки саламдашуу, азыр эртең менен."},{"id":"d","label":"Bye.","explain_ru":"Неверно: bye — прощание, а вы только встретились.","explain_ky":"Туура эмес: bye — коштошуу, сиз эми эле жолуктуңуз."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('030eb00c-c994-5867-831d-b92931fdc2af', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l02', 2, '{"title_ru":"Алфавит, звуки и spelling имени","title_ky":"Алфавит, тыбыштар жана атты тамгалап айтуу","goal_ru":"Называть буквы английского алфавита и диктовать своё имя по буквам.","goal_ky":"Англис алфавитинин тамгаларын атап, өз атыңды тамгалап айтасың."}'::JSONB, '[{"text_ru":"В английском алфавите 26 букв. У буквы есть имя — по нему её называют при диктовке — и звук в слове. Буква B называется «би», а в слове book звучит как «б».","text_ky":"Англис алфавитинде 26 тамга бар. Тамганын аты болот — айтып берүүдө ошону колдонушат — жана сөздөгү тыбышы болот. B тамгасынын аты «би», ал эми book сөзүндө «б» болуп угулат.","examples":[{"en":"A, B, C, D, E","ru":"эй, би, си, ди, и","ky":"эй, би, си, ди, и"},{"en":"book","ru":"книга — буква B здесь звучит как «б»","ky":"китеп — B тамгасы бул жерде «б» болуп угулат"}]},{"text_ru":"Гласные буквы — a, e, i, o, u, их имена: «эй», «и», «ай», «оу», «ю». Остальная 21 буква — согласные.","text_ky":"Үндүү тамгалар — a, e, i, o, u, алардын аттары: «эй», «и», «ай», «оу», «ю». Калган 21 тамга — үнсүздөр.","examples":[{"en":"a, e, i, o, u","ru":"эй, и, ай, оу, ю","ky":"эй, и, ай, оу, ю"},{"en":"name","ru":"имя — в этом слове гласные a и e","ky":"ат — бул сөздө a жана e үндүүлөрү бар"}]},{"text_ru":"Продиктовать имя или слово по буквам просят вопросом How do you spell it? В ответ буквы называют по одной.","text_ky":"Атты же сөздү тамгалап айтып берүүнү How do you spell it? деген суроо менен сурашат. Жоопто тамгалар бирден аталат.","examples":[{"en":"— How do you spell your name? — A-I-D-A-N-A.","ru":"— Как пишется твоё имя? — Эй-ай-ди-эй-эн-эй.","ky":"— Атың кандай жазылат? — Эй-ай-ди-эй-эн-эй."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('738be956-707b-5a8b-8942-d1de45b1a68d', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e01', 1, 'choice', '{"prompt_ru":"Сколько букв в английском алфавите?","prompt_ky":"Англис алфавитинде канча тамга бар?","options":[{"id":"a","label":"24","explain_ru":"Неверно: в английском алфавите на две буквы больше — 26.","explain_ky":"Туура эмес: англис алфавитинде эки тамга көп — 26."},{"id":"b","label":"26","explain_ru":"Верно: 26 букв — 5 гласных и 21 согласная.","explain_ky":"Туура: 26 тамга — 5 үндүү жана 21 үнсүз."},{"id":"c","label":"28","explain_ru":"Неверно: букв ровно 26.","explain_ky":"Туура эмес: тамгалар так 26."},{"id":"d","label":"33","explain_ru":"Неверно: 33 буквы — в русском алфавите; в английском 26.","explain_ky":"Туура эмес: 33 тамга — орус алфавитинде (кыргызчада 36); англисчеде 26."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('c1a13a65-1d6a-5769-8568-8c2a77451bc5', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e02', 2, 'choice', '{"prompt_ru":"Какая буква называется «джей»?","prompt_ky":"Кайсы тамганын аты «джей»?","options":[{"id":"a","label":"G","explain_ru":"Неверно: G называется «джи». «Джи» и «джей» звучат похоже — это самая частая путаница.","explain_ky":"Туура эмес: G тамгасынын аты «джи». «Джи» менен «джей» окшош угулат — бул эң көп чаташуу."},{"id":"b","label":"J","explain_ru":"Верно: J — «джей».","explain_ky":"Туура: J — «джей»."},{"id":"c","label":"Y","explain_ru":"Неверно: Y называется «уай».","explain_ky":"Туура эмес: Y тамгасынын аты «уай»."},{"id":"d","label":"I","explain_ru":"Неверно: I называется «ай».","explain_ky":"Туура эмес: I тамгасынын аты «ай»."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('0573ac98-de80-5e41-8737-73a0d63ba6ac', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e03', 3, 'choice', '{"prompt_ru":"Выберите строку, в которой только гласные буквы.","prompt_ky":"Үндүү тамгалар гана турган сапты тандаңыз.","options":[{"id":"a","label":"a, e, i, o, u","explain_ru":"Верно: это все пять гласных букв английского алфавита.","explain_ky":"Туура: бул англис алфавитинин беш үндүү тамгасы."},{"id":"b","label":"b, c, d, f, g","explain_ru":"Неверно: здесь все буквы согласные.","explain_ky":"Туура эмес: бул саптагы тамгалардын баары үнсүз."},{"id":"c","label":"a, b, c, d, e","explain_ru":"Неверно: a и e — гласные, но b, c, d — согласные.","explain_ky":"Туура эмес: a менен e үндүү, бирок b, c, d — үнсүздөр."},{"id":"d","label":"e, u, b, k, t","explain_ru":"Неверно: e и u — гласные, но b, k, t — согласные.","explain_ky":"Туура эмес: e менен u үндүү, бирок b, k, t — үнсүздөр."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('c7933099-bf9e-5229-8c51-82d61b0588c4', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e04', 4, 'matching', '{"instruction_ru":"Соедините букву с её именем.","instruction_ky":"Тамганы аты менен дал келтириңиз.","pairs":[{"left_en":"A","right_ru":"эй","right_ky":"эй"},{"left_en":"E","right_ru":"и","right_ky":"и"},{"left_en":"I","right_ru":"ай","right_ky":"ай"},{"left_en":"G","right_ru":"джи","right_ky":"джи"},{"left_en":"H","right_ru":"эйч","right_ky":"эйч"}],"explain_ru":"Чаще всего путают E («и») и I («ай»): имя буквы E звучит как русская «и». Ещё одна пара-ловушка — G («джи») и J («джей»).","explain_ky":"Көбүнчө E («и») менен I («ай») чаташтырылат: E тамгасынын аты «и» болуп угулат. Дагы бир алдамчы жуп — G («джи») менен J («джей»)."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('b331d300-a91e-51db-8807-fd46b13b3d61', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e05', 5, 'short_answer', '{"prompt_ru":"Запишите слово, которое продиктовали по буквам: B-O-O-K.","prompt_ky":"Тамгалап айтылган сөздү жазыңыз: B-O-O-K.","accepted":["book","Book","BOOK"],"explain_ru":"B-O-O-K — book («книга»). Двойная O в этом слове читается как «у».","explain_ky":"B-O-O-K — book («китеп»). Бул сөздөгү кош O «у» болуп окулат."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('167a6cb4-c6fc-574e-8042-b141fdf29703', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e06', 6, 'choice', '{"prompt_en":"— How do you spell your name? — ___","options":[{"id":"a","label":"My name is Timur.","explain_ru":"Неверно: так называют имя целиком, а спросили, как оно пишется по буквам.","explain_ky":"Туура эмес: мында ат бүтүн айтылды, ал эми суроо аттын тамгалап жазылышы жөнүндө болчу."},{"id":"b","label":"T-I-M-U-R.","explain_ru":"Верно: на How do you spell…? называют буквы по одной.","explain_ky":"Туура: How do you spell…? дегенге тамгалар бирден аталат."},{"id":"c","label":"I''m fine, thanks.","explain_ru":"Неверно: это ответ на How are you? («как дела?»).","explain_ky":"Туура эмес: бул How are you? («кандайсың?») деген суроонун жообу."},{"id":"d","label":"Nice to meet you.","explain_ru":"Неверно: эту фразу говорят при знакомстве, буквы в ней не называют.","explain_ky":"Туура эмес: бул фраза таанышканда айтылат, анда тамгалар аталбайт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('b6d11293-cd1d-5216-83d7-6f975f9d8337', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e07', 7, 'choice', '{"prompt_ru":"В каком слове есть буква C?","prompt_ky":"Кайсы сөздө C тамгасы бар?","options":[{"id":"a","label":"cat","explain_ru":"Верно: cat начинается с буквы C — «си».","explain_ky":"Туура: cat сөзү C — «си» тамгасынан башталат."},{"id":"b","label":"dog","explain_ru":"Неверно: dog состоит из букв D, O, G.","explain_ky":"Туура эмес: dog сөзү D, O, G тамгаларынан турат."},{"id":"c","label":"pen","explain_ru":"Неверно: pen состоит из букв P, E, N.","explain_ky":"Туура эмес: pen сөзү P, E, N тамгаларынан турат."},{"id":"d","label":"sun","explain_ru":"Неверно: sun состоит из букв S, U, N; S — «эс», а не «си».","explain_ky":"Туура эмес: sun сөзү S, U, N тамгаларынан турат; S — «эс», «си» эмес."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('ba8bcc15-0da9-5381-8d23-3f6415253cf0', '030eb00c-c994-5867-831d-b92931fdc2af', 'en-m1-l02-e08', 8, 'short_answer', '{"prompt_ru":"Продиктуйте слово name по буквам. Пишите заглавные буквы через дефис, например: C-A-T.","prompt_ky":"Name сөзүн тамгалап жазыңыз. Баш тамгаларды дефис менен жазыңыз, мисалы: C-A-T.","accepted":["N-A-M-E","n-a-m-e"],"explain_ru":"Name пишется N-A-M-E: «эн-эй-эм-и». Последняя буква — E («и»), хотя в слове она почти не слышна.","explain_ky":"Name сөзү N-A-M-E деп жазылат: «эн-эй-эм-и». Акыркы тамга — E («и»), сөздө ал дээрлик угулбаса да жазылат."}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('395d23b1-6f33-51af-88fe-5373f11e97a4', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l03', 3, '{"title_ru":"Числа, даты, время","title_ky":"Сандар, даталар, убакыт","goal_ru":"Называть числа, дни недели и время по-английски.","goal_ky":"Сандарды, апта күндөрүн жана убакытты англисче айтасың."}'::JSONB, '[{"text_ru":"Числа от одного до двенадцати — отдельные слова, их запоминают целиком: one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve.","text_ky":"Бирден он экиге чейинки сандар — өзүнчө сөздөр, аларды бүтүн жаттап алышат: one, two, three, four, five, six, seven, eight, nine, ten, eleven, twelve.","examples":[{"en":"one, two, three, four, five, six","ru":"1, 2, 3, 4, 5, 6","ky":"1, 2, 3, 4, 5, 6"},{"en":"seven, eight, nine, ten, eleven, twelve","ru":"7, 8, 9, 10, 11, 12","ky":"7, 8, 9, 10, 11, 12"}]},{"text_ru":"Числа 13–19 оканчиваются на -teen: thirteen, fourteen, fifteen… Десятки оканчиваются на -ty: twenty (20), thirty (30), forty (40), fifty (50). На слух -teen и -ty легко перепутать: thirteen — 13, thirty — 30.","text_ky":"13–19 сандары -teen менен бүтөт: thirteen, fourteen, fifteen… Ондуктар -ty менен бүтөт: twenty (20), thirty (30), forty (40), fifty (50). Угууда -teen менен -ty оңой чаташат: thirteen — 13, thirty — 30.","examples":[{"en":"thirteen — thirty","ru":"13 — 30","ky":"13 — 30"},{"en":"fifteen — fifty","ru":"15 — 50","ky":"15 — 50"}]},{"text_ru":"Дни недели: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. Про время спрашивают What time is it? Ровный час: It''s three o''clock. Месяцы тоже пригодятся: год начинается с January.","text_ky":"Апта күндөрү: Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday. Убакытты What time is it? деп сурашат. Так саат: It''s three o''clock. Айлар да керек болот: жыл January менен башталат.","examples":[{"en":"— What time is it? — It''s nine o''clock.","ru":"— Сколько времени? — Девять часов.","ky":"— Саат канча? — Саат тогуз."},{"en":"Monday, Tuesday, Wednesday","ru":"понедельник, вторник, среда","ky":"дүйшөмбү, шейшемби, шаршемби"},{"en":"January is the first month of the year.","ru":"Январь — первый месяц года.","ky":"Январь — жылдын биринчи айы."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('6e355766-4cf0-53ad-8548-c79748b485b2', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e01', 1, 'choice', '{"prompt_ru":"Выберите число thirteen.","prompt_ky":"Thirteen санын тандаңыз.","options":[{"id":"a","label":"3","explain_ru":"Неверно: 3 — three, без окончания.","explain_ky":"Туура эмес: 3 — three, мүчөсүз."},{"id":"b","label":"13","explain_ru":"Верно: -teen — это 13–19, thirteen — 13.","explain_ky":"Туура: -teen — 13–19 сандары, thirteen — 13."},{"id":"c","label":"30","explain_ru":"Неверно: 30 — thirty, с окончанием -ty, а не -teen.","explain_ky":"Туура эмес: 30 — thirty, -teen эмес, -ty мүчөсү менен."},{"id":"d","label":"33","explain_ru":"Неверно: 33 — thirty-three, это составное число из thirty и three.","explain_ky":"Туура эмес: 33 — thirty-three, ал thirty жана three сандарынан куралат."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('63ec9233-48b8-5167-84c2-c8271217fb49', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e02', 2, 'choice', '{"prompt_en":"Ten plus three is ___.","options":[{"id":"a","label":"thirteen","explain_ru":"Верно: 10 + 3 = 13, thirteen.","explain_ky":"Туура: 10 + 3 = 13, thirteen."},{"id":"b","label":"thirty","explain_ru":"Неверно: thirty — 30; для 13 нужно окончание -teen.","explain_ky":"Туура эмес: thirty — 30; 13 үчүн -teen мүчөсү керек."},{"id":"c","label":"twenty","explain_ru":"Неверно: twenty — 20, а 10 + 3 = 13.","explain_ky":"Туура эмес: twenty — 20, ал эми 10 + 3 = 13."},{"id":"d","label":"three","explain_ru":"Неверно: three — 3, а сумма равна 13.","explain_ky":"Туура эмес: three — 3, суммасы болсо 13."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('d8d50adc-1990-5e9d-85cc-70cfe029d96d', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e03', 3, 'matching', '{"instruction_ru":"Соедините число со словом.","instruction_ky":"Санды сөзү менен дал келтириңиз.","pairs":[{"left_en":"two","right_ru":"2","right_ky":"2"},{"left_en":"twelve","right_ru":"12","right_ky":"12"},{"left_en":"fifteen","right_ru":"15","right_ky":"15"},{"left_en":"twenty","right_ru":"20","right_ky":"20"},{"left_en":"fifty","right_ru":"50","right_ky":"50"}],"explain_ru":"Ловушка — fifteen (15) и fifty (50): различаются только окончанием, -teen против -ty.","explain_ky":"Алдамчы жуп — fifteen (15) менен fifty (50): айырмасы мүчөдө гана, -teen жана -ty."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('e5c207ec-81e7-5694-8c94-19d1dfc13da7', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e04', 4, 'choice', '{"prompt_ru":"Какой день идёт после Monday?","prompt_ky":"Monday күнүнөн кийин кайсы күн келет?","options":[{"id":"a","label":"Sunday","explain_ru":"Неверно: Sunday (воскресенье) идёт перед Monday, а не после.","explain_ky":"Туура эмес: Sunday (жекшемби) Monday күнүнөн мурда келет, кийин эмес."},{"id":"b","label":"Tuesday","explain_ru":"Верно: после Monday (понедельник) идёт Tuesday (вторник).","explain_ky":"Туура: Monday (дүйшөмбү) күнүнөн кийин Tuesday (шейшемби) келет."},{"id":"c","label":"Thursday","explain_ru":"Неверно: Thursday — четверг; его часто путают с Tuesday из-за похожего написания.","explain_ky":"Туура эмес: Thursday — бейшемби; жазылышы окшош болгондуктан аны Tuesday менен көп чаташтырышат."},{"id":"d","label":"Wednesday","explain_ru":"Неверно: Wednesday — среда, она идёт после вторника.","explain_ky":"Туура эмес: Wednesday — шаршемби, ал шейшембиден кийин келет."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('ebeb74f8-291e-525a-8613-778e6418529b', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e05', 5, 'choice', '{"prompt_en":"— What time is it? — ___","options":[{"id":"a","label":"It''s Monday.","explain_ru":"Неверно: Monday — день недели; спросили про время, а не про день.","explain_ky":"Туура эмес: Monday — апта күнү; суроо убакыт жөнүндө болчу, күн жөнүндө эмес."},{"id":"b","label":"It''s three o''clock.","explain_ru":"Верно: на вопрос о времени отвечают It''s … o''clock.","explain_ky":"Туура: убакыт суралганда It''s … o''clock деп жооп беришет."},{"id":"c","label":"It''s May.","explain_ru":"Неверно: May — месяц май, а не время на часах.","explain_ky":"Туура эмес: May — май айы, сааттагы убакыт эмес."},{"id":"d","label":"I''m ten.","explain_ru":"Неверно: I''m ten — «мне десять лет», это ответ о возрасте.","explain_ky":"Туура эмес: I''m ten — «мен ондомун», бул жаш жөнүндө жооп."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('a6a5e949-bfa2-5da6-869c-c20d7699134c', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e06', 6, 'short_answer', '{"prompt_ru":"Напишите цифрами: seventeen.","prompt_ky":"Цифра менен жазыңыз: seventeen.","accepted":["17"],"explain_ru":"Seventeen — 17: seven (7) + -teen. Seventy — это 70.","explain_ky":"Seventeen — 17: seven (7) + -teen. Seventy болсо — 70."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('b56a5104-4686-5f06-84c5-724c2046eca8', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e07', 7, 'choice', '{"prompt_ru":"Часы показывают ровно 9:00. Выберите подпись.","prompt_ky":"Саат так 9:00 көрсөтүп турат. Туура жазууну тандаңыз.","options":[{"id":"a","label":"It''s nine o''clock.","explain_ru":"Верно: ровный час называют nine o''clock.","explain_ky":"Туура: так саатты nine o''clock дешет."},{"id":"b","label":"It''s nine thirty.","explain_ru":"Неверно: nine thirty — 9:30, а на часах ровно 9:00.","explain_ky":"Туура эмес: nine thirty — 9:30, саат болсо так 9:00 көрсөтүп турат."},{"id":"c","label":"It''s Monday.","explain_ru":"Неверно: Monday — день недели, а не время.","explain_ky":"Туура эмес: Monday — апта күнү, убакыт эмес."},{"id":"d","label":"It''s nineteen o''clock.","explain_ru":"Неверно: с o''clock используют числа 1–12; nineteen (19) так не говорят.","explain_ky":"Туура эмес: o''clock менен 1–12 сандары айтылат; nineteen (19) мындай колдонулбайт."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('313a15e4-f702-54f9-8e00-d599ba51c7b9', '395d23b1-6f33-51af-88fe-5373f11e97a4', 'en-m1-l03-e08', 8, 'choice', '{"prompt_ru":"Какой месяц идёт в году первым?","prompt_ky":"Жылдын биринчи айы кайсы?","options":[{"id":"a","label":"December","explain_ru":"Неверно: December (декабрь) — последний, двенадцатый месяц.","explain_ky":"Туура эмес: December (декабрь) — акыркы, он экинчи ай."},{"id":"b","label":"January","explain_ru":"Верно: January (январь) — первый месяц года.","explain_ky":"Туура: January (январь) — жылдын биринчи айы."},{"id":"c","label":"February","explain_ru":"Неверно: February (февраль) — второй месяц.","explain_ky":"Туура эмес: February (февраль) — экинчи ай."},{"id":"d","label":"March","explain_ru":"Неверно: March (март) — третий месяц.","explain_ky":"Туура эмес: March (март) — үчүнчү ай."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('3ae94907-c32a-5661-8670-6e9768ae5415', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l04', 4, '{"title_ru":"Рассказ о себе и семье","title_ky":"Өзүң жана үй-бүлөң жөнүндө","goal_ru":"Сказать, как вас зовут и сколько вам лет, и представить свою семью.","goal_ky":"Атыңды, жашыңды айтып, үй-бүлөңдү тааныштырасың."}'::JSONB, '[{"text_ru":"«Я — студент», «мне 16» — в английском для этого нужен глагол be. После I — форма am: I am a student. I am sixteen years old. Возраст спрашивают How old are you?","text_ky":"«Мен студентмин», «мен он алтыдамын» — англисчеде бул үчүн be этиши керек. I дегенден кийин am формасы келет: I am a student. I am sixteen years old. Жашты How old are you? деп сурашат.","examples":[{"en":"I am a student.","ru":"Я студент.","ky":"Мен студентмин."},{"en":"I am sixteen years old.","ru":"Мне шестнадцать лет.","ky":"Мен он алтыдамын."},{"en":"— How old are you? — I''m fifteen.","ru":"— Сколько тебе лет? — Пятнадцать.","ky":"— Канчадасың? — Он бештемин."}]},{"text_ru":"Слова семьи: mother — мама, father — папа, sister — сестра, brother — брат, grandmother — бабушка, grandfather — дедушка, parents — родители.","text_ky":"Үй-бүлө сөздөрү: mother — апа, father — ата, sister — эже/карындаш, brother — байке/ини, grandmother — чоң апа, grandfather — чоң ата, parents — ата-эне.","examples":[{"en":"mother, father, parents","ru":"мама, папа, родители","ky":"апа, ата, ата-эне"},{"en":"sister, brother","ru":"сестра, брат","ky":"эже/карындаш, байке/ини"}]},{"text_ru":"Представить родных: This is my mother — «это моя мама». Сказать, кто у вас есть: I have a brother. После he/she — форма is, после we/they/you — are: My sister is ten. We are a big family.","text_ky":"Жакындарыңды тааныштыруу: This is my mother — «бул менин апам». Кимиң бар экенин айтуу: I have a brother. He/she дегенден кийин is, we/they/you дегенден кийин are келет: My sister is ten. We are a big family.","examples":[{"en":"This is my mother.","ru":"Это моя мама.","ky":"Бул менин апам."},{"en":"I have a brother.","ru":"У меня есть брат.","ky":"Менин иним бар."},{"en":"My sister is ten years old.","ru":"Моей сестре десять лет.","ky":"Менин карындашым ондо."},{"en":"We are a big family.","ru":"Мы большая семья.","ky":"Биз чоң үй-бүлөбүз."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('0fe1e3bf-ac3b-5ef7-8882-1bc8f5831c67', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e01', 1, 'choice', '{"prompt_en":"I ___ sixteen years old.","options":[{"id":"a","label":"am","explain_ru":"Верно: после I всегда форма am.","explain_ky":"Туура: I дегенден кийин ар дайым am формасы келет."},{"id":"b","label":"is","explain_ru":"Неверно: is используется после he, she, it, а не после I.","explain_ky":"Туура эмес: is формасы he, she, it дегенден кийин колдонулат, I менен эмес."},{"id":"c","label":"are","explain_ru":"Неверно: are идёт после you, we, they.","explain_ky":"Туура эмес: are формасы you, we, they дегенден кийин келет."},{"id":"d","label":"be","explain_ru":"Неверно: be — начальная форма; в предложении она меняется на am/is/are.","explain_ky":"Туура эмес: be — баштапкы форма; сүйлөмдө ал am/is/are болуп өзгөрөт."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('b8fe2de1-3d5f-531d-88d5-6fd66bb9772c', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e02', 2, 'matching', '{"instruction_ru":"Соедините слово с переводом.","instruction_ky":"Сөздү котормосу менен дал келтириңиз.","pairs":[{"left_en":"mother","right_ru":"мама","right_ky":"апа"},{"left_en":"father","right_ru":"папа","right_ky":"ата"},{"left_en":"sister","right_ru":"сестра","right_ky":"эже / карындаш"},{"left_en":"brother","right_ru":"брат","right_ky":"байке / ини"},{"left_en":"grandmother","right_ru":"бабушка","right_ky":"чоң апа"}],"explain_ru":"Grandmother — «бабушка»: grand- добавляется к mother и father для старшего поколения.","explain_ky":"Grandmother — «чоң апа»: улуу муун үчүн mother жана father сөздөрүнө grand- кошулат."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('960bab80-e737-52c0-83f4-7dadf8b3ed87', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e03', 3, 'choice', '{"prompt_ru":"Как сказать по-английски: «Это моя мама»?","prompt_ky":"«Бул менин апам» дегенди англисче кантип айтабыз?","options":[{"id":"a","label":"This is my mother.","explain_ru":"Верно: This is + my + слово семьи.","explain_ky":"Туура: This is + my + үй-бүлө сөзү."},{"id":"b","label":"This my mother is.","explain_ru":"Неверно: is должен стоять сразу после this, а не в конце.","explain_ky":"Туура эмес: is этиши this сөзүнөн кийин эле турушу керек, сүйлөмдүн аягында эмес."},{"id":"c","label":"I am my mother.","explain_ru":"Неверно: получилось «я — моя мама». Представляя другого человека, начинают с This is…","explain_ky":"Туура эмес: «мен өз апаммын» болуп калды. Башка адамды тааныштырганда This is… деп башташат."},{"id":"d","label":"This is me mother.","explain_ru":"Неверно: нужно притяжательное my («моя»), а не me («меня, мне»).","explain_ky":"Туура эмес: бул жерде my («менин») керек, me («мени, мага») эмес."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('851b0315-98bc-5f02-87a2-d8582fb88228', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e04', 4, 'choice', '{"prompt_en":"— How old are you? — ___","options":[{"id":"a","label":"I''m fine.","explain_ru":"Неверно: I''m fine отвечает на How are you? («как дела?»); How old — вопрос о возрасте.","explain_ky":"Туура эмес: I''m fine — How are you? («кандайсың?») суроосунун жообу; How old — жаш жөнүндө суроо."},{"id":"b","label":"I''m fifteen.","explain_ru":"Верно: How old are you? — «сколько тебе лет?», ответ — число: I''m fifteen.","explain_ky":"Туура: How old are you? — «канчадасың?», жообу — сан: I''m fifteen."},{"id":"c","label":"I''m Aigerim.","explain_ru":"Неверно: имя называют в ответ на What''s your name?","explain_ky":"Туура эмес: ат What''s your name? суроосуна айтылат."},{"id":"d","label":"It''s five o''clock.","explain_ru":"Неверно: это ответ про время на часах, а не про возраст.","explain_ky":"Туура эмес: бул сааттагы убакыт жөнүндө жооп, жаш жөнүндө эмес."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('8d2c8b0d-5b0c-509b-8870-0df7e168ef5d', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e05', 5, 'short_answer', '{"prompt_ru":"Напишите по-английски: «У меня есть брат».","prompt_ky":"Англисче жазыңыз: «Менин иним бар».","accepted":["I have a brother","I have a brother.","I have got a brother","I have got a brother.","I''ve got a brother","I''ve got a brother."],"explain_ru":"I have a brother. Перед единственным числом нужен артикль a: не I have brother.","explain_ky":"I have a brother. Жекелик сандын алдында a артикли керек: I have brother деп айтылбайт."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('ea3d65c1-1d7f-5108-80c0-d8fcb20750d3', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e06', 6, 'choice', '{"prompt_en":"My sister ___ ten years old.","options":[{"id":"a","label":"am","explain_ru":"Неверно: am используется только после I.","explain_ky":"Туура эмес: am формасы I дегенден кийин гана колдонулат."},{"id":"b","label":"is","explain_ru":"Верно: my sister — это she, после неё форма is.","explain_ky":"Туура: my sister — бул she, андан кийин is формасы келет."},{"id":"c","label":"are","explain_ru":"Неверно: are идёт после you, we, they; здесь один человек — сестра.","explain_ky":"Туура эмес: are формасы you, we, they менен келет; бул жерде бир адам — карындаш."},{"id":"d","label":"have","explain_ru":"Неверно: have — «иметь»; возраст выражают глаголом be: she is ten.","explain_ky":"Туура эмес: have — «ээ болуу»; жаш be этиши менен айтылат: she is ten."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('abac1172-3b1f-5375-8ade-f696387112d1', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e07', 7, 'choice', '{"prompt_ru":"Выберите слово «родители».","prompt_ky":"«Ата-эне» деген сөздү тандаңыз.","options":[{"id":"a","label":"parents","explain_ru":"Верно: parents — родители, мама и папа вместе.","explain_ky":"Туура: parents — ата-эне, ата менен апа чогуу."},{"id":"b","label":"children","explain_ru":"Неверно: children — «дети».","explain_ky":"Туура эмес: children — «балдар»."},{"id":"c","label":"friends","explain_ru":"Неверно: friends — «друзья».","explain_ky":"Туура эмес: friends — «достор»."},{"id":"d","label":"teachers","explain_ru":"Неверно: teachers — «учителя».","explain_ky":"Туура эмес: teachers — «мугалимдер»."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('45c9f423-ab7f-5c23-8708-e0be1b85f788', '3ae94907-c32a-5661-8670-6e9768ae5415', 'en-m1-l04-e08', 8, 'choice', '{"prompt_en":"We ___ a big family.","options":[{"id":"a","label":"is","explain_ru":"Неверно: is — форма для he/she/it, а we — «мы».","explain_ky":"Туура эмес: is — he/she/it үчүн форма, we болсо — «биз»."},{"id":"b","label":"am","explain_ru":"Неверно: am бывает только после I.","explain_ky":"Туура эмес: am формасы I дегенден кийин гана болот."},{"id":"c","label":"are","explain_ru":"Верно: после we — форма are.","explain_ky":"Туура: we дегенден кийин are формасы келет."},{"id":"d","label":"be","explain_ru":"Неверно: be — начальная форма, в предложении нужна личная форма are.","explain_ky":"Туура эмес: be — баштапкы форма, сүйлөмдө are формасы керек."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l05', 5, '{"title_ru":"Школа и учёба","title_ky":"Мектеп жана окуу","goal_ru":"Использовать основные слова о школе, уроках и предметах.","goal_ky":"Мектеп, сабактар жана предметтер жөнүндө негизги сөздөрдү колдоносуң."}'::JSONB, '[{"text_ru":"Школьные слова: school — школа, lesson — урок, teacher — учитель, student — ученик, classroom — класс (кабинет), book — книга, notebook — тетрадь, pen — ручка.","text_ky":"Мектеп сөздөрү: school — мектеп, lesson — сабак, teacher — мугалим, student — окуучу, classroom — класс (кабинет), book — китеп, notebook — дептер, pen — калем сап.","examples":[{"en":"My school is big.","ru":"Моя школа большая.","ky":"Менин мектебим чоң."},{"en":"The teacher is in the classroom.","ru":"Учитель в классе.","ky":"Мугалим класста."}]},{"text_ru":"Предметы: maths — математика, English — английский, history — история, biology — биология, sport — физкультура.","text_ky":"Предметтер: maths — математика, English — англис тили, history — тарых, biology — биология, sport — дене тарбия.","examples":[{"en":"I have maths and English today.","ru":"Сегодня у меня математика и английский.","ky":"Бүгүн менде математика жана англис тили бар."}]},{"text_ru":"О себе и учёбе: I am a student. I study at school. Любимый предмет — favourite subject: My favourite subject is English.","text_ky":"Өзүң жана окуу жөнүндө: I am a student. I study at school. Сүйүктүү предмет — favourite subject: My favourite subject is English.","examples":[{"en":"I study at school.","ru":"Я учусь в школе.","ky":"Мен мектепте окуйм."},{"en":"My favourite subject is English.","ru":"Мой любимый предмет — английский.","ky":"Менин сүйүктүү предметим — англис тили."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('8e47a0d3-85de-517a-83f0-7e8b2f60d5b6', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e01', 1, 'matching', '{"instruction_ru":"Соедините слово с переводом.","instruction_ky":"Сөздү котормосу менен дал келтириңиз.","pairs":[{"left_en":"teacher","right_ru":"учитель","right_ky":"мугалим"},{"left_en":"student","right_ru":"ученик","right_ky":"окуучу"},{"left_en":"lesson","right_ru":"урок","right_ky":"сабак"},{"left_en":"classroom","right_ru":"класс (кабинет)","right_ky":"класс (кабинет)"},{"left_en":"notebook","right_ru":"тетрадь","right_ky":"дептер"}],"explain_ru":"Notebook — «тетрадь», хотя так же называют и ноутбук; book — «книга», note — «запись».","explain_ky":"Notebook — «дептер», бирок ноутбукту да ушинтип аташат; book — «китеп», note — «жазуу»."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('4d4c5c93-8a0b-5e83-8ea0-64314124a619', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e02', 2, 'choice', '{"prompt_ru":"Кто ведёт урок?","prompt_ky":"Сабакты ким өтөт?","options":[{"id":"a","label":"a student","explain_ru":"Неверно: student — ученик, он учится на уроке.","explain_ky":"Туура эмес: student — окуучу, ал сабакта окуйт."},{"id":"b","label":"a teacher","explain_ru":"Верно: teacher — учитель, он ведёт урок.","explain_ky":"Туура: teacher — мугалим, сабакты ал өтөт."},{"id":"c","label":"a brother","explain_ru":"Неверно: brother — «брат», это слово о семье, а не о школе.","explain_ky":"Туура эмес: brother — «байке/ини», бул үй-бүлө сөзү, мектеп сөзү эмес."},{"id":"d","label":"a doctor","explain_ru":"Неверно: doctor — «врач», он работает в больнице.","explain_ky":"Туура эмес: doctor — «дарыгер», ал ооруканада иштейт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('d684bfa9-d9b0-553a-852e-007d235785f2', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e03', 3, 'choice', '{"prompt_en":"My favourite subject ___ English.","options":[{"id":"a","label":"am","explain_ru":"Неверно: am используется только после I.","explain_ky":"Туура эмес: am формасы I дегенден кийин гана колдонулат."},{"id":"b","label":"is","explain_ru":"Верно: my favourite subject — это it (один предмет), после него is.","explain_ky":"Туура: my favourite subject — бул it (бир предмет), андан кийин is келет."},{"id":"c","label":"are","explain_ru":"Неверно: are нужно для множественного числа, а предмет один.","explain_ky":"Туура эмес: are көптүк сан үчүн керек, бул жерде предмет бирөө."},{"id":"d","label":"be","explain_ru":"Неверно: be — начальная форма; здесь нужна личная форма is.","explain_ky":"Туура эмес: be — баштапкы форма; бул жерде is формасы керек."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('cbe31ea7-ac03-5536-865a-4d66a5a33111', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e04', 4, 'choice', '{"prompt_ru":"На каком предмете изучают числа и счёт?","prompt_ky":"Кайсы предметте сандар жана эсеп окутулат?","options":[{"id":"a","label":"history","explain_ru":"Неверно: history — история, там изучают прошлое.","explain_ky":"Туура эмес: history — тарых, анда өткөн мезгил окутулат."},{"id":"b","label":"English","explain_ru":"Неверно: English — язык; числа там называют, но не изучают счёт.","explain_ky":"Туура эмес: English — тил; сандар аталганы менен эсеп окутулбайт."},{"id":"c","label":"maths","explain_ru":"Верно: maths — математика, наука о числах.","explain_ky":"Туура: maths — математика, сандар жөнүндөгү илим."},{"id":"d","label":"biology","explain_ru":"Неверно: biology — биология, наука о живой природе.","explain_ky":"Туура эмес: biology — биология, жандуу жаратылыш жөнүндөгү илим."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('caba15b6-1978-56dc-86c8-205c289283a3', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e05', 5, 'short_answer', '{"prompt_ru":"Напишите по-английски слово «книга».","prompt_ky":"«Китеп» деген сөздү англисче жазыңыз.","accepted":["book","a book","the book","Book"],"explain_ru":"Книга — book. Не путайте с notebook — «тетрадь».","explain_ky":"Китеп — book. Notebook — «дептер» деген сөз менен чаташтырбаңыз."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('7327368a-9c7d-55dc-8a34-c245794d57eb', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e06', 6, 'choice', '{"prompt_en":"You ___ a student.","options":[{"id":"a","label":"am","explain_ru":"Неверно: am бывает только после I; после you — are.","explain_ky":"Туура эмес: am формасы I дегенден кийин гана болот; you менен are келет."},{"id":"b","label":"is","explain_ru":"Неверно: is идёт после he/she/it.","explain_ky":"Туура эмес: is формасы he/she/it менен келет."},{"id":"c","label":"are","explain_ru":"Верно: после you всегда are, даже если речь об одном человеке.","explain_ky":"Туура: you дегенден кийин ар дайым are келет, бир адам жөнүндө болсо да."},{"id":"d","label":"be","explain_ru":"Неверно: be — начальная форма; в предложении нужна форма are.","explain_ky":"Туура эмес: be — баштапкы форма; сүйлөмдө are керек."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('6816d7b8-6d79-5fdd-8258-20e5e31d8646', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e07', 7, 'choice', '{"prompt_ru":"Что из этого — школьные принадлежности?","prompt_ky":"Булардын кайсынысы окуу куралдары?","options":[{"id":"a","label":"a pen and a notebook","explain_ru":"Верно: pen — ручка, notebook — тетрадь; их берут на урок.","explain_ky":"Туура: pen — калем сап, notebook — дептер; аларды сабакка алып барышат."},{"id":"b","label":"a mother and a father","explain_ru":"Неверно: mother и father — слова о семье.","explain_ky":"Туура эмес: mother жана father — үй-бүлө сөздөрү."},{"id":"c","label":"Monday and Tuesday","explain_ru":"Неверно: Monday и Tuesday — дни недели.","explain_ky":"Туура эмес: Monday жана Tuesday — апта күндөрү."},{"id":"d","label":"a cat and a dog","explain_ru":"Неверно: cat и dog — животные, кошка и собака.","explain_ky":"Туура эмес: cat жана dog — жаныбарлар, мышык менен ит."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('78a22ad2-44b2-50de-81d1-f7490c19ccfa', 'f549276e-6dd5-5cc6-8d24-41f814bc8c08', 'en-m1-l05-e08', 8, 'reading', '{"passage_en":"My name is Bekzat. I am a student. My school is big. I have five lessons today: maths, English, history, biology and sport. My favourite subject is English. My teacher is kind.","questions":[{"id":"en-m1-l05-e08-q1","prompt_en":"How many lessons does Bekzat have today?","options":[{"id":"a","label":"four","explain_ru":"Неверно: в тексте названо число five и перечислены пять предметов.","explain_ky":"Туура эмес: текстте five саны айтылып, беш предмет саналган."},{"id":"b","label":"five","explain_ru":"Верно: I have five lessons today — пять уроков.","explain_ky":"Туура: I have five lessons today — беш сабак."},{"id":"c","label":"six","explain_ru":"Неверно: six — 6, а в тексте five — 5.","explain_ky":"Туура эмес: six — 6, текстте болсо five — 5."},{"id":"d","label":"two","explain_ru":"Неверно: two — 2; в тексте перечислено пять предметов.","explain_ky":"Туура эмес: two — 2; текстте беш предмет саналган."}],"answer_index":1},{"id":"en-m1-l05-e08-q2","prompt_en":"What is Bekzat''s favourite subject?","options":[{"id":"a","label":"maths","explain_ru":"Неверно: maths есть в расписании, но любимым назван другой предмет.","explain_ky":"Туура эмес: maths расписаниеде бар, бирок сүйүктүү предмет катары башкасы аталган."},{"id":"b","label":"English","explain_ru":"Верно: My favourite subject is English.","explain_ky":"Туура: My favourite subject is English."},{"id":"c","label":"history","explain_ru":"Неверно: history только перечислена среди уроков дня.","explain_ky":"Туура эмес: history күндүн сабактарынын арасында гана аталган."},{"id":"d","label":"sport","explain_ru":"Неверно: sport есть в списке уроков, но не назван любимым.","explain_ky":"Туура эмес: sport сабактардын тизмесинде бар, бирок сүйүктүү деп аталган эмес."}],"answer_index":1}]}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l06', 6, '{"title_ru":"Простые вопросы: who, what, where, when","title_ky":"Жөнөкөй суроолор: who, what, where, when","goal_ru":"Задавать простые вопросы с who, what, where, when и понимать ответы.","goal_ky":"Who, what, where, when менен жөнөкөй суроолорду берип, жоопторун түшүнөсүң."}'::JSONB, '[{"text_ru":"Вопросительные слова: who — кто (о людях), what — что (о предметах), where — где (о месте), when — когда (о времени).","text_ky":"Суроо сөздөрү: who — ким (адамдар жөнүндө), what — эмне (заттар жөнүндө), where — кайда (орун жөнүндө), when — качан (убакыт жөнүндө).","examples":[{"en":"Who is this?","ru":"Кто это?","ky":"Бул ким?"},{"en":"What is this?","ru":"Что это?","ky":"Бул эмне?"},{"en":"Where is my book?","ru":"Где моя книга?","ky":"Менин китебим кайда?"},{"en":"When is the lesson?","ru":"Когда урок?","ky":"Сабак качан?"}]},{"text_ru":"Порядок простой: вопросительное слово + is/are + остальное. Ответ подсказывает вопрос: на where отвечают местом (It''s on the table), на when — временем (At nine o''clock), на who — человеком (This is my teacher).","text_ky":"Тартиби жөнөкөй: суроо сөзү + is/are + калганы. Жоопту суроо өзү айтып турат: where дегенге орун менен (It''s on the table), when дегенге убакыт менен (At nine o''clock), who дегенге адам менен (This is my teacher) жооп беришет.","examples":[{"en":"— Where is my pen? — It''s on the table.","ru":"— Где моя ручка? — На столе.","ky":"— Калем сабым кайда? — Үстөлдүн үстүндө."},{"en":"— When is the lesson? — At nine o''clock.","ru":"— Когда урок? — В девять.","ky":"— Сабак качан? — Саат тогузда."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('bd456d2b-721a-5a78-8cdc-354666fdd31e', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e01', 1, 'choice', '{"prompt_en":"— ___ is this? — This is my teacher.","options":[{"id":"a","label":"What","explain_ru":"Неверно: what спрашивает о предмете, а в ответе человек — учитель.","explain_ky":"Туура эмес: what зат жөнүндө сурайт, жоопто болсо адам — мугалим."},{"id":"b","label":"Who","explain_ru":"Верно: ответ называет человека, значит вопрос — who («кто»).","explain_ky":"Туура: жоопто адам аталат, демек суроо — who («ким»)."},{"id":"c","label":"Where","explain_ru":"Неверно: where — «где», ответ был бы о месте.","explain_ky":"Туура эмес: where — «кайда», жооп орун жөнүндө болмок."},{"id":"d","label":"When","explain_ru":"Неверно: when — «когда», ответ был бы о времени.","explain_ky":"Туура эмес: when — «качан», жооп убакыт жөнүндө болмок."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('198dd140-c8bf-5eea-806b-e6e0decbc3f8', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e02', 2, 'choice', '{"prompt_en":"— ___ is my pen? — It''s on the table.","options":[{"id":"a","label":"Who","explain_ru":"Неверно: who — «кто», а ответ говорит о месте.","explain_ky":"Туура эмес: who — «ким», жооп болсо орун жөнүндө."},{"id":"b","label":"What","explain_ru":"Неверно: what — «что»; предмет уже назван — ручка.","explain_ky":"Туура эмес: what — «эмне»; зат мурунтан белгилүү — калем сап."},{"id":"c","label":"Where","explain_ru":"Верно: ответ on the table («на столе») — о месте, вопрос — where.","explain_ky":"Туура: on the table («үстөлдүн үстүндө») деген жооп орун жөнүндө, суроо — where."},{"id":"d","label":"When","explain_ru":"Неверно: when — «когда», ответ был бы о времени.","explain_ky":"Туура эмес: when — «качан», жооп убакыт жөнүндө болмок."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('a662bf73-4165-5468-8663-f09ca16ac621', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e03', 3, 'choice', '{"prompt_en":"— ___ is the English lesson? — At nine o''clock.","options":[{"id":"a","label":"Who","explain_ru":"Неверно: who — «кто», а at nine o''clock — время.","explain_ky":"Туура эмес: who — «ким», at nine o''clock болсо — убакыт."},{"id":"b","label":"When","explain_ru":"Верно: ответ о времени (в девять) — вопрос when («когда»).","explain_ky":"Туура: жооп убакыт жөнүндө (саат тогузда) — суроо when («качан»)."},{"id":"c","label":"What","explain_ru":"Неверно: what — «что», а не «когда».","explain_ky":"Туура эмес: what — «эмне», «качан» эмес."},{"id":"d","label":"Where","explain_ru":"Неверно: where — «где»; ответ был бы о месте, например in the classroom.","explain_ky":"Туура эмес: where — «кайда»; жооп орун жөнүндө болмок, мисалы in the classroom."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('482b8005-f677-576a-8cb0-dd78cc3a6ede', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e04', 4, 'choice', '{"prompt_en":"— ___ is this? — It''s a notebook.","options":[{"id":"a","label":"What","explain_ru":"Верно: ответ называет предмет (тетрадь), вопрос — what («что»).","explain_ky":"Туура: жоопто зат аталат (дептер), суроо — what («эмне»)."},{"id":"b","label":"Who","explain_ru":"Неверно: who — о людях, а notebook — предмет.","explain_ky":"Туура эмес: who адамдар жөнүндө сурайт, notebook болсо — зат."},{"id":"c","label":"Where","explain_ru":"Неверно: where — «где», ответ был бы о месте.","explain_ky":"Туура эмес: where — «кайда», жооп орун жөнүндө болмок."},{"id":"d","label":"When","explain_ru":"Неверно: when — «когда», ответ был бы о времени.","explain_ky":"Туура эмес: when — «качан», жооп убакыт жөнүндө болмок."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('713163cb-762f-59d0-8c91-63c0633315e0', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e05', 5, 'matching', '{"instruction_ru":"Соедините вопросительное слово с переводом.","instruction_ky":"Суроо сөзүн котормосу менен дал келтириңиз.","pairs":[{"left_en":"who","right_ru":"кто","right_ky":"ким"},{"left_en":"what","right_ru":"что","right_ky":"эмне"},{"left_en":"where","right_ru":"где","right_ky":"кайда"},{"left_en":"when","right_ru":"когда","right_ky":"качан"}],"explain_ru":"Чаще всего путают where («где») и when («когда»): смотрите на конец слова — whe-RE — место, whe-N — время.","explain_ky":"Көбүнчө where («кайда») менен when («качан») чаташат: сөздүн аягын караңыз — whe-RE — орун, whe-N — убакыт."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('99b0a7c4-f89f-55b8-8bb2-76abb1c1a92d', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e06', 6, 'choice', '{"prompt_en":"Where ___ my books?","options":[{"id":"a","label":"is","explain_ru":"Неверно: books — множественное число, с ним нужна форма are.","explain_ky":"Туура эмес: books — көптүк сан, аны менен are формасы керек."},{"id":"b","label":"am","explain_ru":"Неверно: am используется только после I.","explain_ky":"Туура эмес: am формасы I дегенден кийин гана колдонулат."},{"id":"c","label":"are","explain_ru":"Верно: books — «книги», их много, поэтому are.","explain_ky":"Туура: books — «китептер», көптүк санда, ошондуктан are."},{"id":"d","label":"be","explain_ru":"Неверно: be — начальная форма, в вопросе нужна личная форма are.","explain_ky":"Туура эмес: be — баштапкы форма, суроодо are керек."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('5c370d1c-844f-5622-804c-f860d803eda1', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e07', 7, 'short_answer', '{"prompt_ru":"Напишите вопрос по-английски: «Кто это?»","prompt_ky":"Англисче суроо жазыңыз: «Бул ким?»","accepted":["Who is this?","Who is this","Who is it?","Who is it","Who''s this?","Who''s it?"],"explain_ru":"Who is this? Порядок: вопросительное слово who, затем is, затем this.","explain_ky":"Who is this? Тартиби: who суроо сөзү, андан кийин is, анан this."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('4127b918-bdd9-5227-8937-63b530a0e198', 'eac5c627-0bba-5df1-8ebb-84a2dd6394ac', 'en-m1-l06-e08', 8, 'choice', '{"prompt_en":"— When is your English lesson? — ___","options":[{"id":"a","label":"In the classroom.","explain_ru":"Неверно: in the classroom — ответ о месте, а when спрашивает о времени.","explain_ky":"Туура эмес: in the classroom — орун жөнүндө жооп, when болсо убакытты сурайт."},{"id":"b","label":"On Monday.","explain_ru":"Верно: on Monday («в понедельник») — ответ о времени.","explain_ky":"Туура: on Monday («дүйшөмбүдө») — убакыт жөнүндө жооп."},{"id":"c","label":"My teacher.","explain_ru":"Неверно: my teacher — ответ на вопрос who («кто»).","explain_ky":"Туура эмес: my teacher — who («ким») суроосунун жообу."},{"id":"d","label":"A book.","explain_ru":"Неверно: a book — ответ на вопрос what («что»).","explain_ky":"Туура эмес: a book — what («эмне») суроосунун жообу."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('33026e22-2c44-5d9a-8eb3-e394be53f94a', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l07', 7, '{"title_ru":"Быть и делать: настоящее время","title_ky":"Болуу жана иш-аракет: учур чак","goal_ru":"Различать am/is/are и глаголы действия и правильно добавлять -s после he/she.","goal_ky":"Am/is/are менен иш-аракет этиштерин айырмалап, he/she дегенден кийин -s мүчөсүн туура жалгайсың."}'::JSONB, '[{"text_ru":"Глагол be — «быть»: I am, he/she/it is, you/we/they are. Он связывает, кто есть кто или какой: I am a student. They are my friends.","text_ky":"Be этиши — «болуу»: I am, he/she/it is, you/we/they are. Ал ким экенин же кандай экенин байланыштырат: I am a student. They are my friends.","examples":[{"en":"I am a student.","ru":"Я студент.","ky":"Мен студентмин."},{"en":"She is my sister.","ru":"Она моя сестра.","ky":"Ал менин эжем."},{"en":"They are my friends.","ru":"Они мои друзья.","ky":"Алар менин досторум."}]},{"text_ru":"Обычные, регулярные действия — Present Simple: глагол стоит в простой форме, но после he/she/it к нему добавляется -s. I live in Bishkek. She lives in Osh.","text_ky":"Кадимки, дайыма боло турган иш-аракеттер — Present Simple: этиш жөнөкөй формада турат, бирок he/she/it дегенден кийин ага -s жалганат. I live in Bishkek. She lives in Osh.","examples":[{"en":"I live in Bishkek.","ru":"Я живу в Бишкеке.","ky":"Мен Бишкекте жашайм."},{"en":"She lives in Osh.","ru":"Она живёт в Оше.","ky":"Ал Ошто жашайт."},{"en":"They speak Kyrgyz.","ru":"Они говорят по-кыргызски.","ky":"Алар кыргызча сүйлөшөт."}]},{"text_ru":"В простом предложении — либо be, либо глагол действия, не оба сразу. «Я учу английский» — I study English. Сказать I am study English нельзя: am здесь лишний.","text_ky":"Жөнөкөй сүйлөмдө же be, же иш-аракет этиши болот, экөө бирге эмес. «Мен англисче окуйм» — I study English. I am study English деп айтууга болбойт: бул жерде am ашыкча.","examples":[{"en":"I study English.","ru":"Я учу английский.","ky":"Мен англис тилин окуйм."},{"en":"I am a student.","ru":"Я студент.","ky":"Мен студентмин."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('98b367b9-9d80-5d68-82c7-cbf33e0aae3c', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e01', 1, 'choice', '{"prompt_en":"Aidana ___ to school every day.","options":[{"id":"a","label":"go","explain_ru":"Неверно: go — форма для I/you/we/they; Aidana — это she, нужен -s.","explain_ky":"Туура эмес: go — I/you/we/they үчүн форма; Aidana — бул she, -s керек."},{"id":"b","label":"goes","explain_ru":"Верно: после he/she в Present Simple глагол получает -s: goes.","explain_ky":"Туура: Present Simple''де he/she дегенден кийин этишке -s жалганат: goes."},{"id":"c","label":"going","explain_ru":"Неверно: форма на -ing не живёт одна, ей нужен am/is/are — и это уже другое время.","explain_ky":"Туура эмес: -ing формасы жалгыз турбайт, ага am/is/are керек — жана бул башка чак."},{"id":"d","label":"is go","explain_ru":"Неверно: is и простая форма go вместе не ставятся.","explain_ky":"Туура эмес: is менен жөнөкөй go формасы бирге коюлбайт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('ea6c673a-dc23-5c0d-8be4-8ddc2bee4d29', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e02', 2, 'choice', '{"prompt_en":"I ___ English every evening.","options":[{"id":"a","label":"study","explain_ru":"Верно: после I глагол стоит в простой форме без -s.","explain_ky":"Туура: I дегенден кийин этиш -s мүчөсүз жөнөкөй формада турат."},{"id":"b","label":"studies","explain_ru":"Неверно: -s (studies) появляется только после he/she/it.","explain_ky":"Туура эмес: -s (studies) he/she/it дегенден кийин гана жалганат."},{"id":"c","label":"am study","explain_ru":"Неверно: am рядом с глаголом действия лишний: либо I am…, либо I study…","explain_ky":"Туура эмес: иш-аракет этишинин жанында am ашыкча: же I am…, же I study…"},{"id":"d","label":"studying","explain_ru":"Неверно: одна форма на -ing без am/is/are не образует предложение.","explain_ky":"Туура эмес: -ing формасы am/is/are болбосо сүйлөм түзбөйт."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('53e0e61e-dbd2-59be-8554-55bf366a2968', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e03', 3, 'choice', '{"prompt_en":"They ___ in Bishkek.","options":[{"id":"a","label":"lives","explain_ru":"Неверно: -s нужен после he/she/it, а they — «они».","explain_ky":"Туура эмес: -s мүчөсү he/she/it дегенден кийин керек, they болсо — «алар»."},{"id":"b","label":"live","explain_ru":"Верно: после they глагол в простой форме без -s.","explain_ky":"Туура: they дегенден кийин этиш -s мүчөсүз жөнөкөй формада."},{"id":"c","label":"is live","explain_ru":"Неверно: is с простой формой live не сочетается, и после they было бы are.","explain_ky":"Туура эмес: is жөнөкөй live формасы менен айкалышпайт, they менен болсо are келмек."},{"id":"d","label":"living","explain_ru":"Неверно: living без am/is/are не образует предложение.","explain_ky":"Туура эмес: living формасы am/is/are жок сүйлөм түзбөйт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('e4228746-bdbf-592a-88f9-29cb19a6f046', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e04', 4, 'choice', '{"prompt_en":"My brother ___ football.","options":[{"id":"a","label":"play","explain_ru":"Неверно: my brother — это he, глаголу нужен -s: plays.","explain_ky":"Туура эмес: my brother — бул he, этишке -s керек: plays."},{"id":"b","label":"plays","explain_ru":"Верно: brother — he, поэтому play + s.","explain_ky":"Туура: brother — he, ошондуктан play + s."},{"id":"c","label":"is play","explain_ru":"Неверно: is и простая форма play вместе не ставятся.","explain_ky":"Туура эмес: is менен жөнөкөй play формасы бирге коюлбайт."},{"id":"d","label":"playing","explain_ru":"Неверно: playing требует am/is/are и описывает действие прямо сейчас.","explain_ky":"Туура эмес: playing формасына am/is/are керек жана ал азыр болуп жаткан иш-аракетти билдирет."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('22085933-6bf8-5e61-892f-a6819ad514a6', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e05', 5, 'choice', '{"prompt_ru":"Выберите правильное предложение.","prompt_ky":"Туура сүйлөмдү тандаңыз.","options":[{"id":"a","label":"I am study English.","explain_ru":"Неверно: am рядом с глаголом действия study лишний.","explain_ky":"Туура эмес: study иш-аракет этишинин жанында am ашыкча."},{"id":"b","label":"I study English.","explain_ru":"Верно: глагол действия study стоит сразу после I, без am.","explain_ky":"Туура: study этиши I дегенден кийин эле турат, am жок."},{"id":"c","label":"I studies English.","explain_ru":"Неверно: -s появляется после he/she/it, а не после I.","explain_ky":"Туура эмес: -s мүчөсү he/she/it дегенден кийин жалганат, I менен эмес."},{"id":"d","label":"I am studies English.","explain_ru":"Неверно: здесь сразу две ошибки — лишний am и -s после I.","explain_ky":"Туура эмес: мында эки ката бар — ашыкча am жана I менен -s."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('86df3db1-0b45-5f76-83ec-b91af975e5f6', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e06', 6, 'short_answer', '{"prompt_ru":"Напишите по-английски: «Я живу в Бишкеке».","prompt_ky":"Англисче жазыңыз: «Мен Бишкекте жашайм».","accepted":["I live in Bishkek","I live in Bishkek."],"explain_ru":"I live in Bishkek. После I глагол без -s, и am здесь не нужен.","explain_ky":"I live in Bishkek. I дегенден кийин этиш -s мүчөсүз, am да бул жерде керек эмес."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('a6985d06-d731-53c2-8290-98c90003c2ba', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e07', 7, 'matching', '{"instruction_ru":"Соедините глагол с переводом.","instruction_ky":"Этишти котормосу менен дал келтириңиз.","pairs":[{"left_en":"to live","right_ru":"жить","right_ky":"жашоо"},{"left_en":"to study","right_ru":"учиться","right_ky":"окуу"},{"left_en":"to play","right_ru":"играть","right_ky":"ойноо"},{"left_en":"to work","right_ru":"работать","right_ky":"иштөө"},{"left_en":"to speak","right_ru":"говорить","right_ky":"сүйлөө"}],"explain_ru":"Это глаголы действия: в Present Simple они меняются только одним способом — -s после he/she/it.","explain_ky":"Булар иш-аракет этиштери: Present Simple''де алар бир гана жол менен өзгөрөт — he/she/it дегенден кийин -s жалганат."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('f8fd90a1-bac1-5567-824f-a88503adf83c', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e08', 8, 'choice', '{"prompt_en":"Meerim ___ Kyrgyz and Russian.","options":[{"id":"a","label":"speak","explain_ru":"Неверно: Meerim — she, глаголу нужен -s: speaks.","explain_ky":"Туура эмес: Meerim — she, этишке -s керек: speaks."},{"id":"b","label":"speaks","explain_ru":"Верно: после he/she глагол получает -s: speaks.","explain_ky":"Туура: he/she дегенден кийин этишке -s жалганат: speaks."},{"id":"c","label":"is speak","explain_ru":"Неверно: is с простой формой speak не сочетается.","explain_ky":"Туура эмес: is жөнөкөй speak формасы менен айкалышпайт."},{"id":"d","label":"speaking","explain_ru":"Неверно: speaking без is не образует предложение.","explain_ky":"Туура эмес: speaking формасы is болбосо сүйлөм түзбөйт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('45c46934-8d61-5d70-86d5-1f0423096fed', '33026e22-2c44-5d9a-8eb3-e394be53f94a', 'en-m1-l07-e09', 9, 'choice', '{"prompt_en":"We ___ students.","options":[{"id":"a","label":"is","explain_ru":"Неверно: is — для he/she/it, а we — «мы».","explain_ky":"Туура эмес: is — he/she/it үчүн, we болсо — «биз»."},{"id":"b","label":"am","explain_ru":"Неверно: am бывает только после I.","explain_ky":"Туура эмес: am формасы I дегенден кийин гана болот."},{"id":"c","label":"are","explain_ru":"Верно: после we — форма are: We are students.","explain_ky":"Туура: we дегенден кийин are келет: We are students."},{"id":"d","label":"do","explain_ru":"Неверно: do — вспомогательный глагол для вопросов и отрицаний, связкой он не бывает.","explain_ky":"Туура эмес: do — суроо жана танууда колдонулган жардамчы этиш, байланыштыруучу боло албайт."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('7b6defd1-04ce-552c-8b87-12874a87626f', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l08', 8, '{"title_ru":"Повседневные ситуации: кафе, транспорт, покупки","title_ky":"Күнүмдүк кырдаалдар: кафе, транспорт, сатып алуу","goal_ru":"Попросить, спросить цену и купить билет простыми вежливыми фразами.","goal_ky":"Жөнөкөй сылык фразалар менен суранып, баасын сурап, билет сатып аласың."}'::JSONB, '[{"text_ru":"Попросить в кафе: Can I have tea, please? В ответ услышите Here you are — «вот, пожалуйста». Поблагодарить: Thank you.","text_ky":"Кафеде суроо: Can I have tea, please? Жооп катары Here you are — «мына, алыңыз» дегенди угасыз. Ыраазычылык: Thank you.","examples":[{"en":"Can I have tea, please?","ru":"Можно мне чай, пожалуйста?","ky":"Мага чай берсеңиз, сураныч?"},{"en":"Here you are.","ru":"Вот, пожалуйста.","ky":"Мына, алыңыз."},{"en":"Thank you.","ru":"Спасибо.","ky":"Рахмат."}]},{"text_ru":"Узнать цену: How much is it? Ответ: It''s fifty som. Не путайте три похожих вопроса: How much — о цене, How old — о возрасте, How are you — о делах.","text_ky":"Баасын суроо: How much is it? Жообу: It''s fifty som. Үч окшош суроону чаташтырбаңыз: How much — баа жөнүндө, How old — жаш жөнүндө, How are you — ал-абал жөнүндө.","examples":[{"en":"— How much is it? — It''s fifty som.","ru":"— Сколько это стоит? — Пятьдесят сомов.","ky":"— Бул канча турат? — Элүү сом."}]},{"text_ru":"Транспорт: One ticket, please — «один билет, пожалуйста». Спросить дорогу: Where is the bus stop? Привлечь внимание или извиниться: Excuse me.","text_ky":"Транспорт: One ticket, please — «бир билет, сураныч». Жол суроо: Where is the bus stop? Көңүл буруу же кечирим суроо: Excuse me.","examples":[{"en":"One ticket, please.","ru":"Один билет, пожалуйста.","ky":"Бир билет, сураныч."},{"en":"Excuse me, where is the bus stop?","ru":"Извините, где автобусная остановка?","ky":"Кечиресиз, автобус аялдамасы кайда?"}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('593c65e7-6f40-58fd-8d4a-5559d73740de', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e01', 1, 'choice', '{"prompt_ru":"Вы в кафе и хотите чай. Что вы скажете?","prompt_ky":"Сиз кафедесиз, чай алгыңыз келет. Эмне дейсиз?","options":[{"id":"a","label":"Can I have tea, please?","explain_ru":"Верно: Can I have… , please? — вежливая просьба.","explain_ky":"Туура: Can I have…, please? — сылык суранч."},{"id":"b","label":"Where is tea?","explain_ru":"Неверно: это вопрос «где чай?» — так ищут предмет, а не заказывают.","explain_ky":"Туура эмес: бул «чай кайда?» деген суроо — минтип затты издешет, заказ кылышпайт."},{"id":"c","label":"Tea is good.","explain_ru":"Неверно: «чай — это хорошо» — мнение, а не просьба.","explain_ky":"Туура эмес: «чай жакшы» — бул пикир, суранч эмес."},{"id":"d","label":"I am tea.","explain_ru":"Неверно: получилось «я — чай». Для просьбы нужна конструкция Can I have…","explain_ky":"Туура эмес: «мен чаймын» болуп калды. Суранч үчүн Can I have… керек."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('39e039f3-c485-5abe-8ea6-2f9c98ea3c85', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e02', 2, 'choice', '{"prompt_en":"— How much is it? — ___","options":[{"id":"a","label":"It''s ten o''clock.","explain_ru":"Неверно: это ответ о времени, а how much спрашивает о цене.","explain_ky":"Туура эмес: бул убакыт жөнүндө жооп, how much болсо бааны сурайт."},{"id":"b","label":"It''s fifty som.","explain_ru":"Верно: how much — вопрос о цене, ответ — сумма.","explain_ky":"Туура: how much — баа жөнүндө суроо, жообу — сумма."},{"id":"c","label":"It''s Monday.","explain_ru":"Неверно: Monday — день недели, а не цена.","explain_ky":"Туура эмес: Monday — апта күнү, баа эмес."},{"id":"d","label":"I''m fine.","explain_ru":"Неверно: I''m fine — ответ на How are you? («как дела?»).","explain_ky":"Туура эмес: I''m fine — How are you? («кандайсың?») суроосунун жообу."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('8c0cd37b-15a3-5e22-8f11-7d0e842db5f3', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e03', 3, 'matching', '{"instruction_ru":"Соедините фразу с переводом.","instruction_ky":"Фразаны котормосу менен дал келтириңиз.","pairs":[{"left_en":"Here you are","right_ru":"Вот, пожалуйста","right_ky":"Мына, алыңыз"},{"left_en":"Thank you","right_ru":"Спасибо","right_ky":"Рахмат"},{"left_en":"How much is it?","right_ru":"Сколько это стоит?","right_ky":"Бул канча турат?"},{"left_en":"One ticket, please","right_ru":"Один билет, пожалуйста","right_ky":"Бир билет, сураныч"},{"left_en":"Excuse me","right_ru":"Извините","right_ky":"Кечиресиз"}],"explain_ru":"Here you are говорит тот, кто даёт вещь; в ответ говорят Thank you.","explain_ky":"Here you are деп затты берген адам айтат; жооп катары Thank you дешет."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('ea0704db-347a-5724-8732-c23a08b66815', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e04', 4, 'choice', '{"prompt_ru":"Вы хотите узнать цену. Какой вопрос зададите?","prompt_ky":"Баасын билгиңиз келет. Кайсы суроону бересиз?","options":[{"id":"a","label":"How old are you?","explain_ru":"Неверно: how old — вопрос о возрасте человека.","explain_ky":"Туура эмес: how old — адамдын жашы жөнүндө суроо."},{"id":"b","label":"How much is it?","explain_ru":"Верно: how much is it? — «сколько это стоит?».","explain_ky":"Туура: how much is it? — «бул канча турат?»."},{"id":"c","label":"How are you?","explain_ru":"Неверно: how are you — «как дела?», о самочувствии, не о цене.","explain_ky":"Туура эмес: how are you — «кандайсың?», ал-абал жөнүндө, баа жөнүндө эмес."},{"id":"d","label":"What time is it?","explain_ru":"Неверно: what time is it — вопрос о времени на часах.","explain_ky":"Туура эмес: what time is it — сааттагы убакыт жөнүндө суроо."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('18a4bc67-1f3e-5dc8-8323-8ace7913962a', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e05', 5, 'short_answer', '{"prompt_ru":"Напишите вежливую просьбу по-английски: «Один билет, пожалуйста».","prompt_ky":"Англисче сылык суранч жазыңыз: «Бир билет, сураныч».","accepted":["One ticket, please","One ticket, please.","One ticket please","One ticket please."],"explain_ru":"One ticket, please. Слово please делает просьбу вежливой; без него фраза звучит как приказ.","explain_ky":"One ticket, please. Please сөзү суранчты сылык кылат; ансыз фраза буйруктай угулат."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('a5c0443b-c119-5fce-8fc6-7b3d5d044edb', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e06', 6, 'choice', '{"prompt_en":"— Excuse me, where is the bus stop? — ___","options":[{"id":"a","label":"It''s near the school.","explain_ru":"Верно: where — вопрос о месте, ответ near the school («рядом со школой») называет место.","explain_ky":"Туура: where — орун жөнүндө суроо, near the school («мектептин жанында») деген жооп орунду айтат."},{"id":"b","label":"It''s two o''clock.","explain_ru":"Неверно: это ответ о времени, а спросили, где остановка.","explain_ky":"Туура эмес: бул убакыт жөнүндө жооп, суроо болсо аялдама кайда экени жөнүндө."},{"id":"c","label":"I''m sixteen.","explain_ru":"Неверно: это ответ о возрасте на вопрос how old.","explain_ky":"Туура эмес: бул how old суроосуна жаш жөнүндө жооп."},{"id":"d","label":"Nice to meet you.","explain_ru":"Неверно: эту фразу говорят при знакомстве, она не называет место.","explain_ky":"Туура эмес: бул фраза таанышканда айтылат, орунду билдирбейт."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('ac8ad152-1947-5959-8ef8-7bfe33b1cb4a', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e07', 7, 'choice', '{"prompt_ru":"Когда говорят Excuse me?","prompt_ky":"Excuse me качан айтылат?","options":[{"id":"a","label_ru":"Чтобы привлечь внимание или извиниться","label_ky":"Көңүл буруу же кечирим суроо үчүн","explain_ru":"Верно: excuse me открывает обращение к незнакомому человеку или извиняет за беспокойство.","explain_ky":"Туура: excuse me бейтааныш адамга кайрылууну баштайт же тынчсыздандырганы үчүн кечирим сурайт."},{"id":"b","label_ru":"Чтобы попрощаться","label_ky":"Коштошуу үчүн","explain_ru":"Неверно: прощаются словами Goodbye или Bye.","explain_ky":"Туура эмес: коштошкондо Goodbye же Bye дешет."},{"id":"c","label_ru":"Чтобы назвать цену","label_ky":"Бааны айтуу үчүн","explain_ru":"Неверно: цену называют так: It''s fifty som.","explain_ky":"Туура эмес: баа мындай айтылат: It''s fifty som."},{"id":"d","label_ru":"Чтобы поблагодарить","label_ky":"Ыраазычылык билдирүү үчүн","explain_ru":"Неверно: благодарят словами Thank you.","explain_ky":"Туура эмес: ыраазычылык Thank you деп айтылат."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('391ef266-ed0b-5d76-805a-c9c1cd5d606a', '7b6defd1-04ce-552c-8b87-12874a87626f', 'en-m1-l08-e08', 8, 'reading', '{"passage_en":"Meerim is in a café. — Can I have green tea and bread, please? — Here you are. Anything else? — No, thank you. How much is it? — Sixty som, please. Meerim gives the money and says: — Thank you! Goodbye!","questions":[{"id":"en-m1-l08-e08-q1","prompt_en":"What does Meerim ask for?","options":[{"id":"a","label":"green tea and bread","explain_ru":"Верно: Can I have green tea and bread, please?","explain_ky":"Туура: Can I have green tea and bread, please?"},{"id":"b","label":"coffee and cake","explain_ru":"Неверно: кофе и торт в диалоге не звучат.","explain_ky":"Туура эмес: диалогдо кофе жана торт айтылган жок."},{"id":"c","label":"one ticket","explain_ru":"Неверно: билет покупают в транспорте, а Meerim в кафе.","explain_ky":"Туура эмес: билет транспорттон алынат, Meerim болсо кафеде."},{"id":"d","label":"a book","explain_ru":"Неверно: книга в диалоге не упоминается.","explain_ky":"Туура эмес: диалогдо китеп айтылган эмес."}],"answer_index":0},{"id":"en-m1-l08-e08-q2","prompt_en":"How much is it?","options":[{"id":"a","label":"sixteen som","explain_ru":"Неверно: sixteen — 16; в диалоге sixty — 60. Окончание -teen против -ty.","explain_ky":"Туура эмес: sixteen — 16; диалогдо sixty — 60. Айырмасы -teen жана -ty мүчөлөрүндө."},{"id":"b","label":"sixty som","explain_ru":"Верно: Sixty som, please — 60 сомов.","explain_ky":"Туура: Sixty som, please — 60 сом."},{"id":"c","label":"six som","explain_ru":"Неверно: six — 6, а в диалоге sixty — 60.","explain_ky":"Туура эмес: six — 6, диалогдо болсо sixty — 60."},{"id":"d","label":"sixty-six som","explain_ru":"Неверно: sixty-six — 66, в диалоге ровно sixty — 60.","explain_ky":"Туура эмес: sixty-six — 66, диалогдо так sixty — 60."}],"answer_index":1}]}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('0369c08c-75ed-526f-89c2-ed2348c5d78b', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l09', 9, '{"title_ru":"Чтение коротких текстов","title_ky":"Кыска тексттерди окуу","goal_ru":"Прочитать короткий английский текст и найти в нём нужную информацию.","goal_ky":"Кыска англисче текстти окуп, андан керектүү маалыматты табасың."}'::JSONB, '[{"text_ru":"Сначала посмотрите на вопросы — станет ясно, что искать в тексте. Понимать каждое слово не обязательно: ищите имена, числа, дни недели и знакомые слова.","text_ky":"Адегенде суроолорду караңыз — тексттен эмнени издөө керек экени түшүнүктүү болот. Ар бир сөздү түшүнүү милдеттүү эмес: аттарды, сандарды, апта күндөрүн жана тааныш сөздөрдү издеңиз.","examples":[{"en":"Aizat — Naryn — sixteen — Monday","ru":"имя — город — число — день: за такие слова цепляется взгляд","ky":"ат — шаар — сан — күн: көз ушундай сөздөргө илинет"}]},{"text_ru":"Маленькие слова-связки меняют смысл: and — «и» (добавляет), but — «но» (противопоставляет). My school is small, but my class is big.","text_ky":"Кичинекей байланыш сөздөр маанини өзгөртөт: and — «жана» (кошот), but — «бирок» (каршы коёт). My school is small, but my class is big.","examples":[{"en":"I like maths and English.","ru":"Я люблю математику и английский.","ky":"Мен математиканы жана англис тилин жакшы көрөм."},{"en":"My school is small, but my class is big.","ru":"Моя школа маленькая, но мой класс большой.","ky":"Мектебим кичине, бирок классым чоң."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('8a14aaf9-5c9b-50e6-8003-f3352cc9c9f1', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e01', 1, 'reading', '{"passage_en":"Aizat is from Naryn. She is sixteen. She is a student. Her school is small, but her class is big. Aizat likes maths and English. After school she plays volleyball with her friends. Her brother plays too.","questions":[{"id":"en-m1-l09-e01-q1","prompt_en":"Where is Aizat from?","options":[{"id":"a","label":"Naryn","explain_ru":"Верно: Aizat is from Naryn — первая строка текста.","explain_ky":"Туура: Aizat is from Naryn — тексттин биринчи сабы."},{"id":"b","label":"Bishkek","explain_ru":"Неверно: Бишкек в тексте не упоминается.","explain_ky":"Туура эмес: текстте Бишкек айтылган эмес."},{"id":"c","label":"Osh","explain_ru":"Неверно: Ош в тексте не упоминается.","explain_ky":"Туура эмес: текстте Ош айтылган эмес."},{"id":"d","label":"Talas","explain_ru":"Неверно: Талас в тексте не упоминается.","explain_ky":"Туура эмес: текстте Талас айтылган эмес."}],"answer_index":0},{"id":"en-m1-l09-e01-q2","prompt_en":"What subjects does Aizat like?","options":[{"id":"a","label":"maths and English","explain_ru":"Верно: Aizat likes maths and English.","explain_ky":"Туура: Aizat likes maths and English."},{"id":"b","label":"history and sport","explain_ru":"Неверно: history и sport в тексте не названы.","explain_ky":"Туура эмес: текстте history жана sport аталган эмес."},{"id":"c","label":"music","explain_ru":"Неверно: музыка в тексте не упоминается.","explain_ky":"Туура эмес: текстте музыка айтылган эмес."},{"id":"d","label":"biology","explain_ru":"Неверно: биология в тексте не упоминается.","explain_ky":"Туура эмес: текстте биология айтылган эмес."}],"answer_index":0},{"id":"en-m1-l09-e01-q3","prompt_en":"Aizat plays volleyball with ___.","options":[{"id":"a","label":"her friends","explain_ru":"Верно: she plays volleyball with her friends; брат тоже играет, но «с кем» сказано о друзьях.","explain_ky":"Туура: she plays volleyball with her friends; иниси да ойнойт, бирок «ким менен» деген жоопто досторун айтылат."},{"id":"b","label":"her teacher","explain_ru":"Неверно: учитель в тексте с волейболом не связан.","explain_ky":"Туура эмес: текстте мугалим волейболго байланышкан эмес."},{"id":"c","label":"her mother","explain_ru":"Неверно: мама в тексте не упоминается.","explain_ky":"Туура эмес: текстте апасы айтылган эмес."},{"id":"d","label":"her cat","explain_ru":"Неверно: кошки в тексте нет.","explain_ky":"Туура эмес: текстте мышык жок."}],"answer_index":0}]}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('268eae5d-c6f7-519d-80ca-402a09a7d858', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e02', 2, 'choice', '{"prompt_ru":"Что означает слово but?","prompt_ky":"But деген сөз эмнени билдирет?","options":[{"id":"a","label_ru":"но","label_ky":"бирок","explain_ru":"Верно: but противопоставляет две части предложения.","explain_ky":"Туура: but сүйлөмдүн эки бөлүгүн каршы коёт."},{"id":"b","label_ru":"и","label_ky":"жана","explain_ru":"Неверно: «и» — это and.","explain_ky":"Туура эмес: «жана» — англисче and."},{"id":"c","label_ru":"потом","label_ky":"анан","explain_ru":"Неверно: «потом» — это then.","explain_ky":"Туура эмес: «анан» — англисче then."},{"id":"d","label_ru":"потому что","label_ky":"себеби","explain_ru":"Неверно: «потому что» — это because.","explain_ky":"Туура эмес: «себеби» — англисче because."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('e910d4c0-8c36-55f7-8aea-1491ba32bf49', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e03', 3, 'reading', '{"passage_en":"The school library is open from Monday to Friday. It opens at nine o''clock and closes at five o''clock. On Saturday it is open from ten to two. On Sunday it is closed. Students can take three books for two weeks.","questions":[{"id":"en-m1-l09-e03-q1","prompt_en":"When is the library closed?","options":[{"id":"a","label":"on Sunday","explain_ru":"Верно: On Sunday it is closed.","explain_ky":"Туура: On Sunday it is closed."},{"id":"b","label":"on Monday","explain_ru":"Неверно: с понедельника по пятницу библиотека открыта.","explain_ky":"Туура эмес: дүйшөмбүдөн жумага чейин китепкана ачык."},{"id":"c","label":"on Friday","explain_ru":"Неверно: пятница входит в from Monday to Friday — открыто.","explain_ky":"Туура эмес: жума from Monday to Friday аралыгына кирет — ачык."},{"id":"d","label":"on Saturday","explain_ru":"Неверно: в субботу открыто с десяти до двух.","explain_ky":"Туура эмес: ишембиде саат ондон экиге чейин ачык."}],"answer_index":0},{"id":"en-m1-l09-e03-q2","prompt_en":"How many books can students take?","options":[{"id":"a","label":"two","explain_ru":"Неверно: two weeks — это срок («на две недели»), а книг — three.","explain_ky":"Туура эмес: two weeks — мөөнөт («эки жумага»), китептер болсо — three."},{"id":"b","label":"three","explain_ru":"Верно: three books for two weeks — три книги на две недели.","explain_ky":"Туура: three books for two weeks — эки жумага үч китеп."},{"id":"c","label":"five","explain_ru":"Неверно: five (пять) — это час закрытия, а не число книг.","explain_ky":"Туура эмес: five (беш) — жабылуу сааты, китептин саны эмес."},{"id":"d","label":"ten","explain_ru":"Неверно: ten (десять) — час открытия в субботу.","explain_ky":"Туура эмес: ten (он) — ишембидеги ачылуу сааты."}],"answer_index":1}]}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('5166fde5-ea58-5a70-8338-e25eba9e15eb', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e04', 4, 'choice', '{"prompt_ru":"Что означает слово open?","prompt_ky":"Open деген сөз эмнени билдирет?","options":[{"id":"a","label_ru":"открыто","label_ky":"ачык","explain_ru":"Верно: open — «открыто»; противоположное слово — closed.","explain_ky":"Туура: open — «ачык»; карама-каршы сөзү — closed."},{"id":"b","label_ru":"закрыто","label_ky":"жабык","explain_ru":"Неверно: «закрыто» — это closed.","explain_ky":"Туура эмес: «жабык» — англисче closed."},{"id":"c","label_ru":"дорого","label_ky":"кымбат","explain_ru":"Неверно: «дорого» — expensive, это слово о цене.","explain_ky":"Туура эмес: «кымбат» — expensive, бул баа жөнүндө сөз."},{"id":"d","label_ru":"рано","label_ky":"эрте","explain_ru":"Неверно: «рано» — early, это слово о времени.","explain_ky":"Туура эмес: «эрте» — early, бул убакыт жөнүндө сөз."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('7cec06a5-8588-5f2a-8e76-ad4e46598780', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e05', 5, 'reading', '{"passage_en":"Hi, Timur! I am at the bus stop near the market. My bus comes at four o''clock. Please buy bread and milk. Mum is at work today. See you at home! — Kanat","questions":[{"id":"en-m1-l09-e05-q1","prompt_en":"Where is Kanat?","options":[{"id":"a","label":"at the bus stop","explain_ru":"Верно: I am at the bus stop near the market.","explain_ky":"Туура: I am at the bus stop near the market."},{"id":"b","label":"at school","explain_ru":"Неверно: школа в записке не упоминается.","explain_ky":"Туура эмес: катта мектеп айтылган эмес."},{"id":"c","label":"at home","explain_ru":"Неверно: дом упоминается в конце — see you at home, но Kanat ещё не там.","explain_ky":"Туура эмес: үй каттын аягында айтылат — see you at home, бирок Kanat азырынча ал жерде эмес."},{"id":"d","label":"at work","explain_ru":"Неверно: at work — это про маму: Mum is at work today.","explain_ky":"Туура эмес: at work — апасы жөнүндө: Mum is at work today."}],"answer_index":0},{"id":"en-m1-l09-e05-q2","prompt_en":"What does Kanat ask Timur to buy?","options":[{"id":"a","label":"bread and milk","explain_ru":"Верно: Please buy bread and milk.","explain_ky":"Туура: Please buy bread and milk."},{"id":"b","label":"tea and bread","explain_ru":"Неверно: чай в записке не упоминается.","explain_ky":"Туура эмес: катта чай айтылган эмес."},{"id":"c","label":"a ticket","explain_ru":"Неверно: билет не упоминается; bus — это автобус Каната.","explain_ky":"Туура эмес: билет айтылган эмес; bus — Канаттын автобусу."},{"id":"d","label":"a book","explain_ru":"Неверно: книги в записке нет.","explain_ky":"Туура эмес: катта китеп жок."}],"answer_index":0}]}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('0887dc7b-f188-5cd5-82a3-38f5eba6bca7', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e06', 6, 'choice', '{"prompt_ru":"Что означает фраза See you!?","prompt_ky":"See you! деген фраза эмнени билдирет?","options":[{"id":"a","label_ru":"До встречи!","label_ky":"Көрүшкөнчө!","explain_ru":"Верно: see you — «увидимся, до встречи», лёгкое прощание.","explain_ky":"Туура: see you — «көрүшөбүз, көрүшкөнчө», жеңил коштошуу."},{"id":"b","label_ru":"Спасибо!","label_ky":"Рахмат!","explain_ru":"Неверно: «спасибо» — thank you.","explain_ky":"Туура эмес: «рахмат» — thank you."},{"id":"c","label_ru":"Извините!","label_ky":"Кечиресиз!","explain_ru":"Неверно: «извините» — excuse me или sorry.","explain_ky":"Туура эмес: «кечиресиз» — excuse me же sorry."},{"id":"d","label_ru":"Вот, пожалуйста!","label_ky":"Мына, алыңыз!","explain_ru":"Неверно: «вот, пожалуйста» — here you are.","explain_ky":"Туура эмес: «мына, алыңыз» — here you are."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('e5c65b95-75d0-5832-8478-40bb8fea3e36', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e07', 7, 'short_answer', '{"prompt_ru":"Прочитайте: «Aidana has one sister and two brothers». Сколько у Айданы братьев? Ответьте английским словом.","prompt_ky":"Окуңуз: «Aidana has one sister and two brothers». Айдананын канча иниси/байкеси бар? Англисче сөз менен жооп бериңиз.","accepted":["two","Two","2"],"explain_ru":"Two brothers — два брата. One sister — одна сестра, следите, к какому слову относится число.","explain_ky":"Two brothers — эки бир тууган (эркек). One sister — бир эже/карындаш; сан кайсы сөзгө тиешелүү экенин байкаңыз."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('fc7bbfb8-e2c9-511e-862e-f4274d0fcbbf', '0369c08c-75ed-526f-89c2-ed2348c5d78b', 'en-m1-l09-e08', 8, 'choice', '{"prompt_ru":"В тексте встретилось незнакомое слово. Что делать?","prompt_ky":"Текстте тааныш эмес сөз чыкты. Эмне кылуу керек?","options":[{"id":"a","label_ru":"Остановиться и дальше не читать","label_ky":"Токтоп, андан ары окубай коюу","explain_ru":"Неверно: одно незнакомое слово редко мешает понять главное.","explain_ky":"Туура эмес: бир тааныш эмес сөз негизги маанини түшүнүүгө сейрек тоскоол болот."},{"id":"b","label_ru":"Понять общий смысл по соседним словам и читать дальше","label_ky":"Жанындагы сөздөр аркылуу жалпы маанини түшүнүп, андан ары окуу","explain_ru":"Верно: смысл часто ясен из контекста — имён, чисел и знакомых слов рядом.","explain_ky":"Туура: маани көбүнчө контексттен түшүнүктүү — жанындагы аттардан, сандардан жана тааныш сөздөрдөн."},{"id":"c","label_ru":"Переписать весь текст в тетрадь","label_ky":"Бүт текстти дептерге көчүрүп жазуу","explain_ru":"Неверно: переписывание не помогает понять смысл при чтении.","explain_ky":"Туура эмес: көчүрүп жазуу окуп жатканда маанини түшүнүүгө жардам бербейт."},{"id":"d","label_ru":"Выбрать ответ наугад","label_ky":"Жоопту туш келди тандоо","explain_ru":"Неверно: ответ почти всегда можно найти в тексте по знакомым словам.","explain_ky":"Туура эмес: жоопту дээрлик ар дайым тексттеги тааныш сөздөр аркылуу таап алууга болот."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('9e3aff49-3517-568b-80cf-48447a32e566', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l10', 10, '{"title_ru":"Слова об учёбе и планах","title_ky":"Окуу жана пландар жөнүндө сөздөр","goal_ru":"Сказать, что вам нравится и кем или где вы хотите учиться и стать.","goal_ky":"Эмне жакканын жана ким болгуң же кайда окугуң келгенин айтасың."}'::JSONB, '[{"text_ru":"Планы выражают конструкцией want to + глагол: I want to study at a university. She wants to be a doctor. После want обязательно нужна частица to.","text_ky":"Пландар want to + этиш түзүлүшү менен айтылат: I want to study at a university. She wants to be a doctor. Want этишинен кийин to бөлүкчөсү сөзсүз керек.","examples":[{"en":"I want to study at a university.","ru":"Я хочу учиться в университете.","ky":"Мен университетте окугум келет."},{"en":"She wants to be a doctor.","ru":"Она хочет стать врачом.","ky":"Ал дарыгер болгусу келет."}]},{"text_ru":"Слова об учёбе: university — университет, exam — экзамен, plan — план, to learn — учить, to study — учиться. Про будущую профессию говорят want to be — «хотеть стать».","text_ky":"Окуу сөздөрү: university — университет, exam — экзамен, plan — план, to learn — үйрөнүү, to study — окуу. Келечектеги кесип жөнүндө want to be — «болгусу келүү» деп айтышат.","examples":[{"en":"The exam is on Monday.","ru":"Экзамен в понедельник.","ky":"Экзамен дүйшөмбүдө."},{"en":"I learn ten new words every day.","ru":"Я учу десять новых слов каждый день.","ky":"Мен күн сайын он жаңы сөз үйрөнөм."}]},{"text_ru":"Что нравится: like + предмет. I like English. Nurlan likes maths. После like перед существительным to не ставится.","text_ky":"Эмне жагат: like + зат. I like English. Nurlan likes maths. Like этишинен кийин зат атоочтун алдына to коюлбайт.","examples":[{"en":"I like English.","ru":"Мне нравится английский.","ky":"Мага англис тили жагат."},{"en":"Nurlan likes maths.","ru":"Нурлану нравится математика.","ky":"Нурланга математика жагат."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('4b94cf46-6d59-5ab4-8053-4fe15b9cd721', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e01', 1, 'choice', '{"prompt_en":"I want ___ a doctor.","options":[{"id":"a","label":"be","explain_ru":"Неверно: после want нужна частица to: want to be.","explain_ky":"Туура эмес: want этишинен кийин to керек: want to be."},{"id":"b","label":"to be","explain_ru":"Верно: want to be — «хотеть стать».","explain_ky":"Туура: want to be — «болгусу келүү»."},{"id":"c","label":"being","explain_ru":"Неверно: после want ставится to + начальная форма, а не форма на -ing.","explain_ky":"Туура эмес: want этишинен кийин to + баштапкы форма коюлат, -ing формасы эмес."},{"id":"d","label":"am","explain_ru":"Неверно: am — личная форма be, после want она не ставится.","explain_ky":"Туура эмес: am — be этишинин жактама формасы, want дегенден кийин коюлбайт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('d9a45b02-c2b5-5f7b-8c30-566d31ae1a38', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e02', 2, 'choice', '{"prompt_en":"Nurlan wants ___ at a university.","options":[{"id":"a","label":"study","explain_ru":"Неверно: после wants нужна частица to: wants to study.","explain_ky":"Туура эмес: wants дегенден кийин to керек: wants to study."},{"id":"b","label":"to study","explain_ru":"Верно: wants to study — конструкция want to + глагол; -s уже у wants.","explain_ky":"Туура: wants to study — want to + этиш түзүлүшү; -s мүчөсү wants сөзүндө эле бар."},{"id":"c","label":"studies","explain_ru":"Неверно: двух глаголов с -s подряд не бывает; после to глагол стоит в начальной форме.","explain_ky":"Туура эмес: -s мүчөлүү эки этиш катар келбейт; to бөлүкчөсүнөн кийин этиш баштапкы формада."},{"id":"d","label":"studying","explain_ru":"Неверно: после want(s) идёт to + начальная форма, а не -ing.","explain_ky":"Туура эмес: want(s) дегенден кийин to + баштапкы форма келет, -ing эмес."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('2b5c2c73-bb3e-51e3-8322-65f8f3155f05', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e03', 3, 'matching', '{"instruction_ru":"Соедините слово с переводом.","instruction_ky":"Сөздү котормосу менен дал келтириңиз.","pairs":[{"left_en":"university","right_ru":"университет","right_ky":"университет"},{"left_en":"exam","right_ru":"экзамен","right_ky":"экзамен"},{"left_en":"plan","right_ru":"план","right_ky":"план"},{"left_en":"to learn","right_ru":"учить, узнавать","right_ky":"үйрөнүү"},{"left_en":"student","right_ru":"студент, ученик","right_ky":"студент, окуучу"}],"explain_ru":"Learn — получать знания (учить слова), study — учиться, заниматься. Оба переводятся «учить(ся)», но study — про процесс занятий.","explain_ky":"Learn — билим алуу (сөз үйрөнүү), study — окуу, сабак кылуу. Экөө тең «окуу/үйрөнүү» деп которулат, бирок study окуу процессин билдирет."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('dd785652-59ef-50f5-82da-0741d3884af3', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e04', 4, 'choice', '{"prompt_en":"She ___ to be a teacher.","options":[{"id":"a","label":"want","explain_ru":"Неверно: she — третье лицо, глаголу нужен -s: wants.","explain_ky":"Туура эмес: she — үчүнчү жак, этишке -s керек: wants."},{"id":"b","label":"wants","explain_ru":"Верно: после she глагол получает -s: she wants to be…","explain_ky":"Туура: she дегенден кийин этишке -s жалганат: she wants to be…"},{"id":"c","label":"to want","explain_ru":"Неверно: to want — начальная форма, сказуемым она не бывает.","explain_ky":"Туура эмес: to want — баштапкы форма, баяндооч боло албайт."},{"id":"d","label":"wanting","explain_ru":"Неверно: wanting без am/is/are не образует предложение.","explain_ky":"Туура эмес: wanting формасы am/is/are жок сүйлөм түзбөйт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('2a3fca83-f414-5c15-8cf1-6a903b55fe39', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e05', 5, 'short_answer', '{"prompt_ru":"Напишите по-английски: «Я хочу учиться в университете».","prompt_ky":"Англисче жазыңыз: «Мен университетте окугум келет».","accepted":["I want to study at a university","I want to study at a university.","I want to study at university","I want to study at university.","I want to study at the university","I want to study at the university."],"explain_ru":"I want to study at a university. Две опоры: to после want и at перед university.","explain_ky":"I want to study at a university. Эки таяныч: want дегенден кийин to жана university алдында at."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('59cbe327-96b9-5880-8b00-58b73410f419', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e06', 6, 'choice', '{"prompt_ru":"Выберите правильное предложение.","prompt_ky":"Туура сүйлөмдү тандаңыз.","options":[{"id":"a","label":"I like English.","explain_ru":"Верно: like + название предмета, без to.","explain_ky":"Туура: like + предметтин аталышы, to жок."},{"id":"b","label":"I like to English.","explain_ru":"Неверно: to перед существительным English не ставится; to нужен перед глаголом.","explain_ky":"Туура эмес: English зат атоочунун алдына to коюлбайт; to этиштин алдында керек."},{"id":"c","label":"I am like English.","explain_ru":"Неверно: am рядом с глаголом like лишний: либо I am…, либо I like…","explain_ky":"Туура эмес: like этишинин жанында am ашыкча: же I am…, же I like…"},{"id":"d","label":"I likes English.","explain_ru":"Неверно: -s появляется после he/she/it, а не после I.","explain_ky":"Туура эмес: -s мүчөсү he/she/it дегенден кийин жалганат, I менен эмес."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('3424660f-a09d-556e-864b-596ad94f4549', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e07', 7, 'choice', '{"prompt_en":"— What do you want to be? — ___","options":[{"id":"a","label":"I want to be an engineer.","explain_ru":"Верно: вопрос о будущей профессии, ответ — want to be + профессия.","explain_ky":"Туура: суроо келечектеги кесип жөнүндө, жообу — want to be + кесип."},{"id":"b","label":"I''m fine, thanks.","explain_ru":"Неверно: это ответ на How are you? («как дела?»).","explain_ky":"Туура эмес: бул How are you? («кандайсың?») суроосунун жообу."},{"id":"c","label":"It''s nine o''clock.","explain_ru":"Неверно: это ответ о времени.","explain_ky":"Туура эмес: бул убакыт жөнүндө жооп."},{"id":"d","label":"Nice to meet you.","explain_ru":"Неверно: эту фразу говорят при знакомстве.","explain_ky":"Туура эмес: бул фраза таанышканда айтылат."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('8ca733a8-c713-5056-8573-20bb2f3dbeb0', '9e3aff49-3517-568b-80cf-48447a32e566', 'en-m1-l10-e08', 8, 'choice', '{"prompt_ru":"Выберите слово «экзамен».","prompt_ky":"«Экзамен» деген сөздү тандаңыз.","options":[{"id":"a","label":"exam","explain_ru":"Верно: exam — экзамен, проверка знаний.","explain_ky":"Туура: exam — экзамен, билимди текшерүү."},{"id":"b","label":"lesson","explain_ru":"Неверно: lesson — «урок».","explain_ky":"Туура эмес: lesson — «сабак»."},{"id":"c","label":"plan","explain_ru":"Неверно: plan — «план».","explain_ky":"Туура эмес: plan — «план»."},{"id":"d","label":"notebook","explain_ru":"Неверно: notebook — «тетрадь».","explain_ky":"Туура эмес: notebook — «дептер»."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l11', 11, '{"title_ru":"Страна и город: откуда ты и куда хочешь","title_ky":"Өлкө жана шаар: кайдансың жана кайда баргың келет","goal_ru":"Сказать, откуда вы, где живёте и в какой стране хотите учиться.","goal_ky":"Кайдан экениңди, кайда жашаганыңды жана кайсы өлкөдө окугуң келгенин айтасың."}'::JSONB, '[{"text_ru":"Откуда вы: Where are you from? — I am from Kyrgyzstan. From — «из»; после него называют страну или город.","text_ky":"Кайдан экениң: Where are you from? — I am from Kyrgyzstan. From — «-дан/-ден»; андан кийин өлкө же шаар аталат.","examples":[{"en":"— Where are you from? — I am from Kyrgyzstan.","ru":"— Откуда ты? — Я из Кыргызстана.","ky":"— Кайдансың? — Мен Кыргызстандан."},{"en":"Nurlan is from Osh.","ru":"Нурлан из Оша.","ky":"Нурлан Оштон."}]},{"text_ru":"Где живёте: I live in Bishkek. Слова: country — страна, city — город, capital — столица, village — село.","text_ky":"Кайда жашайсың: I live in Bishkek. Сөздөр: country — өлкө, city — шаар, capital — борбор, village — айыл.","examples":[{"en":"I live in Bishkek.","ru":"Я живу в Бишкеке.","ky":"Мен Бишкекте жашайм."},{"en":"Bishkek is the capital of Kyrgyzstan.","ru":"Бишкек — столица Кыргызстана.","ky":"Бишкек — Кыргызстандын борбору."}]},{"text_ru":"Куда хотите: I want to study in China. Учиться «в стране или городе» — study in; «в университете» — study at a university.","text_ky":"Кайда баргың келет: I want to study in China. Өлкөдө же шаарда окуу — study in; университетте окуу — study at a university.","examples":[{"en":"I am from Osh. I want to study in Italy.","ru":"Я из Оша. Я хочу учиться в Италии.","ky":"Мен Оштонмун. Италияда окугум келет."},{"en":"Aigerim wants to study in Malaysia.","ru":"Айгерим хочет учиться в Малайзии.","ky":"Айгерим Малайзияда окугусу келет."}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('daf2fd81-94f8-57ed-8bfe-cc26f2e9a641', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e01', 1, 'choice', '{"prompt_en":"— Where are you from? — ___","options":[{"id":"a","label":"I am from Kyrgyzstan.","explain_ru":"Верно: на вопрос «откуда» отвечают I am from + страна или город.","explain_ky":"Туура: «кайдансың» дегенге I am from + өлкө же шаар деп жооп беришет."},{"id":"b","label":"I am sixteen.","explain_ru":"Неверно: это ответ о возрасте на вопрос How old are you?","explain_ky":"Туура эмес: бул How old are you? суроосуна жаш жөнүндө жооп."},{"id":"c","label":"I am a student.","explain_ru":"Неверно: это ответ о занятии, а спрашивали, откуда вы.","explain_ky":"Туура эмес: бул иш-аракет жөнүндө жооп, суроо болсо кайдан экениң жөнүндө болчу."},{"id":"d","label":"I am fine.","explain_ru":"Неверно: I am fine — ответ на How are you? («как дела?»).","explain_ky":"Туура эмес: I am fine — How are you? («кандайсың?») суроосунун жообу."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('a612ad6c-4001-5fdf-8578-a16823eff329', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e02', 2, 'choice', '{"prompt_en":"— Where are you from? — I am ___ Bishkek.","options":[{"id":"a","label":"from","explain_ru":"Верно: в ответе на Where are you from? используется from — «из».","explain_ky":"Туура: Where are you from? суроосунун жообунда from колдонулат."},{"id":"b","label":"in","explain_ru":"Неверно: I am in Bishkek — «я (нахожусь) в Бишкеке», а спрашивали, откуда вы.","explain_ky":"Туура эмес: I am in Bishkek — «мен Бишкектемин», суроо болсо кайдан экениң жөнүндө."},{"id":"c","label":"at","explain_ru":"Неверно: at — «у, при» (at school), с городами про происхождение не используется.","explain_ky":"Туура эмес: at — «-да» (at school); кайдан экениң жөнүндө шаарлар менен колдонулбайт."},{"id":"d","label":"to","explain_ru":"Неверно: to — направление «в, к» (go to school), а не происхождение.","explain_ky":"Туура эмес: to — багыт «-га» (go to school), кайдан экенин билдирбейт."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('3de97367-13ac-5bb0-896e-dadbb358e983', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e03', 3, 'choice', '{"prompt_en":"We live ___ Osh.","options":[{"id":"a","label":"from","explain_ru":"Неверно: from — «из», а live отвечает на вопрос «где» — in.","explain_ky":"Туура эмес: from — «-дан», live болсо «кайда» деген суроого жооп берет — in."},{"id":"b","label":"in","explain_ru":"Верно: live in + город или страна.","explain_ky":"Туура: live in + шаар же өлкө."},{"id":"c","label":"on","explain_ru":"Неверно: on — «на» (on the table), с городами не используется.","explain_ky":"Туура эмес: on — «үстүндө» (on the table), шаарлар менен колдонулбайт."},{"id":"d","label":"to","explain_ru":"Неверно: to — направление движения, а live — про место.","explain_ky":"Туура эмес: to — кыймылдын багыты, live болсо орун жөнүндө."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('c8e76bb7-0c68-5d37-8c90-d68cd88be4d7', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e04', 4, 'matching', '{"instruction_ru":"Соедините слово с переводом.","instruction_ky":"Сөздү котормосу менен дал келтириңиз.","pairs":[{"left_en":"country","right_ru":"страна","right_ky":"өлкө"},{"left_en":"city","right_ru":"город","right_ky":"шаар"},{"left_en":"capital","right_ru":"столица","right_ky":"борбор"},{"left_en":"village","right_ru":"село","right_ky":"айыл"}],"explain_ru":"Country — вся страна, city — город, capital — главный город страны.","explain_ky":"Country — бүтүн өлкө, city — шаар, capital — өлкөнүн башкы шаары."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('4ea53afd-8451-5405-8fbe-55029f649922', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e05', 5, 'choice', '{"prompt_en":"Bishkek is the ___ of Kyrgyzstan.","options":[{"id":"a","label":"capital","explain_ru":"Верно: capital — столица, главный город страны.","explain_ky":"Туура: capital — борбор, өлкөнүн башкы шаары."},{"id":"b","label":"country","explain_ru":"Неверно: country — страна; Бишкек — город, а не страна.","explain_ky":"Туура эмес: country — өлкө; Бишкек — шаар, өлкө эмес."},{"id":"c","label":"village","explain_ru":"Неверно: village — село, а Бишкек — большой город.","explain_ky":"Туура эмес: village — айыл, Бишкек болсо чоң шаар."},{"id":"d","label":"lesson","explain_ru":"Неверно: lesson — «урок», слово из темы учёбы.","explain_ky":"Туура эмес: lesson — «сабак», окуу темасынын сөзү."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('ee60fb0c-447a-53ac-874b-2374bcc063eb', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e06', 6, 'short_answer', '{"prompt_ru":"Напишите по-английски: «Я из Кыргызстана».","prompt_ky":"Англисче жазыңыз: «Мен Кыргызстанданмын».","accepted":["I am from Kyrgyzstan","I am from Kyrgyzstan.","I''m from Kyrgyzstan","I''m from Kyrgyzstan."],"explain_ru":"I am from Kyrgyzstan. Не забудьте am: связка be в английском обязательна.","explain_ky":"I am from Kyrgyzstan. Am этишин унутпаңыз: англисчеде be байланыштыруучусу милдеттүү."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('216699a4-3752-56f0-80e8-4575328e3578', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e07', 7, 'choice', '{"prompt_en":"Aigerim ___ in Karakol.","options":[{"id":"a","label":"live","explain_ru":"Неверно: Aigerim — she, глаголу нужен -s: lives.","explain_ky":"Туура эмес: Aigerim — she, этишке -s керек: lives."},{"id":"b","label":"lives","explain_ru":"Верно: после he/she глагол получает -s: lives.","explain_ky":"Туура: he/she дегенден кийин этишке -s жалганат: lives."},{"id":"c","label":"is live","explain_ru":"Неверно: is с простой формой live вместе не ставятся.","explain_ky":"Туура эмес: is менен жөнөкөй live формасы бирге коюлбайт."},{"id":"d","label":"living","explain_ru":"Неверно: living без am/is/are не образует предложение.","explain_ky":"Туура эмес: living формасы am/is/are жок сүйлөм түзбөйт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('6c94da05-8a52-5c1a-880d-b020c885ef3e', '87ff1dca-bd45-5077-87fd-100b7dd58fd4', 'en-m1-l11-e08', 8, 'choice', '{"prompt_en":"Kanat wants to study ___ China.","options":[{"id":"a","label":"in","explain_ru":"Верно: учиться в стране — study in + страна.","explain_ky":"Туура: өлкөдө окуу — study in + өлкө."},{"id":"b","label":"from","explain_ru":"Неверно: from — «из», про происхождение, а не про место учёбы.","explain_ky":"Туура эмес: from — «-дан», кайдан экенин билдирет, окуу ордун эмес."},{"id":"c","label":"at","explain_ru":"Неверно: at идёт с университетом (at a university), со странами — in.","explain_ky":"Туура эмес: at университет менен колдонулат (at a university), өлкөлөр менен — in."},{"id":"d","label":"on","explain_ru":"Неверно: on — «на» (on Monday, on the table), со странами не используется.","explain_ky":"Туура эмес: on — «үстүндө» (on Monday, on the table), өлкөлөр менен колдонулбайт."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_lessons (id, module_id, lesson_key, order_index, metadata, theory)
VALUES ('89b7604b-965a-5fa1-8a76-8e584c2972b4', 'de7d4fe3-38b1-5971-858e-b03f71f9f2b2', 'en-m1-l12', 12, '{"title_ru":"Повторение модуля","title_ky":"Модулду кайталоо","goal_ru":"Закрепить самые трудные места уроков 1–11 на новых вариантах заданий.","goal_ky":"1–11-сабактардын эң кыйын жерлерин жаңы тапшырма варианттары менен бекемдейсиң."}'::JSONB, '[{"text_ru":"Это повторение. Здесь собраны места, где ошибаются чаще всего: -s после he/she, выбор am/is/are, to после want, вопросительные слова, числа на -teen и -ty. Ошибка — это нормально: разбор напомнит правило и урок, куда можно вернуться.","text_ky":"Бул кайталоо сабагы. Мында эң көп ката кетчү жерлер чогултулган: he/she дегенден кийинки -s, am/is/are тандоо, want дегенден кийинки to, суроо сөздөрү, -teen жана -ty сандары. Ката кетирүү — кадимки нерсе: разбор эрежени жана кайра кайрыла турган сабакты эскертет.","examples":[{"en":"She lives in Osh.","ru":"Она живёт в Оше.","ky":"Ал Ошто жашайт."},{"en":"I want to be a doctor.","ru":"Я хочу стать врачом.","ky":"Мен дарыгер болгум келет."},{"en":"thirteen — thirty","ru":"13 — 30","ky":"13 — 30"}]}]'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('60acffe5-591b-5547-85eb-1a9e393efae9', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e01', 1, 'choice', '{"source_lesson":7,"prompt_en":"My sister ___ English at school.","options":[{"id":"a","label":"study","explain_ru":"Неверно: my sister — she, глаголу нужен -s: studies (урок 7).","explain_ky":"Туура эмес: my sister — she, этишке -s керек: studies (7-сабак)."},{"id":"b","label":"studies","explain_ru":"Верно: после he/she глагол получает -s: studies.","explain_ky":"Туура: he/she дегенден кийин этишке -s жалганат: studies."},{"id":"c","label":"is study","explain_ru":"Неверно: is с простой формой study вместе не ставятся.","explain_ky":"Туура эмес: is менен жөнөкөй study формасы бирге коюлбайт."},{"id":"d","label":"studying","explain_ru":"Неверно: studying без am/is/are не образует предложение.","explain_ky":"Туура эмес: studying формасы am/is/are жок сүйлөм түзбөйт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('e74cbc5b-8454-552a-899e-c8dc33d97018', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e02', 2, 'choice', '{"source_lesson":4,"prompt_en":"My parents ___ teachers.","options":[{"id":"a","label":"is","explain_ru":"Неверно: parents — «они», множественное число; is — для одного (he/she/it). Урок 4.","explain_ky":"Туура эмес: parents — «алар», көптүк сан; is бирөө үчүн (he/she/it). 4-сабак."},{"id":"b","label":"am","explain_ru":"Неверно: am бывает только после I.","explain_ky":"Туура эмес: am формасы I дегенден кийин гана болот."},{"id":"c","label":"are","explain_ru":"Верно: parents — они, поэтому are: My parents are teachers.","explain_ky":"Туура: parents — алар, ошондуктан are: My parents are teachers."},{"id":"d","label":"be","explain_ru":"Неверно: be — начальная форма, в предложении нужна личная форма are.","explain_ky":"Туура эмес: be — баштапкы форма, сүйлөмдө are керек."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('0b79cbb0-ad2f-5e9d-8396-7a8a902888f8', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e03', 3, 'choice', '{"source_lesson":10,"prompt_en":"Bekzat wants ___ a pilot.","options":[{"id":"a","label":"be","explain_ru":"Неверно: после wants нужна частица to: wants to be (урок 10).","explain_ky":"Туура эмес: wants дегенден кийин to керек: wants to be (10-сабак)."},{"id":"b","label":"to be","explain_ru":"Верно: want(s) to be — «хотеть стать».","explain_ky":"Туура: want(s) to be — «болгусу келүү»."},{"id":"c","label":"being","explain_ru":"Неверно: после want(s) идёт to + начальная форма, а не -ing.","explain_ky":"Туура эмес: want(s) дегенден кийин to + баштапкы форма келет, -ing эмес."},{"id":"d","label":"is","explain_ru":"Неверно: is — личная форма be, после wants она не ставится.","explain_ky":"Туура эмес: is — be этишинин жактама формасы, wants дегенден кийин коюлбайт."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('d950e2b1-4936-547e-8d46-6009cb5e576d', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e04', 4, 'choice', '{"source_lesson":6,"prompt_en":"— ___ is your school? — It''s near the market.","options":[{"id":"a","label":"Who","explain_ru":"Неверно: who — «кто», а ответ near the market — о месте (урок 6).","explain_ky":"Туура эмес: who — «ким», near the market деген жооп болсо орун жөнүндө (6-сабак)."},{"id":"b","label":"What","explain_ru":"Неверно: what — «что», ответ назвал бы предмет.","explain_ky":"Туура эмес: what — «эмне», жооп затты атамак."},{"id":"c","label":"Where","explain_ru":"Верно: ответ о месте («рядом с рынком») — вопрос where.","explain_ky":"Туура: жооп орун жөнүндө («базардын жанында») — суроо where."},{"id":"d","label":"When","explain_ru":"Неверно: when — «когда», ответ был бы о времени.","explain_ky":"Туура эмес: when — «качан», жооп убакыт жөнүндө болмок."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('7c5654fd-9582-5ea5-857f-161a0ef7724b', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e05', 5, 'choice', '{"source_lesson":8,"prompt_en":"— ___ — It''s ninety som.","options":[{"id":"a","label":"How old are you?","explain_ru":"Неверно: how old — о возрасте, ответ был бы I''m fifteen (урок 8).","explain_ky":"Туура эмес: how old — жаш жөнүндө, жооп I''m fifteen болмок (8-сабак)."},{"id":"b","label":"How much is it?","explain_ru":"Верно: ответ называет цену, значит вопрос — how much.","explain_ky":"Туура: жоопто баа айтылат, демек суроо — how much."},{"id":"c","label":"How are you?","explain_ru":"Неверно: how are you — «как дела?», ответ был бы I''m fine.","explain_ky":"Туура эмес: how are you — «кандайсың?», жооп I''m fine болмок."},{"id":"d","label":"What time is it?","explain_ru":"Неверно: это вопрос о времени, ответ был бы It''s nine o''clock.","explain_ky":"Туура эмес: бул убакыт жөнүндө суроо, жооп It''s nine o''clock болмок."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('bcfa568b-e30a-5f0b-8075-ff2055ae6ae4', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e06', 6, 'choice', '{"source_lesson":3,"prompt_ru":"Выберите число sixty.","prompt_ky":"Sixty санын тандаңыз.","options":[{"id":"a","label":"6","explain_ru":"Неверно: 6 — six, без окончания (урок 3).","explain_ky":"Туура эмес: 6 — six, мүчөсүз (3-сабак)."},{"id":"b","label":"16","explain_ru":"Неверно: 16 — sixteen, с окончанием -teen.","explain_ky":"Туура эмес: 16 — sixteen, -teen мүчөсү менен."},{"id":"c","label":"60","explain_ru":"Верно: -ty — десятки, sixty — 60.","explain_ky":"Туура: -ty — ондуктар, sixty — 60."},{"id":"d","label":"66","explain_ru":"Неверно: 66 — sixty-six, составное число.","explain_ky":"Туура эмес: 66 — sixty-six, курама сан."}],"answer_index":2}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('3367f968-d35c-55ef-86cb-599fc13ea184', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e07', 7, 'short_answer', '{"source_lesson":2,"prompt_ru":"Запишите слово, которое продиктовали по буквам: P-L-A-N.","prompt_ky":"Тамгалап айтылган сөздү жазыңыз: P-L-A-N.","accepted":["plan","Plan","PLAN"],"explain_ru":"P-L-A-N — plan («план»). Имена букв: «пи-эл-эй-эн» (урок 2).","explain_ky":"P-L-A-N — plan («план»). Тамгалардын аттары: «пи-эл-эй-эн» (2-сабак)."}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('40c696c0-85f7-5cdc-8776-f41ae07923d6', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e08', 8, 'choice', '{"source_lesson":11,"prompt_en":"— Where are you from? — I am ___ Naryn.","options":[{"id":"a","label":"from","explain_ru":"Верно: в ответе на Where are you from? используется from — «из» (урок 11).","explain_ky":"Туура: Where are you from? суроосунун жообунда from колдонулат (11-сабак)."},{"id":"b","label":"in","explain_ru":"Неверно: I am in Naryn — «я в Нарыне» (где нахожусь), а спрашивали, откуда вы.","explain_ky":"Туура эмес: I am in Naryn — «мен Нарындамын» (кайда экениң), суроо болсо кайдан экениң жөнүндө."},{"id":"c","label":"at","explain_ru":"Неверно: at с городами про происхождение не используется.","explain_ky":"Туура эмес: at шаарлар менен кайдан экенин билдирбейт."},{"id":"d","label":"to","explain_ru":"Неверно: to — направление движения («в, к»), а не происхождение.","explain_ky":"Туура эмес: to — кыймылдын багыты, кайдан экенин билдирбейт."}],"answer_index":0}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('8584f790-d253-5c41-84e4-0f6fcc7f785b', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e09', 9, 'reading', '{"source_lesson":9,"passage_en":"Adilet is from Talas. He is seventeen. He wants to study at a university in China. Every day he learns twenty new English words and reads one short text. On Saturday he plays football with his brothers.","questions":[{"id":"en-m1-l12-e09-q1","prompt_en":"What does Adilet want?","options":[{"id":"a","label":"to study at a university in China","explain_ru":"Верно: He wants to study at a university in China.","explain_ky":"Туура: He wants to study at a university in China."},{"id":"b","label":"to work in a café","explain_ru":"Неверно: кафе и работа в тексте не упоминаются.","explain_ky":"Туура эмес: текстте кафе жана жумуш айтылган эмес."},{"id":"c","label":"to play volleyball","explain_ru":"Неверно: в тексте футбол, и это не мечта, а субботнее занятие.","explain_ky":"Туура эмес: текстте футбол, жана бул максат эмес, ишембидеги көнүгүү."},{"id":"d","label":"to buy a ticket","explain_ru":"Неверно: про билет в тексте ничего нет.","explain_ky":"Туура эмес: текстте билет жөнүндө эч нерсе жок."}],"answer_index":0},{"id":"en-m1-l12-e09-q2","prompt_en":"How many new words does Adilet learn every day?","options":[{"id":"a","label":"twelve","explain_ru":"Неверно: twelve — 12, а в тексте twenty — 20.","explain_ky":"Туура эмес: twelve — 12, текстте болсо twenty — 20."},{"id":"b","label":"twenty","explain_ru":"Верно: he learns twenty new English words — двадцать слов.","explain_ky":"Туура: he learns twenty new English words — жыйырма сөз."},{"id":"c","label":"seventeen","explain_ru":"Неверно: seventeen — это возраст Адилета, а не число слов.","explain_ky":"Туура эмес: seventeen — Адилеттин жашы, сөздөрдүн саны эмес."},{"id":"d","label":"two","explain_ru":"Неверно: two — 2; в тексте twenty — 20.","explain_ky":"Туура эмес: two — 2; текстте twenty — 20."}],"answer_index":1}]}'::JSONB);

INSERT INTO platform_private.learning_exercises (id, lesson_id, exercise_key, order_index, exercise_type, body)
VALUES ('4246fbba-5a57-55c5-8605-c2d3af206352', '89b7604b-965a-5fa1-8a76-8e584c2972b4', 'en-m1-l12-e10', 10, 'choice', '{"source_lesson":7,"prompt_ru":"Выберите правильное предложение.","prompt_ky":"Туура сүйлөмдү тандаңыз.","options":[{"id":"a","label":"She is study English.","explain_ru":"Неверно: is рядом с глаголом действия study лишний (урок 7).","explain_ky":"Туура эмес: study иш-аракет этишинин жанында is ашыкча (7-сабак)."},{"id":"b","label":"She studies English.","explain_ru":"Верно: глагол действия сразу после she, с -s: studies.","explain_ky":"Туура: иш-аракет этиши she дегенден кийин эле, -s менен: studies."},{"id":"c","label":"She study English.","explain_ru":"Неверно: после she глаголу нужен -s: studies.","explain_ky":"Туура эмес: she дегенден кийин этишке -s керек: studies."},{"id":"d","label":"She is studies English.","explain_ru":"Неверно: здесь две ошибки сразу — лишний is и форма с -s после него.","explain_ky":"Туура эмес: мында эки ката бар — ашыкча is жана андан кийинки -s формасы."}],"answer_index":1}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('bf56c901-7335-5deb-811b-ae730ec826ca', 'project-manager', '1.0.0', '{"id":"project-manager","title_ru":"Менеджер проектов","title_ky":"Долбоор менеджери","orvis_scales":["leadership","organization"],"day_in_work_ru":"Утро начинается с короткой встречи: команда за десять минут рассказывает, что сделано вчера и что мешает сегодня. Потом менеджер открывает план проекта и сверяет сроки — одна задача задерживается, и нужно решить, кого подключить, чтобы не сдвинулся весь график. Днём — созвон с заказчиком: обсудить, что уже готово показать, и честно предупредить о рисках. Между встречами он отвечает на десятки сообщений и следит, чтобы у бюджета сходились цифры. Ближе к вечеру собирает короткий отчёт о состоянии проекта: что идёт по плану, что нет и почему. День заканчивается списком решений на завтра — их менеджер продумывает заранее, чтобы утренняя встреча заняла те же десять минут.","day_in_work_ky":"Таң эрте кыска жолугушуудан башталат: команда он мүнөттө кечээ эмне бүткөнүн жана бүгүн эмне тоскоол болуп жатканын айтып берет. Андан кийин менеджер долбоордун планын ачып, мөөнөттөрдү салыштырат — бир тапшырма кечигип жатат, бүт график жылып кетпеши үчүн кимди кошумча тартуу керектигин чечиш керек. Күндүзү буюртмачы менен сүйлөшүү: эмне даяр экенин талкуулап, тобокелдиктер жөнүндө чынын айтуу. Жолугушуулардын ортосунда ондогон билдирүүлөргө жооп берип, бюджеттин цифралары туура келишин көзөмөлдөйт. Кечке жуук долбоордун абалы боюнча кыска отчёт даярдайт: эмне план боюнча баратат, эмне жок жана эмне үчүн. Күн эртеңки чечимдердин тизмеси менен аяктайт — аларды менеджер алдын ала ойлонуп коёт, эртең мененки жолугушуу дагы он эле мүнөт болушу үчүн.","environment_ru":"Офис или удалённая работа за компьютером, большая часть дня — общение: встречи, переписка, звонки. Вокруг всегда команда — разработчики, дизайнеры, заказчики. Ритм задают сроки: спокойные недели чередуются с плотными.","environment_ky":"Кеңсе же компьютер менен алыстан иштөө, күндүн көбү — баарлашуу: жолугушуулар, кат алышуу, чалуулар. Айланада дайыма команда бар — иштеп чыгуучулар, дизайнерлер, буюртмачылар. Ыргакты мөөнөттөр аныктайт: тынч жумалар тыгыз жумалар менен алмашып турат.","skills_ru":["Планирование и расстановка приоритетов","Понятное устное и письменное общение","Работа с рисками: замечать проблему раньше, чем она выросла","Ведение бюджета и учёт затрат","Умение договариваться с разными людьми","Работа с инструментами планирования (доски задач, календари)"],"skills_ky":["Пландоо жана артыкчылыктарды аныктоо","Оозеки жана жазуу жүзүндө түшүнүктүү баарлашуу","Тобокелдиктер менен иштөө: көйгөйдү чоңоюп кетээрден мурун байкоо","Бюджет жүргүзүү жана чыгымдарды эсепке алуу","Ар кандай адамдар менен сүйлөшө билүү","Пландоо куралдары менен иштөө (тапшырма такталары, календарлар)"],"interesting_ru":["Виден результат: проект, который без тебя развалился бы на куски, доходит до финиша","Каждый проект — новая область: сегодня приложение, завтра стройка или фестиваль","Много живого общения с очень разными людьми"],"interesting_ky":["Натыйжа көрүнөт: сенсиз быт-чыт болуп кетмек долбоор бүтүшүнө жетет","Ар бир долбоор — жаңы тармак: бүгүн колдонмо, эртең курулуш же фестиваль","Абдан ар түрдүү адамдар менен көп жандуу баарлашуу"],"hard_ru":["Отвечаешь за срок и результат, даже когда причина задержки не в тебе","Постоянные переключения: десятки тем и людей за один день","Приходится сообщать неприятные новости заказчику и команде"],"hard_ky":["Кечигүүнүн себеби сенде болбосо да, мөөнөт жана натыйжа үчүн сен жооп бересиң","Тынымсыз которулуу: бир күндө ондогон темалар жана адамдар","Буюртмачыга жана командага жагымсыз кабарларды айтууга туура келет"],"trial_task_ru":"Спланируйте маленький домашний «проект» — например, семейный ужин на шесть человек. Выпишите все задачи (меню, покупки, готовка, стол), к каждой поставьте время и ответственного. Затем найдите два места, где всё может пойти не так, и придумайте запасной план. Если уложились в 15 минут и план читается без пояснений — это и есть работа менеджера в миниатюре.","trial_task_ky":"Кичинекей үй «долбоорун» пландаңыз — мисалы, алты кишилик үй-бүлөлүк кечки тамак. Бардык тапшырмаларды жазып чыгыңыз (меню, базар, тамак жасоо, дасторкон), ар бирине убакыт жана жооптуу адамды белгилеңиз. Анан баары бузулуп кетиши мүмкүн болгон эки жерди таап, кошумча план ойлоп табыңыз. 15 мүнөткө батып, план түшүндүрмөсүз эле окулса — бул менеджердин ишинин кичине үлгүсү.","study_directions_ru":["Менеджмент","Управление проектами","Бизнес-администрирование"],"study_directions_ky":["Менеджмент","Долбоорлорду башкаруу","Бизнес-администрлөө"],"linked_program_refs":[{"institution_photo_key":"kozminski-university","program_hint":"Bachelor in Management"},{"institution_photo_key":"bilkent-university","program_hint":"Management"},{"institution_photo_key":"university-of-perugia","program_hint":"Engineering Management"}],"sources":["https://www.onetonline.org/link/summary/13-1082.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('d0681dcd-bf56-5aef-8b02-c5d3861ed3fd', 'marketing-manager', '1.0.0', '{"id":"marketing-manager","title_ru":"Маркетолог","title_ky":"Маркетолог","orvis_scales":["leadership","creativity"],"day_in_work_ru":"День открывается цифрами: сколько людей вчера увидели рекламу, сколько кликнули, сколько купили. Одна кампания работает хуже ожиданий — маркетолог разбирается, дело в картинке, тексте или в том, что предложение показали не тем людям. Потом обсуждение с дизайнером: какие три варианта баннера подготовить к пятнице. После обеда — планирование запуска нового продукта: кому он нужен, как о нём рассказать и сколько это будет стоить. Вечером маркетолог пишет короткий разбор для руководства: что сработало, что нет, куда двигать бюджет. Между делом он постоянно смотрит, что делают конкуренты — не чтобы копировать, а чтобы не отстать.","day_in_work_ky":"Күн цифралардан башталат: кечээ жарнаманы канча адам көрдү, канчасы басты, канчасы сатып алды. Бир кампания күткөндөн начар иштеп жатат — маркетолог себебин издейт: сүрөттөбү, тексттеби же сунушту туура эмес адамдарга көрсөтүштүбү. Анан дизайнер менен талкуу: жумага чейин баннердин кайсы үч вариантын даярдоо керек. Түштөн кийин — жаңы продукттун чыгышын пландоо: ал кимге керек, ал жөнүндө кантип айтуу керек жана бул канча турат. Кечинде маркетолог жетекчилик үчүн кыска талдоо жазат: эмне иштеди, эмне жок, бюджетти кайда буруу керек. Ортодо ал атаандаштар эмне кылып жатканын дайыма карап турат — көчүрүү үчүн эмес, артта калбоо үчүн.","environment_ru":"Офис или удалённая работа, много встреч с дизайнерами, аналитиками и руководством. Половина дня проходит в таблицах и рекламных кабинетах, половина — в обсуждениях идей. Темп высокий: запуски, дедлайны, быстрые решения.","environment_ky":"Кеңсе же алыстан иштөө, дизайнерлер, аналитиктер жана жетекчилик менен көп жолугушуулар. Күндүн жарымы таблицаларда жана жарнама кабинеттеринде, жарымы — идеяларды талкуулоодо өтөт. Темп бийик: жаңы продукттарды чыгаруу, мөөнөттөр, тез чечимдер.","skills_ru":["Анализ данных: понять из цифр, что работает","Понимание аудитории: кому и зачем нужен продукт","Ясные короткие тексты","Работа с дизайнерами: внятно объяснить задачу","Планирование бюджета кампаний","Быстрая проверка идей маленькими экспериментами"],"skills_ky":["Маалыматты талдоо: цифралардан эмне иштеп жатканын түшүнүү","Аудиторияны түшүнүү: продукт кимге жана эмнеге керек","Так жана кыска тексттер жазуу","Дизайнерлер менен иштөө: тапшырманы түшүнүктүү айтып берүү","Кампаниялардын бюджетин пландоо","Идеяларды кичине эксперименттер менен тез текшерүү"],"interesting_ru":["Соединение творчества и математики: придумал — измерил — улучшил","Результат виден быстро: кампания запущена сегодня, цифры уже завтра","Каждый продукт заставляет разобраться в новой сфере и новых людях"],"interesting_ky":["Чыгармачылык менен математиканын айкалышы: ойлоп таптың — өлчөдүң — жакшырттың","Натыйжа тез көрүнөт: кампания бүгүн иштеди, цифралар эртең эле келет","Ар бир продукт жаңы тармакты жана жаңы адамдарды түшүнүүгө түртөт"],"hard_ru":["Хорошая идея может не сработать, и это видно всем по цифрам","Бюджет ограничен, а ожидания руководства — нет","Правила площадок и поведение аудитории меняются постоянно"],"hard_ky":["Жакшы идея иштебей калышы мүмкүн, жана муну цифралардан баары көрөт","Бюджет чектелүү, ал эми жетекчиликтин күтүүлөрү — жок","Аянтчалардын эрежелери жана аудиториянын жүрүм-туруму тынымсыз өзгөрөт"],"trial_task_ru":"Выберите любимый местный продукт — например, напиток или кафе. За 15 минут напишите три разных коротких объявления о нём: одно для школьников, одно для родителей, одно для туристов. Сравните: что пришлось поменять в словах и картинке для каждой группы? Это главный навык маркетолога — говорить с разными людьми на их языке.","trial_task_ky":"Жактырган жергиликтүү продуктту тандаңыз — мисалы, суусундук же кафе. 15 мүнөттө ал жөнүндө үч башка кыска жарнама жазыңыз: бири окуучуларга, бири ата-энелерге, бири туристтерге. Салыштырыңыз: ар бир топ үчүн сөздөрдө жана сүрөттө эмнени өзгөртүүгө туура келди? Бул маркетологдун башкы көндүмү — ар кандай адамдар менен алардын тилинде сүйлөшүү.","study_directions_ru":["Маркетинг","Менеджмент","Коммуникации и реклама"],"study_directions_ky":["Маркетинг","Менеджмент","Коммуникация жана жарнама"],"linked_program_refs":[{"institution_photo_key":"university-of-bergamo","program_hint":"International Management and Marketing"},{"institution_photo_key":"iulm-university","program_hint":"Corporate Communication and Public Relations"},{"institution_photo_key":"hangzhou-normal-university-hznu","program_hint":"International Business (Cross-border eCommerce)"}],"sources":["https://www.onetonline.org/link/summary/11-2021.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('66f67700-ddc5-5195-8d9b-4e78382ee55f', 'hotel-manager', '1.0.0', '{"id":"hotel-manager","title_ru":"Менеджер отеля","title_ky":"Мейманкана менеджери","orvis_scales":["leadership","organization"],"day_in_work_ru":"День начинается с обхода: чистые ли холлы, готовы ли номера к заезду, всё ли в порядке на завтраке. Потом планёрка с администраторами и горничными — сегодня заезжает большая группа, надо перераспределить людей. В обед приходит недовольный гость: кондиционер шумит, — и менеджер решает вопрос так, чтобы человек ушёл спокойным, а не обиженным. После — работа с цифрами: загрузка отеля, цены на следующий месяц, счета поставщиков. Вечером он проверяет отзывы за неделю и разбирает с командой один неприятный: не спорить с гостем, а понять, что изменить. График плавающий: отель живёт круглосуточно, и иногда смена выпадает на выходные.","day_in_work_ky":"Күн айланып чыгуудан башталат: холлдор тазабы, бөлмөлөр конокторго даярбы, эртең мененки тамакта баары жайындабы. Анан администраторлор жана тазалоочулар менен планёрка — бүгүн чоң топ келет, адамдарды кайра бөлүштүрүү керек. Түштө нааразы конок келет: кондиционер ызылдап жатат, — менеджер маселени адам таарынбай, тынч кетээрдей кылып чечет. Андан кийин — цифралар менен иштөө: мейманкананын жүктөмү, кийинки айдын баалары, жеткирүүчүлөрдүн эсептери. Кечинде ал жуманын пикирлерин карап, бир жагымсызын команда менен талдайт: конок менен талашпай, эмнени өзгөртүү керектигин түшүнүү. График жылма: мейманкана суткасына жашайт, кээде смена дем алышка туш келет.","environment_ru":"Отель — ресепшен, номера, ресторан, склад, кабинет. Постоянное живое общение с гостями и командой, много ходьбы. Работа сменная, включая праздники и высокий сезон.","environment_ky":"Мейманкана — ресепшн, бөлмөлөр, ресторан, кампа, кабинет. Коноктор жана команда менен тынымсыз жандуу баарлашуу, көп басуу. Иш сменалуу, майрамдарды жана бийик сезонду кошкондо.","skills_ru":["Спокойное решение конфликтов","Организация работы команды и смен","Внимание к деталям: от чистоты до счетов","Ведение бюджета и ценообразование","Гостеприимство: замечать, что нужно человеку, раньше, чем он попросил","Иностранные языки для общения с гостями"],"skills_ky":["Чыр-чатактарды сабырдуу чечүү","Команданын жана сменалардын ишин уюштуруу","Майда-чүйдөгө көңүл буруу: тазалыктан эсептерге чейин","Бюджет жүргүзүү жана баа коюу","Меймандостук: адамга эмне керектигин ал сурай электе байкоо","Коноктор менен сүйлөшүү үчүн чет тилдер"],"interesting_ru":["Живая работа с людьми со всего мира","Результат ощущается сразу: довольный гость возвращается и советует отель другим","Профессия открывает путь в туризм в любой стране"],"interesting_ky":["Дүйнөнүн ар кайсы жеринен келген адамдар менен жандуу иш","Натыйжа дароо сезилет: ыраазы конок кайра келет жана мейманкананы башкаларга сунуштайт","Кесип каалаган өлкөдө туризмге жол ачат"],"hard_ru":["Сменный график: праздники и выходные часто рабочие","Претензии гостей принимаешь на себя, даже если виноват не ты","Много рутины: проверки, счета, графики повторяются каждый день"],"hard_ky":["Сменалуу график: майрамдар жана дем алыш көп учурда жумуш күнү","Күнөө сенде болбосо да, коноктордун дооматтарын өзүң кабыл аласың","Күнүмдүк иштер көп: текшерүүлөр, эсептер, графиктер күн сайын кайталанат"],"trial_task_ru":"Представьте, что к вам домой на две ночи приезжает гость из другой страны, который не говорит по-русски и по-кыргызски. За 15 минут составьте для него памятку на простом английском: как пользоваться душем и Wi-Fi, где завтрак, что посмотреть рядом, куда звонить, если что-то нужно. Перечитайте глазами гостя: всё ли понятно без вопросов? Это и есть суть гостеприимства — продумать заранее.","trial_task_ky":"Үйүңүзгө эки түнгө орусча да, кыргызча да билбеген чет өлкөлүк конок келет деп элестетиңиз. 15 мүнөттө ага жөнөкөй англис тилинде эскертме түзүңүз: душ жана Wi-Fi кантип иштейт, эртең мененки тамак кайда, жакын жерде эмнени көрсө болот, бир нерсе керек болсо кайда чалуу керек. Коноктун көзү менен кайра окуп чыгыңыз: баары суроосуз түшүнүктүүбү? Меймандостуктун маңызы ушул — алдын ала ойлонуу.","study_directions_ru":["Гостиничный менеджмент","Туризм","Бизнес-администрирование"],"study_directions_ky":["Мейманкана менеджменти","Туризм","Бизнес-администрлөө"],"linked_program_refs":[{"institution_photo_key":"taylors","program_hint":"Bachelor of International Hospitality Management (Honours)"},{"institution_photo_key":"gbs-he-malta","program_hint":"BSc (Hons) Business Management"}],"sources":["https://www.onetonline.org/link/summary/11-9081.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('6fa449ef-23af-5d63-845d-be2e5db2db3d', 'accountant', '1.0.0', '{"id":"accountant","title_ru":"Бухгалтер и аудитор","title_ky":"Бухгалтер жана аудитор","orvis_scales":["organization"],"day_in_work_ru":"Утро — за сверкой: вчерашние платежи компании должны сойтись с выписками банка до копейки. Одна сумма не сходится, и бухгалтер, как детектив, идёт по цепочке документов, пока не находит причину — дважды проведённый счёт. Дальше — обработка новых счетов и подготовка платежей поставщикам. После обеда он считает налоги за квартал и проверяет, всё ли оформлено так, чтобы у проверки не было вопросов. В конце месяца добавляется большая задача — отчёт о том, сколько компания заработала и потратила. Именно по этим цифрам директор решает, можно ли нанимать людей и запускать новое направление.","day_in_work_ky":"Таң — салыштырып текшерүү менен: компаниянын кечээки төлөмдөрү банктын көчүрмөлөрү менен тыйынына чейин дал келиши керек. Бир сумма дал келбей жатат, бухгалтер детективдей болуп документтердин чынжырын аңтарат — акыры себебин табат: бир эсеп эки жолу өткөрүлүптүр. Андан ары — жаңы эсептерди иштетүү жана жеткирүүчүлөргө төлөмдөрдү даярдоо. Түштөн кийин ал кварталдын салыктарын эсептеп, текшерүүдө суроо жаралбагыдай баары туура таризделгенин карайт. Айдын аягында чоң тапшырма кошулат — компания канча тапты жана канча короттту деген отчёт. Дал ушул цифраларга карап директор адам алууга жана жаңы багытты баштоого болобу деп чечет.","environment_ru":"Тихий офис, компьютер, бухгалтерские программы и таблицы. Работа в основном сидячая и самостоятельная, но с постоянными контактами с банком, налоговой и коллегами. В отчётные периоды нагрузка заметно растёт.","environment_ky":"Тынч кеңсе, компьютер, бухгалтердик программалар жана таблицалар. Иш негизинен отуруп, өз алдынча жүрөт, бирок банк, салык кызматы жана кесиптештер менен байланыш үзүлбөйт. Отчёт мезгилдеринде жүк кыйла көбөйөт.","skills_ru":["Внимательность: ошибка в одной цифре меняет весь отчёт","Уверенная математика и работа с таблицами","Знание правил учёта и налогов","Аккуратность с документами и сроками","Умение объяснять цифры простыми словами","Честность: с деньгами компании нельзя иначе"],"skills_ky":["Кылдаттык: бир цифрадагы ката бүт отчётту өзгөртөт","Ишенимдүү математика жана таблицалар менен иштөө","Эсеп жана салык эрежелерин билүү","Документтерге жана мөөнөттөргө тактык","Цифраларды жөнөкөй сөз менен түшүндүрө билүү","Чынчылдык: компаниянын акчасы менен башкача болбойт"],"interesting_ru":["Момент, когда всё сошлось до копейки, приносит настоящее удовольствие","Профессия нужна каждой организации — от кафе до министерства","Ты видишь бизнес насквозь: цифры рассказывают, как компания живёт на самом деле"],"interesting_ky":["Баары тыйынына чейин дал келген учур чыныгы канааттануу берет","Кесип ар бир уюмга керек — кафеден министрликке чейин","Бизнести ичинен көрөсүң: компания чындыгында кантип жашап жатканын цифралар айтып берет"],"hard_ru":["Много однотипной точной работы, где нельзя расслабиться","Отчётные периоды — плотные недели с переработками","Правила и налоги регулярно меняются, приходится доучиваться постоянно"],"hard_ky":["Бир түрдүү так иш көп, эс алууга болбойт","Отчёт мезгилдери — кошумча иштөө менен өткөн тыгыз жумалар","Эрежелер жана салыктар үзгүлтүксүз өзгөрөт, дайыма кошумча окууга туура келет"],"trial_task_ru":"Ведите один день учёт своих или семейных расходов. Записывайте каждую трату: время, на что, сколько. Вечером разнесите всё по категориям (еда, транспорт, связь, прочее), посчитайте итог и проверьте, сходится ли он с тем, сколько денег реально ушло. Если нашли расхождение и сумели объяснить его — вы только что провели свою первую сверку.","trial_task_ky":"Бир күн өзүңүздүн же үй-бүлөңүздүн чыгымдарын эсепке алыңыз. Ар бир чыгымды жазыңыз: убактысы, эмнеге, канча. Кечинде баарын категорияларга бөлүңүз (тамак, транспорт, байланыш, башка), жыйынтыгын эсептеп, чындап кеткен акча менен дал келерин текшериңиз. Айырма таап, аны түшүндүрө алсаңыз — сиз азыр эле биринчи салыштырып текшерүүңүздү жүргүздүңүз.","study_directions_ru":["Бухгалтерский учёт","Финансы","Аудит"],"study_directions_ky":["Бухгалтердик эсеп","Финансы","Аудит"],"linked_program_refs":[{"institution_photo_key":"southwestern-university-of-finance-and-economics","program_hint":"Accounting"},{"institution_photo_key":"kozminski-university","program_hint":"Bachelor in Finance and Accounting"},{"institution_photo_key":"vistula-university-uczelnia-vistula","program_hint":"Finance and Accounting"}],"sources":["https://www.onetonline.org/link/summary/13-2011.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('889bc363-e5fb-5ff7-8e05-39e807f07f33', 'logistics-specialist', '1.0.0', '{"id":"logistics-specialist","title_ru":"Логист","title_ky":"Логист","orvis_scales":["organization","leadership"],"day_in_work_ru":"С утра логист проверяет, где сейчас грузы: одна машина стоит на границе дольше плана, и нужно быстро решить — ждать или перестраивать маршрут. Он звонит перевозчику, уточняет документы и предупреждает склад о сдвиге. Потом садится за расчёт нового маршрута для клиента: сравнивает сроки и стоимость по железной дороге, автотранспортом и в комбинации. После обеда — переговоры с поставщиком упаковки: та же надёжность, но дешевле. Ближе к вечеру он сверяет остатки на складе с системой, чтобы завтрашние отгрузки не сорвались. День логиста — это десятки маленьких решений, из которых складывается одно большое: груз пришёл вовремя.","day_in_work_ky":"Эртең менен логист жүктөр азыр кайда экенин текшерет: бир унаа чек арада пландан узак турат, тез чечиш керек — күтүү керекпи же маршрутту өзгөртүү керекпи. Ал ташуучуга чалып, документтерди тактап, кампаны жылыштыруу жөнүндө эскертет. Анан кардар үчүн жаңы маршрутту эсептөөгө отурат: темир жол, автотранспорт жана айкалыштыруу боюнча мөөнөттөр менен бааларды салыштырат. Түштөн кийин — таңгак жеткирүүчүсү менен сүйлөшүү: ошол эле ишенимдүүлүк, бирок арзаныраак. Кечке жуук ал кампадагы калдыктарды система менен салыштырат, эртеңки жөнөтүүлөр үзгүлтүккө учурабашы үчүн. Логисттин күнү — ондогон кичине чечимдер, алардан бир чоң нерсе куралат: жүк өз убагында келди.","environment_ru":"Офис с телефоном и системой отслеживания, регулярные выезды на склад или терминал. Постоянные звонки и переписка: перевозчики, таможня, склады, клиенты. Ритм зависит от дорог, погоды и границ, поэтому день редко идёт точно по плану.","environment_ky":"Телефону жана байкоо системасы бар кеңсе, кампага же терминалга үзгүлтүксүз баруу. Тынымсыз чалуулар жана кат алышуу: ташуучулар, бажы, кампалар, кардарлар. Ыргак жолдорго, аба ырайына жана чек араларга байланыштуу, ошондуктан күн так план боюнча сейрек өтөт.","skills_ru":["Планирование маршрутов и сроков","Быстрые решения при сбоях","Работа с документами перевозок и таможни","Расчёт стоимости и сравнение вариантов","Переговоры с перевозчиками и поставщиками","Аккуратный учёт: склад, остатки, отгрузки"],"skills_ky":["Маршруттарды жана мөөнөттөрдү пландоо","Үзгүлтүк болгондо тез чечим кабыл алуу","Ташуу жана бажы документтери менен иштөө","Наркты эсептөө жана варианттарды салыштыруу","Ташуучулар жана жеткирүүчүлөр менен сүйлөшүүлөр","Так эсеп: кампа, калдыктар, жөнөтүүлөр"],"interesting_ru":["Ты видишь мировую торговлю изнутри: как товар из Гуанчжоу оказывается в Бишкеке","Каждый сбой — головоломка со многими решениями","Профессия востребована на всех перекрёстках торговых путей, включая Центральную Азию"],"interesting_ky":["Дүйнөлүк сооданы ичинен көрөсүң: товар Гуанчжоудан Бишкекке кантип жетет","Ар бир үзгүлтүк — бир нече чечими бар табышмак","Кесип соода жолдорунун бардык кесилиштеринде, анын ичинде Борбор Азияда суроо-талапка ээ"],"hard_ru":["Многое не в твоей власти: погода, границы, поломки — а отвечать тебе","Срочные звонки случаются вечером и в выходные","Цена ошибки высока: простой машины или склада стоит реальных денег"],"hard_ky":["Көп нерсе сенин колуңда эмес: аба ырайы, чек аралар, бузулуулар — бирок жооп сага","Шашылыш чалуулар кечинде жана дем алышта да болот","Катанын баасы жогору: унаанын же кампанын токтоп турушу чыныгы акча турат"],"trial_task_ru":"Спланируйте доставку: представьте, что вам нужно передать коробку 30×30 см из вашего города родственникам в другой город страны. За 15 минут найдите и сравните два реальных способа (маршрутка/автобус, почта, попутчики, курьер): сколько стоит, сколько дней идёт, где груз может застрять. Выберите один способ и напишите три предложения, почему он лучший. Вы только что решили типовую задачу логиста.","trial_task_ky":"Жеткирүүнү пландаңыз: шаарыңыздан өлкөнүн башка шаарындагы туугандарга 30×30 см коробканы жеткириш керек деп элестетиңиз. 15 мүнөттө эки чыныгы жолду таап, салыштырыңыз (маршрутка/автобус, почта, жол боюнча адамдар, курьер): канча турат, канча күн жүрөт, жүк кайда токтоп калышы мүмкүн. Бир жолду тандап, эмне үчүн ал мыкты экенин үч сүйлөм менен жазыңыз. Сиз азыр эле логисттин типтүү маселесин чечтиңиз.","study_directions_ru":["Логистика и управление цепями поставок","Международная торговля","Менеджмент"],"study_directions_ky":["Логистика жана жеткирүү чынжырларын башкаруу","Эл аралык соода","Менеджмент"],"linked_program_refs":[{"institution_photo_key":"xiamen-malaysia","program_hint":"Bachelor of Management in International Business (Honours)"},{"institution_photo_key":"krakow-university-of-economics-uniwersytet-ekonomiczny-w-krakowie","program_hint":"International Business"},{"institution_photo_key":"msu","program_hint":"Bachelor in Industrial Management (Hons)"}],"sources":["https://www.onetonline.org/link/summary/13-1081.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('b03a07fd-91ce-5542-8777-3a3b50833612', 'financial-analyst', '1.0.0', '{"id":"financial-analyst","title_ru":"Финансовый аналитик","title_ky":"Финансылык аналитик","orvis_scales":["organization","analysis"],"day_in_work_ru":"Утро аналитика начинается с новостей рынка: что произошло за ночь с валютами, ценами и компаниями, за которыми он следит. Потом — работа с моделью в таблице: компания хочет открыть филиал, и нужно посчитать, когда вложения окупятся при трёх разных сценариях. Цифры не берутся из воздуха: аналитик копается в отчётах компании, статистике и ценах поставщиков. После обеда он собирает выводы в короткую презентацию — три слайда, на которых видно главное. Затем встреча с руководством: защищать расчёт, отвечать на неудобные вопросы, честно показывать риски. Хороший аналитик отличается тем, что говорит не «будет так», а «вот три варианта и вот что на них влияет».","day_in_work_ky":"Аналитиктин таңы рынок жаңылыктарынан башталат: түн ичинде валюталар, баалар жана ал байкаган компаниялар менен эмне болду. Анан — таблицадагы модель менен иштөө: компания филиал ачкысы келет, үч башка сценарийде салымдар качан актала турганын эсептөө керек. Цифралар абадан алынбайт: аналитик компаниянын отчётторун, статистиканы жана жеткирүүчүлөрдүн бааларын аңтарат. Түштөн кийин ал корутундуларды кыска презентацияга чогултат — башкысы көрүнүп турган үч слайд. Андан кийин жетекчилик менен жолугушуу: эсепти коргоо, ыңгайсыз суроолорго жооп берүү, тобокелдиктерди чын көрсөтүү. Жакшы аналитик «ушундай болот» дебейт, «мына үч вариант жана аларга эмне таасир этет» дейт — айырмасы ушунда.","environment_ru":"Офис банка, инвестиционной или обычной компании; работа за компьютером с таблицами и данными. Много самостоятельного анализа, но результаты постоянно обсуждаются с коллегами и руководством. В периоды сделок и отчётности темп жёсткий.","environment_ky":"Банктын, инвестициялык же жөнөкөй компаниянын кеңсеси; таблицалар жана маалыматтар менен компьютерде иштөө. Өз алдынча талдоо көп, бирок жыйынтыктар дайыма кесиптештер жана жетекчилик менен талкууланат. Келишимдер жана отчёттуулук мезгилинде темп катаал.","skills_ru":["Уверенная математика и работа с таблицами","Построение финансовых моделей и сценариев","Чтение отчётности компаний","Критическое мышление: проверять источник каждой цифры","Ясное изложение выводов — устно и на слайдах","Аккуратность: одна ошибка в формуле ломает весь расчёт"],"skills_ky":["Ишенимдүү математика жана таблицалар менен иштөө","Финансылык моделдерди жана сценарийлерди түзүү","Компаниялардын отчётторун окуу","Сын ойлом: ар бир цифранын булагын текшерүү","Корутундуларды так айтып берүү — оозеки жана слайддарда","Тактык: формуладагы бир ката бүт эсепти бузат"],"interesting_ru":["По твоим расчётам принимаются настоящие решения о больших деньгах","Каждая задача — новая отрасль: сегодня энергетика, завтра торговые сети","Видно, как устроена экономика на самом деле, а не в учебнике"],"interesting_ky":["Сенин эсептериң боюнча чоң акча жөнүндө чыныгы чечимдер кабыл алынат","Ар бир маселе — жаңы тармак: бүгүн энергетика, эртең соода тармактары","Экономика окуу китебинде эмес, чындыгында кандай иштээри көрүнөт"],"hard_ru":["Будущее не обязано слушаться модели: даже хороший прогноз может не сбыться","Высокая цена ошибки и придирчивая проверка каждого вывода","Многочасовая сосредоточенная работа с цифрами подходит не всем"],"hard_ky":["Келечек моделге баш ийүүгө милдеттүү эмес: жакшы божомол да аткарылбай калышы мүмкүн","Катанын баасы жогору жана ар бир корутунду кылдат текшерилет","Цифралар менен көп сааттык топтолгон иш баарына эле туура келбейт"],"trial_task_ru":"Посчитайте простую окупаемость: представьте, что вы ставите возле школы автомат с водой за 50 000 сом. Прикиньте на бумаге: сколько бутылок в день он продаст, какая прибыль с бутылки, сколько уходит на аренду места и обслуживание. Через сколько месяцев автомат окупится? Теперь пересчитайте пессимистичный вариант — продажи вдвое ниже. Два сценария на одном листе — это уже настоящая финансовая модель.","trial_task_ky":"Жөнөкөй акталууну эсептеңиз: мектептин жанына 50 000 сомго суу автоматын коёсуз деп элестетиңиз. Кагазга болжолдоңуз: күнүнө канча бөтөлкө сатылат, бир бөтөлкөдөн канча пайда, орун ижарасына жана тейлөөгө канча кетет. Автомат канча айда акталат? Эми пессимисттик вариантты кайра эсептеңиз — сатуу эки эсе төмөн. Бир барактагы эки сценарий — бул чыныгы финансылык модель.","study_directions_ru":["Финансы","Экономика","Бизнес-аналитика"],"study_directions_ky":["Финансы","Экономика","Бизнес-аналитика"],"linked_program_refs":[{"institution_photo_key":"masaryk-university","program_hint":"Business Management and Finance"},{"institution_photo_key":"southwestern-university-of-finance-and-economics","program_hint":"Finance"},{"institution_photo_key":"beijing-language-and-culture-university","program_hint":"Finance"}],"sources":["https://www.onetonline.org/link/summary/13-2051.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('303207ba-6a2d-5640-8436-975e5fb77cc5', 'language-teacher', '1.0.0', '{"id":"language-teacher","title_ru":"Преподаватель иностранного языка","title_ky":"Чет тил мугалими","orvis_scales":["altruism","erudition"],"day_in_work_ru":"Первый урок — в девять, но преподаватель приходит раньше: разложить карточки, проверить колонки, вывести упражнение на экран. Сегодня группа начинающих учится заказывать еду — половина урока проходит в парах, класс шумит на изучаемом языке, и это хороший шум. На перемене подходит ученица, у которой не даются времена глаголов, — короткое объяснение один на один иногда даёт больше, чем целый урок. Днём — проверка вчерашних работ: не просто отметить ошибки, а понять, какая тема не усвоена у всей группы. Потом преподаватель готовит завтрашнее занятие и подбирает живые примеры вместо скучных из учебника. Вечером отвечает на вопросы учеников в чате группы и отмечает, кого надо подбодрить: язык бросают не из-за сложности, а из-за потери веры в себя.","day_in_work_ky":"Биринчи сабак саат тогуздо, бирок мугалим эртерээк келет: карточкаларды жайып, колонкаларды текшерип, көнүгүүнү экранга чыгаруу керек. Бүгүн башталгыч топ тамак заказ кылганды үйрөнөт — сабактын жарымы жуп-жуп болуп өтөт, класс үйрөнүп жаткан тилде шуулдайт, бул жакшы ызы-чуу. Тыныгууда этиштин чактарын түшүнбөгөн окуучу келет — бирме-бир кыска түшүндүрүү кээде бүтүндөй сабактан көбүрөөк берет. Күндүзү — кечээки иштерди текшерүү: жөн гана каталарды белгилөө эмес, бүт топ кайсы теманы өздөштүрбөгөнүн түшүнүү. Анан мугалим эртеңки сабакты даярдап, окуу китебиндеги зериктирме мисалдардын ордуна жандуу мисалдарды тандайт. Кечинде топтун чатында окуучулардын суроолоруна жооп берип, кимди колдош керектигин белгилейт: тилди татаалдыгынан эмес, өзүнө болгон ишеним жоголгондон таштап коюшат.","environment_ru":"Класс, языковой центр или онлайн-платформа; доска, экран, много разговоров и работы в группах. Часть дня — подготовка уроков и проверка работ в тишине. Возможна работа с очень разными возрастами: от школьников до взрослых.","environment_ky":"Класс, тил борбору же онлайн-платформа; доска, экран, көп сүйлөшүү жана топтордо иштөө. Күндүн бир бөлүгү — тынчтыкта сабак даярдоо жана иштерди текшерүү. Абдан ар кандай жаштагылар менен иштөө мүмкүн: окуучулардан чоңдорго чейин.","skills_ru":["Свободное владение преподаваемым языком","Умение объяснять сложное просто и по-разному","Терпение и внимание к каждому ученику","Планирование уроков и учебной программы","Умение держать внимание группы","Честная и бережная обратная связь"],"skills_ky":["Окуткан тилди эркин билүү","Татаалды жөнөкөй жана ар кандай жол менен түшүндүрө билүү","Чыдамкайлык жана ар бир окуучуга көңүл буруу","Сабактарды жана окуу программасын пландоо","Топтун көңүлүн кармай билүү","Чынчыл жана этият пикир айтуу"],"interesting_ru":["Видно, как человек за год проходит путь от «здравствуйте» до свободного разговора","Язык — это ещё и культура: фильмы, музыка, поездки становятся частью работы","Профессия мобильна: преподавать можно в школе, онлайн и в другой стране"],"interesting_ky":["Адам бир жылда «саламатсызбы» дегенден эркин сүйлөшүүгө чейин өскөнү көрүнөт","Тил — бул маданият дагы: кинолор, музыка, саякаттар иштин бөлүгү болуп калат","Кесип мобилдүү: мектепте, онлайн жана башка өлкөдө окутса болот"],"hard_ru":["Проверка работ и подготовка занимают вечера, а не только рабочие часы","Прогресс учеников не всегда зависит от тебя, но переживаешь за каждого","Одну и ту же тему приходится объяснять в сотый раз с той же энергией"],"hard_ky":["Иштерди текшерүү жана даярдануу жумуш сааттарын гана эмес, кечтерди да ээлейт","Окуучулардын ийгилиги дайыма эле сенден көз каранды эмес, бирок ар бири үчүн кабатырланасың","Бир эле теманы жүзүнчү жолу ошол эле энергия менен түшүндүрүүгө туура келет"],"trial_task_ru":"Выберите пять слов на любом языке, который вы знаете хотя бы немного, и научите им кого-то из семьи за 15 минут. Заранее придумайте: как объяснить значение без перевода (жесты, картинки, примеры), как повторить слова три раза по-разному и как проверить в конце, что они запомнились. Заметьте, что было труднее всего: объяснить, удержать внимание или проверить. Это и есть три главных умения преподавателя.","trial_task_ky":"Өзүңүз аз да болсо билген каалаган тилден беш сөз тандап, аларды 15 мүнөттө үй-бүлөңүздөгү кимдир-бирөөгө үйрөтүңүз. Алдын ала ойлонуңуз: маанисин котормосуз кантип түшүндүрүү керек (жаңдоо, сүрөттөр, мисалдар), сөздөрдү үч жолу ар кандай жол менен кантип кайталоо жана аягында эсте калганын кантип текшерүү. Эң кыйыны эмне болгонун байкаңыз: түшүндүрүүбү, көңүлдү кармообу же текшерүүбү. Мугалимдин үч башкы чеберчилиги дал ушулар.","study_directions_ru":["Педагогика","Лингвистика","Преподавание языков"],"study_directions_ky":["Педагогика","Лингвистика","Тилдерди окутуу"],"linked_program_refs":[{"institution_photo_key":"beijing-normal-university","program_hint":"International Chinese Language Education"},{"institution_photo_key":"wuhan-university","program_hint":"Teaching Chinese to Speakers of Other Languages"},{"institution_photo_key":"nanchang-university","program_hint":"Teaching Chinese to Speakers of Other Languages"}],"sources":["https://www.onetonline.org/link/summary/25-1124.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('05515b11-d609-509e-854b-bc764157840f', 'nurse', '1.0.0', '{"id":"nurse","title_ru":"Медицинская сестра / медбрат","title_ky":"Медайым / медага","orvis_scales":["altruism"],"day_in_work_ru":"Смена начинается с передачи: ночная сестра рассказывает, как прошла ночь у каждого пациента и на что обратить внимание. Потом обход — измерить давление и температуру, раздать лекарства строго по назначениям, проверить капельницы. У пациента из третьей палаты изменилось состояние — сестра замечает это первой и сразу сообщает врачу: часто именно её наблюдательность решает исход. Днём — процедуры, перевязки, подготовка пациентов к обследованиям и много записей: каждое действие фиксируется в карте. Между делами она объясняет пациенту, как принимать лекарства дома, и успокаивает его родных. К концу смены — снова передача: следующая сестра должна знать всё, что знаешь ты.","day_in_work_ky":"Смена өткөрүп берүүдөн башталат: түнкү медайым ар бир бейтаптын түнү кандай өткөнүн жана эмнеге көңүл буруу керектигин айтып берет. Анан кыдыруу — кан басымын жана температураны өлчөө, дарыларды так дайындоо боюнча таратуу, капельницаларды текшерүү. Үчүнчү палатадагы бейтаптын абалы өзгөрдү — медайым муну биринчи байкап, дароо дарыгерге билдирет: көп учурда дал анын байкагычтыгы жыйынтыкты чечет. Күндүзү — процедуралар, таңуулар, бейтаптарды текшерүүлөргө даярдоо жана көп жазуу: ар бир аракет картага түшөт. Ортодо ал бейтапка үйдө дарыларды кантип ичүүнү түшүндүрүп, туугандарын тынчтандырат. Смена аягында — кайрадан өткөрүп берүү: кийинки медайым сен билгендин баарын билиши керек.","environment_ru":"Больница, поликлиника или медицинский центр; пост, палаты, процедурный кабинет. Работа на ногах, сменная, включая ночи и праздники. Вокруг постоянно люди — пациенты, родные, врачи, — и строгие правила гигиены и безопасности.","environment_ky":"Оорукана, поликлиника же медициналык борбор; пост, палаталар, процедура бөлмөсү. Иш бут үстүндө, сменалуу, түндөрдү жана майрамдарды кошкондо. Айланада дайыма адамдар — бейтаптар, туугандар, дарыгерлер — жана гигиена менен коопсуздуктун катуу эрежелери.","skills_ru":["Точное выполнение медицинских назначений","Наблюдательность: заметить изменение состояния раньше всех","Спокойствие в стрессовых ситуациях","Аккуратное ведение медицинских записей","Умение поддержать пациента и его близких","Физическая выносливость","Работа в команде с врачами и коллегами"],"skills_ky":["Медициналык дайындоолорду так аткаруу","Байкагычтык: абалдын өзгөрүшүн баарынан мурун байкоо","Стресстик кырдаалдарда сабырдуулук","Медициналык жазууларды тыкан жүргүзүү","Бейтапты жана анын жакындарын колдой билүү","Физикалык чыдамкайлык","Дарыгерлер жана кесиптештер менен командада иштөө"],"interesting_ru":["Помощь видна каждый день: людям становится лучше, и в этом есть твой вклад","Профессия нужна в любой стране мира — медсёстры востребованы везде","Постоянное развитие: новые методы, оборудование, специализации"],"interesting_ky":["Жардам күн сайын көрүнөт: адамдар айыгып баратат, мында сенин салымың бар","Кесип дүйнөнүн каалаган өлкөсүндө керек — медайымдар бардык жерде суроо-талапка ээ","Тынымсыз өнүгүү: жаңы ыкмалар, жабдуулар, адистиктер"],"hard_ru":["Ночные смены и работа в праздники","Физически тяжело: целый день на ногах","Эмоциональная нагрузка: боль и страх пациентов проходят через тебя","Цена ошибки очень высока, расслабиться нельзя"],"hard_ky":["Түнкү сменалар жана майрамдарда иштөө","Физикалык жактан оор: күн бою бут үстүндө","Эмоциялык жүк: бейтаптардын ооруусу жана коркунучу сенден өтөт","Катанын баасы өтө жогору, эс алууга болбойт"],"trial_task_ru":"Освойте базовое наблюдение: научитесь правильно измерять пульс — на запястье, за 30 секунд, умножая на два. Измерьте пульс у себя и у двух членов семьи в покое, запишите результаты с временем измерения. Потом попросите одного из них сделать 15 приседаний и измерьте снова. Оформите записи так, чтобы по ним другой человек понял всё без ваших объяснений — точная запись наблюдений и есть основа сестринского дела.","trial_task_ky":"Негизги байкоону үйрөнүңүз: тамырдын кагышын туура өлчөгөндү үйрөнүңүз — билектен, 30 секунд ичинде, экиге көбөйтүп. Өзүңүздүн жана үй-бүлөңүздүн эки мүчөсүнүн тынч абалдагы тамыр кагышын өлчөп, жыйынтыктарды өлчөө убактысы менен жазыңыз. Анан алардын бирөөсүнөн 15 отуруп-туруу жасоону өтүнүп, кайра өлчөңүз. Жазууларды башка адам сиздин түшүндүрмөңүзсүз баарын түшүнгүдөй кылып тариздеңиз — байкоолордун так жазылышы медайым ишинин негизи.","study_directions_ru":["Сестринское дело","Лечебное дело"],"study_directions_ky":["Медайым иши","Дарылоо иши"],"linked_program_refs":[{"institution_photo_key":"medical-university-of-gdansk","program_hint":"Bachelor of Nursing"},{"institution_photo_key":"medical-university-of-gdansk","program_hint":"Premedical Course"}],"sources":["https://www.onetonline.org/link/summary/29-1141.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('73584190-7216-5c3d-84dc-b2536795e79c', 'physician', '1.0.0', '{"id":"physician","title_ru":"Врач","title_ky":"Дарыгер","orvis_scales":["altruism","analysis"],"day_in_work_ru":"Приём начинается в восемь: первый пациент жалуется на усталость, и задача врача — из десятка возможных причин найти настоящую. Он расспрашивает, осматривает, назначает анализы и объясняет, зачем каждый из них нужен. Дальше пациенты идут один за другим: у кого-то простуда, у кого-то давление, а у кого-то за обычной жалобой прячется серьёзная болезнь, которую нельзя пропустить. Между приёмами врач разбирает готовые результаты обследований и корректирует лечение тем, кто был на прошлой неделе. Одному пациенту приходится долго объяснять, почему таблетки нужно пить полным курсом, даже когда стало лучше. Вечером — записи в картах и полчаса с медицинским журналом: медицина обновляется быстрее, чем любой учебник.","day_in_work_ky":"Кабыл алуу саат сегизде башталат: биринчи бейтап чарчоого арызданат, дарыгердин милдети — ондогон мүмкүн себептен чыныгысын табуу. Ал сурап, карап чыгып, анализдерди дайындап, ар биринин эмнеге керектигин түшүндүрөт. Андан ары бейтаптар биринин артынан бири келет: биринде суук тийүү, биринде кан басымы, ал эми биринде жөнөкөй арыздын артында өткөрүп жиберүүгө болбогон олуттуу оору жашынып жатат. Кабыл алуулардын ортосунда дарыгер даяр текшерүү жыйынтыктарын карап, өткөн жумада келгендердин дарылоосун оңдойт. Бир бейтапка жакшы болуп калса да, эмне үчүн дарыны толук курс ичиш керектигин узак түшүндүрүүгө туура келет. Кечинде — карталарга жазуулар жана медициналык журнал менен жарым саат: медицина каалаган окуу китебинен тезирээк жаңыланат.","environment_ru":"Поликлиника, больница или частный центр; кабинет приёма, палаты, иногда дежурства. Постоянный поток людей и решений, у каждого из которых есть цена. Путь в профессию долгий: шесть лет университета и практика после него.","environment_ky":"Поликлиника, оорукана же жеке борбор; кабыл алуу бөлмөсү, палаталар, кээде нөөмөттөр. Адамдардын жана чечимдердин тынымсыз агымы, ар биринин өз баасы бар. Кесипке жол узун: алты жыл университет жана андан кийинки практика.","skills_ru":["Глубокие знания биологии и химии как фундамент","Клиническое мышление: собрать диагноз из разрозненных признаков","Внимательное слушание пациента","Спокойные решения в условиях неопределённости","Умение объяснять диагноз и лечение простыми словами","Готовность учиться всю жизнь"],"skills_ky":["Пайдубал катары биология менен химияны терең билүү","Клиникалык ойлом: чачыранды белгилерден диагноз куроо","Бейтапты кунт коюп угуу","Белгисиздик шартында сабырдуу чечимдер","Диагнозду жана дарылоону жөнөкөй сөз менен түшүндүрө билүү","Өмүр бою окууга даярдык"],"interesting_ru":["Каждый пациент — задача, где правильный ответ реально меняет жизнь человека","Профессия соединяет науку и живое общение с людьми","Врачи нужны везде и всегда — эта работа не исчезнет"],"interesting_ky":["Ар бир бейтап — туура жообу адамдын жашоосун чындап өзгөрткөн маселе","Кесип илимди жана адамдар менен жандуу баарлашууну бириктирет","Дарыгерлер бардык жерде жана ар дайым керек — бул жумуш жоголбойт"],"hard_ru":["Самый долгий путь обучения среди массовых профессий","Ответственность за жизнь: ошибка может стоить очень дорого","Эмоционально тяжёлые разговоры и потери — часть работы","Дежурства, очереди и большой объём бумажной работы"],"hard_ky":["Массалык кесиптердин ичинен эң узун окуу жолу","Өмүр үчүн жоопкерчилик: ката өтө кымбатка турушу мүмкүн","Эмоциялык оор сүйлөшүүлөр жана жоготуулар — иштин бир бөлүгү","Нөөмөттөр, кезектер жана көп кагаз иши"],"trial_task_ru":"Потренируйте клиническое мышление на безопасном примере. Попросите члена семьи загадать бытовую «неисправность» (например, телефон быстро разряжается) и разрешите задать только семь вопросов, чтобы найти причину. Сформулируйте вопросы так, чтобы каждый отсекал часть версий, а не проверял одну догадку. Потом запишите свою «историю болезни»: жалоба, вопросы, ответы, вывод. Именно так врач сужает круг от жалобы до диагноза.","trial_task_ky":"Клиникалык ойломду коопсуз мисалда машыктырыңыз. Үй-бүлө мүчөңүздөн турмуштук бир «бузукту» ойлоп табууну өтүнүңүз (мисалы, телефон тез отуруп калат) жана себебин табуу үчүн жети гана суроо берүүгө уруксат алыңыз. Суроолорду ар бири бир божомолду текшербей, версиялардын бир бөлүгүн кесип салгыдай кылып түзүңүз. Анан өзүңүздүн «оору тарыхыңызды» жазыңыз: арыз, суроолор, жооптор, корутунду. Дарыгер арыздан диагнозго чейин чөйрөнү дал ушинтип тарытат.","study_directions_ru":["Лечебное дело (Medicine)","Подготовительные медицинские программы"],"study_directions_ky":["Дарылоо иши (Medicine)","Даярдоо медициналык программалары"],"linked_program_refs":[{"institution_photo_key":"medical-university-of-warsaw","program_hint":"Medicine — единый шестилетний цикл"},{"institution_photo_key":"huazhong-university-of-science-and-technology-hust","program_hint":"Clinical Medicine (MBBS)"},{"institution_photo_key":"medical-university-of-gdansk","program_hint":"Premedical Course"}],"sources":["https://www.onetonline.org/link/summary/29-1215.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('dad3ee66-d9b6-5599-81b6-98ae0d00ad6c', 'graphic-designer', '1.0.0', '{"id":"graphic-designer","title_ru":"Графический дизайнер","title_ky":"Графикалык дизайнер","orvis_scales":["creativity"],"day_in_work_ru":"Утро начинается с брифа: кофейне нужен логотип, и заказчик описывает всё словами «что-то тёплое, но современное». Дизайнер переводит эти слова в конкретику: собирает референсы, смотрит, как выглядят конкуренты, набрасывает первые эскизы на бумаге. Потом — работа в графическом редакторе: три разных направления, у каждого свои шрифты и цвета. Днём приходит правка по вчерашнему проекту: «сделайте логотип побольше» — и нужно не обидеться, а понять, какую проблему заказчик на самом деле хочет решить. После обеда дизайнер готовит макеты к печати: проверяет цвета, отступы и размеры файлов, потому что ошибка уйдёт в тираж. День заканчивается любимой частью — свободные полчаса на эксперимент со шрифтами для собственного проекта.","day_in_work_ky":"Таң брифтен башталат: кофеканага логотип керек, буюртмачы баарын «жылуу, бирок заманбап бир нерсе» деген сөздөр менен сүрөттөйт. Дизайнер бул сөздөрдү конкреттикке которот: референстерди чогултат, атаандаштар кандай көрүнөрүн карайт, алгачкы эскиздерди кагазга түшүрөт. Анан — графикалык редактордо иштөө: үч башка багыт, ар биринин өз шрифттери жана түстөрү. Күндүзү кечээки долбоор боюнча оңдоо келет: «логотипти чоңураак кылгыла» — таарынбай, буюртмачы чындыгында кайсы маселени чечкиси келгенин түшүнүш керек. Түштөн кийин дизайнер макеттерди басууга даярдайт: түстөрдү, чегинүүлөрдү жана файл өлчөмдөрүн текшерет, анткени ката тиражга кетет. Күн эң сүйүктүү бөлүк менен аяктайт — өз долбоору үчүн шрифттер менен эксперимент кылууга эркин жарым саат.","environment_ru":"Студия, офис или работа из дома; компьютер с графическими программами, планшет, много визуального материала вокруг. Работа то самостоятельная и тихая, то плотное общение с заказчиками и командой. Дедлайны — постоянная часть профессии.","environment_ky":"Студия, кеңсе же үйдөн иштөө; графикалык программалары бар компьютер, планшет, айланада көп визуалдык материал. Иш бирде өз алдынча жана тынч, бирде буюртмачылар жана команда менен тыгыз баарлашуу. Дедлайндар — кесиптин туруктуу бөлүгү.","skills_ru":["Композиция, цвет и типографика","Уверенная работа в графических редакторах","Умение услышать заказчика за его словами","Подготовка макетов к печати и публикации","Аргументация своих решений","Насмотренность: постоянное изучение хорошего дизайна"],"skills_ky":["Композиция, түс жана типографика","Графикалык редакторлордо ишенимдүү иштөө","Буюртмачынын сөзүнүн артындагы оюн уга билүү","Макеттерди басууга жана жарыялоого даярдоо","Өз чечимдерин негиздей билүү","Көз таразасы: жакшы дизайнды тынымсыз изилдөө"],"interesting_ru":["Твои работы живут в городе: вывески, упаковки, афиши, приложения","Каждый заказ — новая тема: сегодня кофейня, завтра спортивный клуб","Профессия позволяет работать удалённо на заказчиков из любой страны"],"interesting_ky":["Иштериң шаарда жашайт: көрнөктөр, таңгактар, афишалар, колдонмолор","Ар бир буюртма — жаңы тема: бүгүн кофекана, эртең спорт клубу","Кесип каалаган өлкөдөгү буюртмачыларга алыстан иштөөгө мүмкүндүк берет"],"hard_ru":["Вкусы у всех разные: работу, которая тебе дорога, могут забраковать","Много правок и компромиссов с заказчиком","Дедлайны и работа по ночам перед сдачей проекта","Начинающим платят мало, портфолио важнее диплома"],"hard_ky":["Табит ар кимде ар кандай: сага кымбат ишти четке кагышы мүмкүн","Буюртмачы менен көп оңдоолор жана компромисстер","Дедлайндар жана долбоорду тапшыруу алдында түнкү иш","Башталгычтарга аз төлөшөт, портфолио дипломдон маанилүү"],"trial_task_ru":"Возьмите афишу школьного события (или придумайте её) и сделайте два варианта на бумаге или в бесплатном редакторе: один — где главное объявлено самым крупным, второй — где всё написано одинаковым размером. Покажите оба варианта трём людям на три секунды каждый и спросите, что они успели понять. Разница в ответах — это и есть работа дизайнера: управлять вниманием.","trial_task_ky":"Мектеп иш-чарасынын афишасын алыңыз (же өзүңүз ойлоп табыңыз) жана кагазга же акысыз редактордо эки вариант жасаңыз: биринде башкы нерсе эң чоң жазылган, экинчисинде баары бирдей өлчөмдө. Эки вариантты тең үч адамга үч секунддан көрсөтүп, эмнени түшүнүп үлгүргөнүн сураңыз. Жооптордогу айырма — дизайнердин иши дал ушул: көңүлдү башкаруу.","study_directions_ru":["Графический дизайн","Визуальные коммуникации","Коммуникационный дизайн"],"study_directions_ky":["Графикалык дизайн","Визуалдык коммуникациялар","Коммуникациялык дизайн"],"linked_program_refs":[{"institution_photo_key":"prague-college","program_hint":"BA (Hons) Graphic Design"},{"institution_photo_key":"tsinghua-university","program_hint":"Visual Communication Design"},{"institution_photo_key":"communication-university-of-zhejiang","program_hint":"Visual Communication Design"},{"institution_photo_key":"scuola-politecnica-di-design","program_hint":"BA (Hons) Communication Design & Creative Strategy"}],"sources":["https://www.onetonline.org/link/summary/27-1024.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('9d052b05-02b7-533d-84cd-07ad8624fdec', 'interface-designer', '1.0.0', '{"id":"interface-designer","title_ru":"Дизайнер интерфейсов","title_ky":"Интерфейс дизайнери","orvis_scales":["creativity","analysis"],"day_in_work_ru":"День начинается с записи вчерашнего теста: пять человек пытались оформить заказ в приложении, и трое застряли на одном и том же экране. Дизайнер пересматривает запись и ищет причину — кнопка есть, но её никто не видит. Дальше он перерисовывает экран в редакторе прототипов: два варианта, чтобы было что сравнить. Днём — обсуждение с разработчиками: один вариант красивее, но сложнее в реализации, и нужно найти честный баланс. После обеда дизайнер собирает кликабельный прототип нового раздела и сам проходит его пальцем на телефоне: где-то цель маленькая, где-то шаг лишний. Вечером он записывает задачи на завтрашний тест — интерфейс считается готовым не тогда, когда он нравится, а когда им легко пользуются.","day_in_work_ky":"Күн кечээки тесттин жазуусунан башталат: беш адам колдонмодо заказ жасаганга аракет кылды, үчөө бир эле экранда токтоп калды. Дизайнер жазууну кайра карап, себебин издейт — баскыч бар, бирок аны эч ким көрбөйт. Андан ары ал экранды прототип редакторунда кайра тартат: салыштырганга эки вариант болушу үчүн. Күндүзү — иштеп чыгуучулар менен талкуу: бир вариант сулуураак, бирок жасалышы татаал, калыс балансты табыш керек. Түштөн кийин дизайнер жаңы бөлүмдүн басып көрө турган прототибин чогултуп, аны телефондо өз колу менен өтөт: бир жерде бута кичине, бир жерде ашыкча кадам бар. Кечинде эртеңки тестке тапшырмаларды жазат — интерфейс жакканда эмес, аны колдонуу оңой болгондо даяр деп эсептелет.","environment_ru":"Офис IT-компании или удалённая работа; редакторы прототипов, созвоны с командой, записи пользовательских тестов. Работа на стыке дизайна, психологии и техники. Результат постоянно проверяется на живых людях.","environment_ky":"IT-компаниянын кеңсеси же алыстан иштөө; прототип редакторлору, команда менен чалуулар, колдонуучу тесттеринин жазуулары. Иш дизайндын, психологиянын жана техниканын кесилишинде. Натыйжа дайыма жандуу адамдарда текшерилет.","skills_ru":["Проектирование удобных сценариев: от входа до цели за минимум шагов","Визуальный дизайн: сетки, цвет, типографика","Прототипирование и пользовательские тесты","Умение слушать пользователей, а не только заказчика","Общий язык с разработчиками: что реально построить","Внимание к деталям: состояние кнопок, ошибки, пустые экраны"],"skills_ky":["Ыңгайлуу сценарийлерди долбоорлоо: кирүүдөн максатка минималдуу кадам менен","Визуалдык дизайн: торлор, түс, типографика","Прототип жасоо жана колдонуучу тесттери","Буюртмачыны гана эмес, колдонуучуларды уга билүү","Иштеп чыгуучулар менен жалпы тил: эмнени чындап куруп болот","Майда-чүйдөгө көңүл: баскычтардын абалы, каталар, бош экрандар"],"interesting_ru":["Твоими экранами люди пользуются каждый день, не замечая их — и это признак хорошей работы","Видно измеримый результат: было три ошибки на заказ, стало ноль","Профессия на растущем рынке: интерфейсы нужны каждому сервису"],"interesting_ky":["Сенин экрандарыңды адамдар күн сайын байкабай колдонушат — бул жакшы иштин белгиси","Өлчөнө турган натыйжа көрүнөт: заказга үч ката болчу, нөл болду","Кесип өсүп жаткан рынокто: интерфейстер ар бир сервиске керек"],"hard_ru":["Красивое и удобное — не одно и то же, приходится жертвовать любимыми решениями","Много итераций: экран переделывается по пять раз","Своё мнение нужно постоянно защищать данными, а не вкусом"],"hard_ky":["Сулуу менен ыңгайлуу — бир эле нерсе эмес, сүйүктүү чечимдерден баш тартууга туура келет","Итерация көп: экран беш жолудан кайра жасалат","Өз пикириңди табит менен эмес, маалымат менен дайыма коргош керек"],"trial_task_ru":"Проведите мини-тест интерфейса. Выберите приложение, которым пользуетесь, и придумайте задание для члена семьи, который его не знает: например, «найди, сколько стоит доставка». Молча наблюдайте и записывайте: куда человек нажал сначала, где остановился, что сказал вслух. Три наблюдения за 15 минут дадут вам главный навык профессии — видеть интерфейс чужими глазами.","trial_task_ky":"Интерфейстин мини-тестин өткөрүңүз. Өзүңүз колдонгон колдонмону тандап, аны билбеген үй-бүлө мүчөсүнө тапшырма ойлоп табыңыз: мисалы, «жеткирүү канча турарын тап». Унчукпай байкап, жазып туруңуз: адам адегенде кайда басты, кайда токтоду, эмнени үн чыгарып айтты. 15 мүнөттөгү үч байкоо сизге кесиптин башкы көндүмүн берет — интерфейсти бөтөн көз менен көрүү.","study_directions_ru":["Дизайн цифровых продуктов","Мультимедиа и веб-технологии","Человеко-компьютерное взаимодействие"],"study_directions_ky":["Санариптик продукт дизайны","Мультимедиа жана веб-технологиялар","Адам-компьютер өз ара аракети"],"linked_program_refs":[{"institution_photo_key":"communication-university-of-zhejiang","program_hint":"Digital Media Technology"},{"institution_photo_key":"utm","program_hint":"Bachelor of Computer Science (Graphics and Multimedia Software) with Honours"},{"institution_photo_key":"scuola-politecnica-di-design","program_hint":"BA (Hons) Communication Design & Creative Strategy"}],"sources":["https://www.onetonline.org/link/summary/15-1255.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('9861c75e-27e2-5ed0-8d1e-caa465e1b876', 'architect', '1.0.0', '{"id":"architect","title_ru":"Архитектор","title_ky":"Архитектор","orvis_scales":["creativity","production"],"day_in_work_ru":"Утро — за чертежами: архитектор дорабатывает планировку школы, которую команда сдаёт через месяц. Задача звучит просто — чтобы коридоры не пересекались с потоком столовой, — но решение меняет полздания. Потом созвон с инженерами: их вентиляция не проходит под потолком, и нужно вместе найти вариант, не убивающий высоту залов. Днём архитектор едет на стройку другого объекта: проверить, что строители читают чертежи, а не строят по памяти. На месте выясняется, что заказчик хочет перенести вход, — и надо объяснить, что за этой «мелочью» тянутся лестницы, пандусы и нормы безопасности. Вечером — тихий час эскизов: конкурс на городскую библиотеку, и есть идея, которую хочется проверить на бумаге.","day_in_work_ky":"Таң — чиймелер менен: архитектор команда бир айдан кийин тапшыра турган мектептин планировкасын жеткире иштеп жатат. Маселе жөнөкөй угулат — коридорлор ашкананын агымы менен кесилишпесин, — бирок чечим жарым имаратты өзгөртөт. Анан инженерлер менен чалуу: алардын желдетүүсү шыптын астынан батпай жатат, залдардын бийиктигин өлтүрбөгөн вариантты чогуу табыш керек. Күндүзү архитектор башка объекттин курулушуна барат: куруучулар эстеп эмес, чийме окуп жатканын текшерүү. Жеринен буюртмачы кире беришти которгусу келгени белгилүү болот — бул «майда нерсенин» артында тепкичтер, пандустар жана коопсуздук нормалары турганын түшүндүрүш керек. Кечинде — эскиздердин тынч сааты: шаардык китепканага конкурс бар, кагазда текшергиси келген идея бар.","environment_ru":"Бюро или студия с компьютерами и макетами, плюс регулярные выезды на стройплощадки в любую погоду. Работа с чертёжными программами, нормами и живыми людьми: заказчиками, инженерами, строителями. Проекты длинные — от месяцев до лет.","environment_ky":"Компьютерлери жана макеттери бар бюро же студия, кошумча каалаган аба ырайында курулуш аянттарына үзгүлтүксүз баруу. Чийме программалары, нормалар жана жандуу адамдар менен иш: буюртмачылар, инженерлер, куруучулар. Долбоорлор узун — айлардан жылдарга чейин.","skills_ru":["Пространственное мышление и рисунок","Работа в чертёжных и 3D-программах","Знание строительных норм и материалов","Согласование интересов заказчика, города и инженеров","Точность: чертёж — это документ, по которому строят","Терпение к длинным проектам"],"skills_ky":["Мейкиндик ойлому жана сүрөт тартуу","Чийме жана 3D-программаларда иштөө","Курулуш нормаларын жана материалдарды билүү","Буюртмачынын, шаардын жана инженерлердин кызыкчылыгын айкалыштыруу","Тактык: чийме — ал боюнча куруучу документ","Узун долбоорлорго чыдамкайлык"],"interesting_ru":["Твоя работа стоит в городе десятилетиями, её видят и используют тысячи людей","Сочетание искусства и точной инженерии в одной профессии","Каждый проект — новый контекст: школа, жилой дом, парк"],"interesting_ky":["Ишиң шаарда ондогон жылдар турат, аны миңдеген адамдар көрөт жана колдонот","Бир кесипте искусство менен так инженериянын айкалышы","Ар бир долбоор — жаңы контекст: мектеп, турак үй, парк"],"hard_ru":["От эскиза до построенного здания проходят годы, быстрых результатов мало","Множество норм и согласований ограничивает творчество","Правки заказчика могут менять проект на любом этапе","Учёба долгая, а первые годы работы — в основном черчение чужих идей"],"hard_ky":["Эскизден курулган имаратка чейин жылдар өтөт, тез натыйжа аз","Көптөгөн нормалар жана макулдашуулар чыгармачылыкты чектейт","Буюртмачынын оңдоолору долбоорду каалаган этапта өзгөртүшү мүмкүн","Окуу узак, ал эми алгачкы жылдары негизинен бирөөнүн идеяларын чийесиң"],"trial_task_ru":"Начертите план своей комнаты в масштабе: измерьте стены шагами или рулеткой и перенесите на клетчатую бумагу (одна клетка — полметра). Нанесите мебель, окна и дверь. Теперь главное: предложите перестановку, которая освободит место для рабочего стола у окна, и проверьте, открывается ли после неё дверь и удобно ли ходить. Планировка с проверкой ограничений — это ежедневная задача архитектора.","trial_task_ky":"Бөлмөңүздүн планын масштабда чийиңиз: дубалдарды кадам же рулетка менен өлчөп, чакмак кагазга түшүрүңүз (бир чакмак — жарым метр). Эмеректи, терезелерди жана эшикти белгилеңиз. Эми башкысы: терезенин жанынан жумуш столуна орун бошото турган которуштурууну сунуштап, андан кийин эшик ачыларын жана басып жүрүү ыңгайлуу экенин текшериңиз. Чектөөлөрдү текшерүү менен пландоо — архитектордун күнүмдүк маселеси.","study_directions_ru":["Архитектура","Архитектурный дизайн","Градостроительство"],"study_directions_ky":["Архитектура","Архитектуралык дизайн","Шаар куруу"],"linked_program_refs":[{"institution_photo_key":"politecnico-di-milano","program_hint":"Architectural Design"},{"institution_photo_key":"brno-university-of-technology","program_hint":"Architecture and Urban Design"},{"institution_photo_key":"nanjing-university","program_hint":"Architecture"},{"institution_photo_key":"tsinghua-university","program_hint":"Urban Regeneration and Design"}],"sources":["https://www.onetonline.org/link/summary/17-1011.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('a031b013-0b35-5bfb-8d4d-61024b81d148', 'software-developer', '1.0.0', '{"id":"software-developer","title_ru":"Разработчик программного обеспечения","title_ky":"Программалык камсыздоону иштеп чыгуучу","orvis_scales":["analysis"],"day_in_work_ru":"День начинается с пятнадцатиминутной встречи команды: кто что делает и у кого что застряло. Потом разработчик открывает вчерашнюю задачу — в приложении неправильно считается скидка, но только у пользователей с определённой валютой. Полтора часа уходит на поиски: он читает код, ставит контрольные точки и наконец находит строку, где ошибка пряталась. Исправление занимает пять минут, ещё час — тесты, чтобы починенное не сломало что-то другое. После обеда — новая функция: обсуждение с дизайнером, как она должна работать, и первые строки кода. Вечером разработчик отдаёт свой код коллеге на проверку и сам смотрит чужой: в хороших командах никто не отправляет код в работу в одиночку.","day_in_work_ky":"Күн команданын он беш мүнөттүк жолугушуусунан башталат: ким эмне кылып жатат, кимде эмне токтоп турат. Анан иштеп чыгуучу кечээки маселени ачат — колдонмодо арзандатуу туура эмес эсептелет, бирок белгилүү бир валютасы бар колдонуучуларда гана. Бир жарым саат издөөгө кетет: ал кодду окуйт, көзөмөл чекиттерин коёт жана акыры ката жашынган сапты табат. Оңдоо беш мүнөт алат, дагы бир саат — тесттер, оңдолгону башка нерсени бузбашы үчүн. Түштөн кийин — жаңы функция: дизайнер менен ал кантип иштеши керектигин талкуулоо жана коддун алгачкы саптары. Кечинде иштеп чыгуучу өз кодун кесиптешине текшерүүгө берет жана өзү бөлөк кодду карайт: жакшы командаларда эч ким кодду жалгыз жөнөтпөйт.","environment_ru":"Офис IT-компании или полностью удалённая работа; компьютер, второй монитор, наушники. Много сосредоточенной одиночной работы, но и ежедневное общение с командой. График часто гибкий, оценивают результат, а не часы за столом.","environment_ky":"IT-компаниянын кеңсеси же толугу менен алыстан иштөө; компьютер, экинчи монитор, кулакчындар. Топтолгон жалгыз иш көп, бирок команда менен күнүмдүк баарлашуу да бар. График көбүнчө ийкемдүү, стол жанындагы сааттар эмес, натыйжа бааланат.","skills_ru":["Программирование на одном-двух языках уверенно","Разбиение большой задачи на маленькие шаги","Чтение чужого кода","Терпеливый поиск причин ошибок","Работа с системами контроля версий","Английский: документация и общение в международных командах","Постоянное самообучение: технологии меняются каждые несколько лет"],"skills_ky":["Бир-эки тилде ишенимдүү программалоо","Чоң маселени кичине кадамдарга бөлүү","Бөтөн кодду окуй билүү","Каталардын себебин чыдамкайлык менен издөө","Версияларды көзөмөлдөө системалары менен иштөө","Англис тили: документтер жана эл аралык командаларда баарлашуу","Тынымсыз өз алдынча окуу: технологиялар ар бир нече жылда өзгөрөт"],"interesting_ru":["Ты буквально строишь вещи, которыми пользуются тысячи людей","Момент, когда код заработал, приносит удовольствие каждый раз","Можно работать из любой точки мира на компании из любой страны","Порог входа честный: портфолио проектов важнее связей"],"interesting_ky":["Сен түзмө-түз миңдеген адамдар колдонгон нерселерди куруп жатасың","Код иштеп кеткен учур ар бир жолу кубаныч тартуулайт","Дүйнөнүн каалаган жеринен каалаган өлкөнүн компаниясына иштесе болот","Кирүү босогосу калыс: долбоорлор портфолиосу тааныш-билиштен маанилүү"],"hard_ru":["Часы за поиском ошибки, которая оказывается опечаткой в одной букве","Сидячая работа и большая нагрузка на глаза","Технологии устаревают: выучил инструмент — через пять лет учи новый","На старте много рутинных задач, интересное доверяют не сразу"],"hard_ky":["Бир тамгадагы жаңылыш болуп чыккан катаны издеп сааттар кетет","Отуруп иштөө жана көзгө чоң жүк","Технологиялар эскирет: куралды үйрөндүң — беш жылдан кийин жаңысын үйрөн","Башында күнүмдүк тапшырмалар көп, кызыктуусун дароо ишенип беришпейт"],"trial_task_ru":"Напишите первую программу без установки чего-либо: откройте бесплатный онлайн-редактор кода (например, встроенную консоль браузера — F12, вкладка Console) и наберите: let name = \"Ваше имя\"; alert(\"Привет, \" + name). Затем усложните: пусть программа спрашивает имя через prompt() и здоровается по-разному утром и вечером (подсказка: new Date().getHours()). Если за 20 минут вы заставили компьютер сделать то, что придумали сами, — вы уже программировали.","trial_task_ky":"Эч нерсе орнотпой биринчи программаңызды жазыңыз: браузердин акысыз код редакторун ачыңыз (мисалы, браузердин консолу — F12, Console өтмөгү) жана териңиз: let name = \"Атыңыз\"; alert(\"Салам, \" + name). Анан татаалдатыңыз: программа атты prompt() аркылуу сурап, эртең менен жана кечинде ар башкача саламдашсын (кеңеш: new Date().getHours()). 20 мүнөттө компьютерге өзүңүз ойлоп тапкан нерсени жасатсаңыз — сиз программалап көрдүңүз.","study_directions_ru":["Компьютерные науки","Программная инженерия","Информационные технологии"],"study_directions_ky":["Компьютердик илимдер","Программалык инженерия","Маалыматтык технологиялар"],"linked_program_refs":[{"institution_photo_key":"apu","program_hint":"Bachelor of Science (Honours) in Computer Science"},{"institution_photo_key":"agh-university-of-krakow","program_hint":"Computer Science"},{"institution_photo_key":"istanbul-teknik-universitesi-itu","program_hint":"Computer Engineering (100% English)"},{"institution_photo_key":"charles-university","program_hint":"Computer Science"},{"institution_photo_key":"unikl","program_hint":"Bachelor of Software Engineering with Honours"}],"sources":["https://www.onetonline.org/link/summary/15-1252.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('bfe843fa-d9f4-53eb-81c9-93e55d23e105', 'data-scientist', '1.0.0', '{"id":"data-scientist","title_ru":"Специалист по данным","title_ky":"Маалымат боюнча адис","orvis_scales":["analysis","organization"],"day_in_work_ru":"Утро начинается с вопроса от бизнеса: «Почему в прошлом месяце ушла часть клиентов?» Специалист по данным выгружает историю заказов и первым делом чистит её: пропуски, дубли и опечатки способны испортить любой красивый график. Дальше — поиск закономерностей: он группирует клиентов, сравнивает их поведение и замечает, что уходят в основном те, кто столкнулся с задержкой доставки. Днём он проверяет гипотезу цифрами и строит модель, которая предсказывает риск ухода конкретного клиента. После — самое важное: превратить расчёты в понятную историю для людей, которые не знают статистики. Вечером он оформляет три графика и один вывод: «ускорьте доставку в этих двух районах — и удержите примерно каждого пятого уходящего».","day_in_work_ky":"Таң бизнестин суроосунан башталат: «Эмне үчүн өткөн айда кардарлардын бир бөлүгү кетип калды?» Маалымат адиси заказдардын тарыхын жүктөп алып, эң биринчи аны тазалайт: боштуктар, кайталанмалар жана каталар каалаган сулуу графикти бузуп коё алат. Андан ары — мыйзам ченемдүүлүктөрдү издөө: ал кардарларды топтоп, жүрүм-турумун салыштырат жана негизинен жеткирүү кечиккенине туш болгондор кетип жатканын байкайт. Күндүзү ал божомолду цифралар менен текшерип, конкреттүү кардардын кетүү тобокелин алдын ала айткан модель курат. Андан кийин — эң маанилүүсү: эсептөөлөрдү статистиканы билбеген адамдарга түшүнүктүү окуяга айландыруу. Кечинде үч график жана бир корутунду даярдайт: «ушул эки райондо жеткирүүнү тездеткиле — кетип жаткандардын болжол менен ар бир бешинчисин кармап каласыңар».","environment_ru":"Офис или удалённая работа; ноутбук, код, таблицы и много графиков. Работа идёт в связке с продуктовыми командами и руководством. Тишина и сосредоточенность чередуются с презентациями результатов.","environment_ky":"Кеңсе же алыстан иштөө; ноутбук, код, таблицалар жана көп графиктер. Иш продукт командалары жана жетекчилик менен байланышта жүрөт. Тынчтык менен топтолуу натыйжаларды презентациялоо менен алмашып турат.","skills_ru":["Статистика и вероятность на уверенном уровне","Программирование для анализа данных (Python, SQL)","Очистка и подготовка сырых данных","Проверка гипотез, а не подгонка под желаемый ответ","Наглядные графики и понятные объяснения","Здоровый скептицизм: корреляция — ещё не причина"],"skills_ky":["Ишенимдүү деңгээлдеги статистика жана ыктымалдык","Маалымат талдоо үчүн программалоо (Python, SQL)","Чийки маалыматты тазалоо жана даярдоо","Каалаган жоопко тууралабай, божомолдорду текшерүү","Көрсөтмөлүү графиктер жана түшүнүктүү түшүндүрмөлөр","Ден соолуктуу скептицизм: корреляция — себеп дегендик эмес"],"interesting_ru":["Ты находишь в данных то, чего никто не замечал, — почти детективная работа","Твои выводы меняют реальные решения компаний","Профессия применима везде: медицина, спорт, музыка, транспорт"],"interesting_ky":["Маалыматтан эч ким байкабаган нерсени табасың — дээрлик детективдик иш","Корутундуларың компаниялардын чыныгы чечимдерин өзгөртөт","Кесип бардык жерде колдонулат: медицина, спорт, музыка, транспорт"],"hard_ru":["Значительная часть времени уходит на рутинную очистку данных, а не на красивые модели","Результат может разочаровать: данные иногда показывают, что идея не работает","Нужно много математики — без неё инструменты превращаются в магию без понимания"],"hard_ky":["Убакыттын олуттуу бөлүгү сулуу моделдерге эмес, маалыматты тазалоого кетет","Натыйжа көңүл калтырышы мүмкүн: маалымат кээде идея иштебей турганын көрсөтөт","Көп математика керек — ансыз куралдар түшүнүксүз сыйкырга айланат"],"trial_task_ru":"Проведите мини-исследование данных. Соберите за 15 минут простую таблицу: оценки вашего класса по двум предметам или время, которое вы неделю тратили на телефон (в настройках телефона есть готовая статистика). Постройте один график в любой таблице (Google Sheets, Excel) и сформулируйте один честный вывод и один вопрос, на который данных не хватило. Вывод плюс вопрос — это формат работы аналитика.","trial_task_ky":"Маалымат боюнча мини-изилдөө жүргүзүңүз. 15 мүнөттө жөнөкөй таблица чогултуңуз: классыңыздын эки предмет боюнча баалары же бир жума телефонго кеткен убактыңыз (телефондун жөндөөлөрүндө даяр статистика бар). Каалаган таблицада (Google Sheets, Excel) бир график түзүп, бир чынчыл корутунду жана маалымат жетпей калган бир суроо жазыңыз. Корутунду плюс суроо — аналитиктин иш форматы ушул.","study_directions_ru":["Наука о данных","Прикладная математика и статистика","Бизнес-аналитика"],"study_directions_ky":["Маалымат илими","Колдонмо математика жана статистика","Бизнес-аналитика"],"linked_program_refs":[{"institution_photo_key":"university-of-messina","program_hint":"Computer Science — Data Analysis"},{"institution_photo_key":"istanbul-teknik-universitesi-itu","program_hint":"Artificial Intelligence and Data Engineering"},{"institution_photo_key":"sunway","program_hint":"Bachelor of Business Analytics (Honours)"},{"institution_photo_key":"university-of-verona","program_hint":"Economics and Data Analysis"}],"sources":["https://www.onetonline.org/link/summary/15-2051.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('3269f5d5-c21c-5211-89f7-6bfe1e1f2d70', 'cybersecurity-specialist', '1.0.0', '{"id":"cybersecurity-specialist","title_ru":"Специалист по кибербезопасности","title_ky":"Киберкоопсуздук адиси","orvis_scales":["analysis","organization"],"day_in_work_ru":"Смена начинается с проверки ночных оповещений: система мониторинга отметила пять подозрительных событий, четыре — ложная тревога, а вот пятое интересно: кто-то трижды пытался войти в учётную запись бухгалтера из другой страны. Специалист блокирует попытки, проверяет, не было ли входа, и пишет короткий разбор инцидента. Дальше — плановая работа: обновить защиту на серверах, где нашлась свежая уязвимость, пока ею не воспользовались. После обеда он проводит для сотрудников тренировку: рассылает безопасное «фишинговое» письмо и смотрит, кто нажмёт на ссылку, — не чтобы наказать, а чтобы научить. Ближе к вечеру тестирует собственную систему на прочность, пытаясь взломать её теми же приёмами, что настоящие злоумышленники. День заканчивается отчётом: что защищено, что в работе, что требует денег и решения руководства.","day_in_work_ky":"Смена түнкү эскертүүлөрдү текшерүүдөн башталат: мониторинг системасы беш шектүү окуяны белгилептир, төртөө — жалган тревога, ал эми бешинчиси кызык: кимдир-бирөө башка өлкөдөн бухгалтердин аккаунтуна үч жолу киргенге аракет кылыптыр. Адис аракеттерди бөгөттөп, кирүү болбогонун текшерет жана инциденттин кыска талдоосун жазат. Андан ары — пландуу иш: жаңы аялуу жери табылган серверлердин коргоосун аны бирөө колдоно электе жаңыртуу. Түштөн кийин ал кызматкерлер үчүн машыгуу өткөрөт: коопсуз «фишинг» катын жөнөтүп, ким шилтемени басарын карайт — жазалоо үчүн эмес, үйрөтүү үчүн. Кечке жуук өз системасын чыңдыкка сынайт, аны чыныгы кара ниеттердин эле ыкмалары менен бузганга аракет кылып. Күн отчёт менен аяктайт: эмне корголгон, эмне иште, эмнеге акча жана жетекчиликтин чечими керек.","environment_ru":"Офис или центр мониторинга безопасности; несколько экранов, системы отслеживания событий, тишина до первого серьёзного оповещения. Иногда — дежурства и ночные вызовы при инцидентах. Постоянная гонка знаний: методы атак обновляются ежемесячно.","environment_ky":"Кеңсе же коопсуздук мониторинг борбору; бир нече экран, окуяларды байкоо системалары, биринчи олуттуу эскертүүгө чейинки тынчтык. Кээде — нөөмөттөр жана инцидент болгондо түнкү чакыруулар. Билимдин тынымсыз жарышы: чабуул ыкмалары ай сайын жаңыланат.","skills_ru":["Устройство сетей и операционных систем","Внимание к мелочам: атака часто видна по одной странной записи в логе","Быстрые и хладнокровные действия при инциденте","Мышление злоумышленника: где бы атаковал ты?","Понятные отчёты для нетехнических людей","Честность и аккуратность: у тебя доступ к самому ценному"],"skills_ky":["Тармактардын жана операциялык системалардын түзүлүшүн билүү","Майда нерсеге көңүл: чабуул көбүнчө логдогу бир таң калыштуу жазуудан көрүнөт","Инцидент учурунда тез жана муздак кандуу аракет","Кара ниеттин ойлому: сен кайсы жерден чабуул кылмаксың?","Техникалык эмес адамдар үчүн түшүнүктүү отчёттор","Чынчылдык жана тактык: сенде эң баалуу нерсеге жетки бар"],"interesting_ru":["Каждый инцидент — партия в шахматы против реального противника","Профессия остро нужна: специалистов по безопасности не хватает во всём мире","Ты защищаешь настоящих людей — их деньги, переписку и документы"],"interesting_ky":["Ар бир инцидент — чыныгы атаандашка каршы шахмат партиясы","Кесипке муктаждык курч: коопсуздук адистери бүт дүйнөдө жетишпейт","Сен чыныгы адамдарды коргойсуң — алардын акчасын, катташуусун жана документтерин"],"hard_ru":["Успех невидим: когда всё защищено, кажется, что ты ничего не делал","Ошибка заметна всем и может стоить компании очень дорого","Ночные вызовы при серьёзных инцидентах","Учиться приходится непрерывно — противник тоже учится"],"hard_ky":["Ийгилик көрүнбөйт: баары корголуп турганда, эч нерсе кылбагандай сезилесиң","Ката баарына көрүнөт жана компанияга өтө кымбатка турушу мүмкүн","Олуттуу инциденттерде түнкү чакыруулар","Тынымсыз окуу керек — атаандаш дагы окуп жатат"],"trial_task_ru":"Проведите аудит собственной безопасности за 15 минут. Составьте список своих аккаунтов (почта, соцсети, игры) и честно ответьте по каждому: пароль уникальный или повторяется? Включён ли вход в два шага? Потом проверьте почту на сайте haveibeenpwned.com — не утекала ли она в известных взломах. Включите двухшаговый вход хотя бы на почте. Вы только что прошли базовый цикл работы специалиста: инвентаризация, оценка риска, устранение.","trial_task_ky":"15 мүнөттө өз коопсуздугуңузга аудит жүргүзүңүз. Аккаунттарыңыздын тизмесин түзүп (почта, соцтармактар, оюндар), ар бири боюнча чын жооп бериңиз: сырсөз уникалдуубу же кайталанабы? Эки кадамдуу кирүү иштетилгенби? Анан почтаңызды haveibeenpwned.com сайтынан текшериңиз — белгилүү бузуулардан агып кетпегенби. Жок дегенде почтада эки кадамдуу кирүүнү иштетиңиз. Сиз азыр эле адистин негизги ишин өттүңүз: инвентаризация, тобокелди баалоо, четтетүү.","study_directions_ru":["Кибербезопасность","Компьютерные сети","Информационные технологии"],"study_directions_ky":["Киберкоопсуздук","Компьютердик тармактар","Маалыматтык технологиялар"],"linked_program_refs":[{"institution_photo_key":"unikl","program_hint":"Bachelor of Cybersecurity Technology with Honours"},{"institution_photo_key":"utm","program_hint":"Bachelor of Computer Science (Computer Networks and Security) with Honours"},{"institution_photo_key":"upm","program_hint":"Bachelor in Computer Science (Computer Network) with Honours"}],"sources":["https://www.onetonline.org/link/summary/15-1212.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('9fdccc33-b785-5f46-84ee-c1749dae70d8', 'mechanical-engineer', '1.0.0', '{"id":"mechanical-engineer","title_ru":"Инженер-механик","title_ky":"Инженер-механик","orvis_scales":["production","analysis"],"day_in_work_ru":"Утро начинается в цехе: ночью остановился конвейер, и инженер вместе с механиками ищет причину — греется подшипник узла подачи. Он решает, что менять и как переделать крепление, чтобы поломка не повторялась. Вернувшись за компьютер, инженер открывает 3D-модель детали, которую проектирует для нового станка: прочность нужно увеличить, а вес и цену — нет. Программа расчёта показывает, где деталь испытывает наибольшее напряжение, и он меняет форму рёбер. После обеда — испытания опытного образца: датчики, замеры, таблица результатов. Что-то в цифрах не сходится с расчётом, и это нормально: именно на расхождениях инженер учится больше всего. Вечером он оформляет чертежи для завода — по ним деталь будут делать серийно.","day_in_work_ky":"Таң цехте башталат: түнү конвейер токтоп калды, инженер механиктер менен бирге себебин издейт — берүү түйүнүнүн подшипниги ысып жатат. Ал эмнени алмаштырууну жана бузулуу кайталанбашы үчүн бекитүүнү кантип өзгөртүүнү чечет. Компьютерге кайтып келип, инженер жаңы станок үчүн долбоорлоп жаткан деталдын 3D-моделин ачат: бекемдикти жогорулатуу керек, ал эми салмак менен бааны — жок. Эсептөө программасы деталь эң чоң күчкө кайсы жерде кабыларын көрсөтөт, ал кабыргалардын формасын өзгөртөт. Түштөн кийин — тажрыйба үлгүсүн сыноо: датчиктер, өлчөөлөр, жыйынтык таблицасы. Цифралардагы бир нерсе эсеп менен дал келбейт, бул кадыресе көрүнүш: инженер эң көптү дал ушул айырмалардан үйрөнөт. Кечинде ал завод үчүн чиймелерди даярдайт — деталь алар боюнча сериялап жасалат.","environment_ru":"Смесь конструкторского бюро и производства: компьютер с 3D-программами, цех со станками, испытательный стенд. Работа в команде с технологами, электриками и рабочими. Иногда командировки на заводы и объекты.","environment_ky":"Конструктордук бюро менен өндүрүштүн аралашмасы: 3D-программалуу компьютер, станоктору бар цех, сыноо стенди. Технологдор, электриктер жана жумушчулар менен командада иштөө. Кээде заводдорго жана объектилерге командировкалар.","skills_ru":["Физика и механика на уверенном уровне","3D-проектирование и черчение","Понимание материалов: сталь, алюминий, пластики","Расчёт прочности и допусков","Умение работать руками и понимать производство","Поиск простых решений: лучшая деталь — та, которой нет"],"skills_ky":["Ишенимдүү деңгээлдеги физика жана механика","3D-долбоорлоо жана чийме","Материалдарды түшүнүү: болот, алюминий, пластиктер","Бекемдикти жана жол берүүлөрдү эсептөө","Кол менен иштей билүү жана өндүрүштү түшүнүү","Жөнөкөй чечимдерди издөө: эң мыкты деталь — жок деталь"],"interesting_ru":["Твои идеи становятся железом, которое можно потрогать","Инженеры-механики нужны всюду: от пищевых заводов до аэропортов","Задачи очень разные: сегодня расчёт, завтра цех, послезавтра испытания"],"interesting_ky":["Идеяларың кол менен кармап көрө турган темирге айланат","Инженер-механиктер бардык жерде керек: тамак-аш заводдорунан аэропортторго чейин","Маселелер абдан ар түрдүү: бүгүн эсеп, эртең цех, бүрсүгүнү сыноолор"],"hard_ru":["Цена ошибки высока: неверный расчёт может сломать дорогое оборудование","Много нормативов и стандартов, которые нужно знать и соблюдать","Производственная среда — шум, смазка, командировки","Согласования с производством порой дольше самого проектирования"],"hard_ky":["Катанын баасы жогору: туура эмес эсеп кымбат жабдууну бузушу мүмкүн","Билүү жана сактоо керек болгон көп нормативдер менен стандарттар","Өндүрүш чөйрөсү — ызы-чуу, май, командировкалар","Өндүрүш менен макулдашуу кээде долбоорлоонун өзүнөн узак"],"trial_task_ru":"Постройте мост из бумаги: возьмите десять листов А4 и скотч, соорудите пролёт между двумя стульями (расстояние — 40 см), который выдержит кружку с водой. Подсказка: лист, свёрнутый в трубку или сложенный гармошкой, в десятки раз прочнее плоского. Сначала сделайте прогноз, сколько выдержит конструкция, потом проверьте. Расхождение прогноза и результата — это то, с чем инженер работает каждый день.","trial_task_ky":"Кагаздан көпүрө куруңуз: он барак А4 менен скотч алып, эки отургучтун ортосуна (аралык — 40 см) суусу бар кружканы көтөрө турган пролёт жасаңыз. Кеңеш: түтүкчө кылып оролгон же гармошка кылып бүктөлгөн барак жалпак барактан ондогон эсе бекем. Адегенде конструкция канча көтөрөрүн божомолдоп, анан текшериңиз. Божомол менен натыйжанын айырмасы — инженер күн сайын иштеген нерсе дал ушул.","study_directions_ru":["Машиностроение","Механическая инженерия","Мехатроника"],"study_directions_ky":["Машина куруу","Механикалык инженерия","Мехатроника"],"linked_program_refs":[{"institution_photo_key":"monash-malaysia","program_hint":"Bachelor of Mechanical Engineering (Honours)"},{"institution_photo_key":"brno-university-of-technology","program_hint":"Fundamentals of Mechanical Engineering"},{"institution_photo_key":"agh-university-of-krakow","program_hint":"Mechanical Engineering"},{"institution_photo_key":"huazhong-university-of-science-and-technology-hust","program_hint":"Mechanical Design, Manufacturing and Automation"}],"sources":["https://www.onetonline.org/link/summary/17-2141.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('ad199eea-8581-5a70-87aa-55be97adb60e', 'chemical-engineer', '1.0.0', '{"id":"chemical-engineer","title_ru":"Инженер-химик","title_ky":"Инженер-химик","orvis_scales":["production","analysis"],"day_in_work_ru":"День начинается с показателей производства: за ночь температура в одном из реакторов дважды выходила за допустимый коридор, и нужно понять почему. Инженер сравнивает графики датчиков, находит закономерность и корректирует режим. Потом — лаборатория: образцы вчерашней партии проверяются на чистоту, и один показатель на границе нормы. Вместо того чтобы просто отбраковать партию, инженер ищет, на каком этапе процесс пошёл иначе. После обеда — работа над улучшением: если поменять порядок смешивания, расход дорогого компонента снизится на несколько процентов, а это большие деньги в масштабе года. Вечером он обновляет инструкцию для операторов и проводит короткий разбор: безопасность на химическом производстве держится на том, что все понимают, что и зачем делают.","day_in_work_ky":"Күн өндүрүштүн көрсөткүчтөрүнөн башталат: түн ичинде реакторлордун биринде температура эки жолу уруксат берилген чектен чыгып кетти, эмне үчүн экенин түшүнүш керек. Инженер датчиктердин графиктерин салыштырып, мыйзам ченемдүүлүктү таап, режимди оңдойт. Анан — лаборатория: кечээки партиянын үлгүлөрү тазалыкка текшерилет, бир көрсөткүч норманын чегинде. Партияны жөн эле четке кагуунун ордуна инженер процесс кайсы этапта башкача кеткенин издейт. Түштөн кийин — жакшыртуу боюнча иш: аралаштыруу тартибин өзгөртсө, кымбат компоненттин чыгымы бир нече пайызга азаят, бул жылдык масштабда чоң акча. Кечинде ал операторлор үчүн нускаманы жаңыртып, кыска талдоо өткөрөт: химиялык өндүрүштөгү коопсуздук баары эмнени жана эмне үчүн кылып жатканын түшүнгөнүнө таянат.","environment_ru":"Производственная площадка и лаборатория: реакторы, датчики, пробы, спецодежда и строгие правила безопасности. Часть дня — за компьютером с графиками процессов. Работа командная: операторы, лаборанты, технологи.","environment_ky":"Өндүрүш аянты жана лаборатория: реакторлор, датчиктер, сынамдар, атайын кийим жана коопсуздуктун катуу эрежелери. Күндүн бир бөлүгү — процесстердин графиктери менен компьютерде. Иш командалык: операторлор, лаборанттар, технологдор.","skills_ru":["Химия и физика как рабочие инструменты","Чтение и настройка технологических процессов","Анализ данных с датчиков и из лаборатории","Строгая дисциплина безопасности","Поиск экономии без потери качества","Ясные инструкции для операторов"],"skills_ky":["Жумушчу курал катары химия жана физика","Технологиялык процесстерди окуу жана жөндөө","Датчиктерден жана лабораториядан келген маалыматты талдоо","Коопсуздуктун катуу тартиби","Сапатты жоготпой үнөмдөө жолдорун издөө","Операторлор үчүн так нускамалар"],"interesting_ru":["Ты видишь, как из сырья рождаются вещи, которыми пользуются все: топливо, лекарства, материалы","Маленькое улучшение процесса экономит миллионы в масштабе завода","Профессия соединяет науку, производство и экономику"],"interesting_ky":["Чийки заттан баары колдонгон нерселер кантип жаралганын көрөсүң: отун, дарылар, материалдар","Процесстеги кичине жакшыртуу завод масштабында миллиондорду үнөмдөйт","Кесип илимди, өндүрүштү жана экономиканы бириктирет"],"hard_ru":["Высокая ответственность: ошибки на химическом производстве опасны","Сменная работа и вызовы при сбоях процесса","Много регламентов, документации и проверок","Производства расположены не в центрах городов — возможны переезды"],"hard_ky":["Жогорку жоопкерчилик: химиялык өндүрүштөгү каталар коркунучтуу","Сменалуу иш жана процесс бузулганда чакыруулар","Көп регламенттер, документтер жана текшерүүлөр","Өндүрүштөр шаар борборунда эмес — көчүп барууга туура келиши мүмкүн"],"trial_task_ru":"Проведите настоящий эксперимент с контролем условий. Растворяйте по чайной ложке соли в трёх стаканах воды: холодной, комнатной и тёплой, — засекая время полного растворения в каждом. Важно: мешайте одинаково и наливайте одинаковый объём, иначе сравнение нечестное. Запишите результаты таблицей и сформулируйте вывод одним предложением. Управление условиями процесса — это и есть суть работы инженера-химика.","trial_task_ky":"Шарттарды көзөмөлдөп, чыныгы эксперимент жүргүзүңүз. Үч стакан сууда — муздак, бөлмө температурасындагы жана жылуу — бирден чай кашык тузду эритиңиз, ар биринде толук эрүү убактысын белгилеп. Маанилүү: бирдей аралаштырып, бирдей көлөм куюңуз, болбосо салыштыруу калыс эмес. Жыйынтыктарды таблица кылып жазып, корутундуну бир сүйлөм менен айтыңыз. Процесстин шарттарын башкаруу — инженер-химиктин ишинин маңызы дал ушул.","study_directions_ru":["Химическая технология","Химическая инженерия","Технологии материалов"],"study_directions_ky":["Химиялык технология","Химиялык инженерия","Материал технологиялары"],"linked_program_refs":[{"institution_photo_key":"zjut","program_hint":"Chemical Engineering and Technology"},{"institution_photo_key":"ecust","program_hint":"Chemical Engineering and Technology"},{"institution_photo_key":"university-of-chemistry-and-technology-prague-vscht","program_hint":"Chemistry and Technology"}],"sources":["https://www.onetonline.org/link/summary/17-2041.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('f92f938b-5c4f-5b59-8662-d78195924709', 'aerospace-engineer', '1.0.0', '{"id":"aerospace-engineer","title_ru":"Инженер аэрокосмической техники","title_ky":"Аэрокосмостук техника инженери","orvis_scales":["production","analysis"],"day_in_work_ru":"Утро — за результатами ночных расчётов: компьютер всю ночь моделировал обтекание крыла, и теперь инженер разбирает, где поток срывается и почему это меняет расход топлива. Дальше командная встреча: конструкция должна стать легче на четыре килограмма, и каждая группа предлагает, чем пожертвовать. Спорят громко, но по делу — в авиации каждое решение обязано быть обоснованным. После обеда — испытательный стенд: образец крепления проходит проверку на усталость, тысячи циклов нагрузки за несколько часов. Инженер сверяет показания датчиков с расчётной моделью и записывает расхождения. Ближе к вечеру он готовит отчёт для сертификации: в этой отрасли документ о том, почему деталь безопасна, не менее важен, чем сама деталь.","day_in_work_ky":"Таң — түнкү эсептөөлөрдүн жыйынтыктары менен: компьютер түнү бою канаттын агым менен айланышын моделдеди, эми инженер агым кайсы жерде үзүлөрүн жана бул отун чыгымын эмне үчүн өзгөртөрүн талдайт. Андан ары командалык жолугушуу: конструкция төрт килограммга жеңил болушу керек, ар бир топ эмнени курмандыкка чалууну сунуштайт. Катуу талашышат, бирок иш боюнча — авиацияда ар бир чечим негиздүү болууга милдеттүү. Түштөн кийин — сыноо стенди: бекитүүнүн үлгүсү чарчоого текшерүүдөн өтөт, бир нече саатта миңдеген жүктөм циклы. Инженер датчиктердин көрсөткүчтөрүн эсептик модель менен салыштырып, айырмаларды жазат. Кечке жуук ал сертификация үчүн отчёт даярдайт: бул тармакта деталь эмне үчүн коопсуз экени жөнүндөгү документ деталдын өзүнөн кем эмес маанилүү.","environment_ru":"Конструкторское бюро, вычислительные лаборатории и испытательные стенды. Большие команды и длинные проекты: самолёт или спутник делают годами. Всё подчинено безопасности и точности.","environment_ky":"Конструктордук бюро, эсептөө лабораториялары жана сыноо стенддери. Чоң командалар жана узун долбоорлор: учак же спутник жылдап жасалат. Баары коопсуздукка жана тактыкка баш ийет.","skills_ru":["Сильная математика и физика — это фундамент профессии","Аэродинамика, прочность, материалы","Компьютерное моделирование и анализ результатов","Работа в большой команде со строгими процессами","Инженерная документация: расчёт должен быть воспроизводим","Английский: стандарты и статьи отрасли международные"],"skills_ky":["Күчтүү математика жана физика — кесиптин пайдубалы","Аэродинамика, бекемдик, материалдар","Компьютердик моделдөө жана жыйынтыктарды талдоо","Катуу процесстери бар чоң командада иштөө","Инженердик документтер: эсеп кайталанып текшерилгидей болушу керек","Англис тили: тармактын стандарттары жана макалалары эл аралык"],"interesting_ru":["Ты работаешь на переднем крае техники: то, что летает, прощает меньше всего ошибок","Результат труда — самолёты и спутники, которыми гордятся страны","Отрасль растёт: космос снова стал местом, куда идут молодые команды"],"interesting_ky":["Техниканын алдыңкы чегинде иштейсиң: учкан нерсе катаны эң аз кечирет","Эмгектин натыйжасы — өлкөлөр сыймыктанган учактар менен спутниктер","Тармак өсүүдө: космос кайрадан жаш командалар бара турган жерге айланды"],"hard_ru":["Очень высокие требования к точности и дисциплине","Много согласований и документов: свобода творчества ограничена нормами","Проекты длинные — свой вклад в полёт увидишь через годы","Рабочих мест меньше, чем в массовых IT-профессиях, и вход конкурентный"],"hard_ky":["Тактыкка жана тартипке өтө жогорку талаптар","Көп макулдашуулар жана документтер: чыгармачылык эркиндиги нормалар менен чектелген","Долбоорлор узун — учууга кошкон салымыңды жылдардан кийин көрөсүң","Жумуш орду массалык IT-кесиптерге караганда аз, кирүү атаандаштыкта"],"trial_task_ru":"Устройте испытание планёров. Сложите три бумажных самолётика разных конструкций (найдите две новые схемы складывания). Проведите честный эксперимент: по три броска каждого с одинаковым усилием, записывайте дальность. Потом возьмите лучший и попробуйте улучшить: подогните законцовки крыльев, добавьте скрепку на нос — и снова измерьте. Цикл «гипотеза — испытание — измерение — доработка» — это и есть аэрокосмическая инженерия в миниатюре.","trial_task_ky":"Планёрлордун сыноосун өткөрүңүз. Ар башка конструкциядагы үч кагаз учакты бүктөңүз (эки жаңы бүктөө схемасын таап алыңыз). Калыс эксперимент жүргүзүңүз: ар бирин бирдей күч менен үч жолу ыргытып, алыстыгын жазыңыз. Анан эң мыктысын алып, жакшыртып көрүңүз: канаттардын учун бүгүңүз, тумшугуна скрепка кошуңуз — кайра өлчөңүз. «Божомол — сыноо — өлчөө — жеткире иштөө» цикли — кичине түрдөгү аэрокосмостук инженерия дал ушул.","study_directions_ru":["Аэрокосмическая инженерия","Авиастроение","Космическая инженерия"],"study_directions_ky":["Аэрокосмостук инженерия","Учак куруу","Космостук инженерия"],"linked_program_refs":[{"institution_photo_key":"northwestern-polytechnical-university","program_hint":"Aerospace Engineering — School of Aeronautics"},{"institution_photo_key":"shenyang-aerospace-university","program_hint":"Aeronautical Engineering"},{"institution_photo_key":"agh-university-of-krakow","program_hint":"Space Engineering"},{"institution_photo_key":"beijing-institute-of-technology-zhuhai-bit-zhuhai","program_hint":"Aeronautical and Astronautical Engineering — Beijing"}],"sources":["https://www.onetonline.org/link/summary/17-2011.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('7865fdae-46f5-5101-8197-b6d5b6ba5648', 'maritime-officer', '1.0.0', '{"id":"maritime-officer","title_ru":"Судоводитель","title_ky":"Кеме айдоочу","orvis_scales":["adventure","production"],"day_in_work_ru":"Вахта начинается на мостике в четыре утра: впереди узкий пролив, и офицер сверяет курс по картам, радару и данным о течении. Он держит связь с другими судами и береговой службой — в оживлённых водах все обязаны понимать намерения друг друга. После вахты — обход: проверка спасательного оборудования и записи в судовом журнале, где фиксируется каждое существенное событие. Днём порт: швартовка требует ювелирной точности, ведь судно весом в тысячи тонн останавливается очень неохотно. Потом контроль погрузки — груз должен быть распределён так, чтобы судно осталось остойчивым в шторм. Вечером офицер изучает прогноз погоды на следующий переход и планирует маршрут: иногда лишние сто миль в обход — самое правильное решение.","day_in_work_ky":"Вахта таңкы төрттө мостикте башталат: алдыда тар кысык, офицер курсту карталар, радар жана агым маалыматтары боюнча салыштырат. Ал башка кемелер жана жээк кызматы менен байланышта — кайнаган сууларда баары бири-биринин ниетин түшүнүүгө милдеттүү. Вахтадан кийин — кыдыруу: куткаруу жабдууларын текшерүү жана ар бир олуттуу окуя жазылган кеме журналына жазуулар. Күндүзү порт: токтотуу зергердик тактыкты талап кылат, анткени миңдеген тонна салмактагы кеме өтө каалабай токтойт. Анан жүктөөнү көзөмөлдөө — жүк кеме бороондо туруктуу боло тургандай бөлүштүрүлүшү керек. Кечинде офицер кийинки өтүү үчүн аба ырайынын божомолун изилдеп, маршрутту пландайт: кээде айланып өткөн ашыкча жүз миля — эң туура чечим.","environment_ru":"Судно — рабочее место и дом на недели или месяцы: мостик, палуба, машинное отделение, каюта. Море бывает любым — от штиля до шторма, работа вахтами круглые сутки. Экипаж интернациональный, рабочий язык — английский.","environment_ky":"Кеме — жумалар же айлар бою жумуш орду жана үй: мостик, палуба, машина бөлүмү, каюта. Деңиз ар кандай болот — тынчтыктан бороонго чейин, иш сутка бою вахта менен. Экипаж эл аралык, жумуш тили — англисче.","skills_ru":["Навигация: карты, радары, спутниковые системы","Хладнокровие и быстрые решения в сложных условиях","Дисциплина и точное соблюдение процедур","Руководство вахтой и работа в команде","Морской английский","Физическая выносливость и здоровье"],"skills_ky":["Навигация: карталар, радарлар, спутник системалары","Татаал шарттарда муздак кандуулук жана тез чечимдер","Тартип жана процедураларды так сактоо","Вахтаны жетектөө жана командада иштөө","Деңиз англис тили","Физикалык чыдамкайлык жана ден соолук"],"interesting_ru":["Настоящие путешествия: порты и страны, которые большинство видит только на карте","Реальная ответственность приходит рано: вахтенный офицер управляет судном сам","Международная профессия с понятной карьерной лестницей до капитана"],"interesting_ky":["Чыныгы саякаттар: көпчүлүк картадан гана көргөн порттор менен өлкөлөр","Чыныгы жоопкерчилик эрте келет: вахта офицери кемени өзү башкарат","Капитанга чейин түшүнүктүү карьера тепкичи бар эл аралык кесип"],"hard_ru":["Месяцы вдали от дома и семьи","Вахты ночью, качка, работа в любую погоду","Замкнутое пространство и один и тот же круг людей неделями","Строгие медицинские требования на протяжении всей карьеры"],"hard_ky":["Үйдөн жана үй-бүлөдөн алыс айлар","Түнкү вахталар, чайпалуу, каалаган аба ырайында иштөө","Жабык мейкиндик жана жумалар бою бир эле адамдар чөйрөсү","Бүт карьера бою катуу медициналык талаптар"],"trial_task_ru":"Попробуйте настоящую навигационную задачу. Откройте бесплатную карту морского трафика (например, marinetraffic.com) и выберите любое судно в Индийском океане или Средиземном море. По его курсу и скорости посчитайте, когда оно придёт в ближайший порт: расстояние прикиньте по масштабу карты, время = расстояние / скорость. Проверьте себя через пару часов по фактическому положению судна. Вы только что сделали то, что вахтенный офицер делает каждый день.","trial_task_ky":"Чыныгы навигациялык маселени чечип көрүңүз. Деңиз трафигинин акысыз картасын ачыңыз (мисалы, marinetraffic.com) жана Инди океанындагы же Жер Ортолук деңиздеги каалаган кемени тандаңыз. Курсу жана ылдамдыгы боюнча анын жакынкы портко качан келерин эсептеңиз: аралыкты картанын масштабы боюнча болжолдоңуз, убакыт = аралык / ылдамдык. Эки-үч сааттан кийин кеменин чыныгы орду боюнча өзүңүздү текшериңиз. Сиз азыр эле вахта офицери күн сайын жасаган ишти жасадыңыз.","study_directions_ru":["Судовождение","Морские операции","Морская инженерия"],"study_directions_ky":["Кеме айдоо","Деңиз операциялары","Деңиз инженериясы"],"linked_program_refs":[{"institution_photo_key":"mla-college","program_hint":"BSc (Hons) Sustainable Maritime Operations"},{"institution_photo_key":"mla-college","program_hint":"MSc Sustainable Maritime Operations"}],"sources":["https://www.onetonline.org/link/summary/53-5021.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('a8f07f02-cb68-573b-8620-93e705f8864c', 'paramedic', '1.0.0', '{"id":"paramedic","title_ru":"Фельдшер скорой помощи","title_ky":"Тез жардам фельдшери","orvis_scales":["adventure","altruism"],"day_in_work_ru":"Смена начинается с проверки машины: кислород, дефибриллятор, укладки с лекарствами — всё пересчитывается до выезда, потому что на вызове искать будет поздно. Первый вызов приходит через двадцать минут: у пожилого мужчины боль в груди. По дороге фельдшер прокручивает алгоритм действий, на месте — быстрый осмотр, кардиограмма, решение: везём, и везём быстро. Следующие вызовы не похожи один на другой: высокая температура у ребёнка, травма на стройке, паническая атака, которую родные приняли за сердечный приступ. Между выездами — заполнение карт вызова и короткий обед, который может прерваться в любую секунду. Ночью город затихает, но не скорая: до конца смены ещё три вызова, и на каждом фельдшер — самый спокойный человек в комнате.","day_in_work_ky":"Смена машинаны текшерүүдөн башталат: кычкылтек, дефибриллятор, дары салгычтар — баары чыгаар алдында саналат, анткени чакырыкта издөөгө кеч болот. Биринчи чакырык жыйырма мүнөттөн кийин келет: улгайган кишинин көкүрөгү ооруп жатат. Жолдо фельдшер аракеттердин алгоритмин ойлонот, жеринде — тез кароо, кардиограмма, чечим: алып жөнөйбүз, тез алып жөнөйбүз. Кийинки чакырыктар бири-бирине окшобойт: баланын жогорку температурасы, курулуштагы жаракат, туугандары жүрөк кармады деп ойлогон паника кармашы. Чыгуулардын ортосунда — чакырык карталарын толтуруу жана каалаган секундда үзүлүп калышы мүмкүн болгон кыска түшкү тамак. Түнкүсүн шаар тынчыйт, бирок тез жардам эмес: смена аягына чейин дагы үч чакырык бар, ар биринде фельдшер — бөлмөдөгү эң сабырдуу адам.","environment_ru":"Машина скорой помощи, квартиры, улицы, предприятия — рабочее место там, где случилась беда. Смены по 12–24 часа, работа в любую погоду и время суток. Постоянный партнёр — напарник и водитель, связь с диспетчером и больницами.","environment_ky":"Тез жардам машинасы, батирлер, көчөлөр, ишканалар — жумуш орду кырсык болгон жерде. Сменалар 12–24 сааттан, иш каалаган аба ырайында жана суткада. Туруктуу өнөктөш — шерик менен айдоочу, диспетчер жана ооруканалар менен байланыш.","skills_ru":["Неотложная медицина: алгоритмы действий при угрозе жизни","Быстрая оценка состояния по немногим признакам","Спокойствие, когда вокруг паника","Уверенные практические навыки: инъекции, реанимация, иммобилизация","Общение с людьми в худший день их жизни","Физическая сила и выносливость"],"skills_ky":["Шашылыш медицина: өмүргө коркунуч болгондо аракет алгоритмдери","Аз белгилер боюнча абалды тез баалоо","Айлана паникада болгондо сабырдуулук","Ишенимдүү практикалык көндүмдөр: ийне саюу, реанимация, кыймылсыздандыруу","Адамдар менен алардын жашоосундагы эң оор күнү сүйлөшө билүү","Физикалык күч жана чыдамкайлык"],"interesting_ru":["Есть смены, после которых точно знаешь: сегодня человек жив благодаря тебе","Никакой рутины: каждый вызов — новая ситуация и новое решение","Навыки профессии полезны всю жизнь и в любом месте"],"interesting_ky":["Кээ бир сменалардан кийин так билесиң: бүгүн адам сенин аркаң менен аман","Эч кандай күнүмдүк бир түрдүүлүк жок: ар бир чакырык — жаңы кырдаал жана жаңы чечим","Кесиптин көндүмдөрү өмүр бою жана каалаган жерде пайдалуу"],"hard_ru":["Тяжёлые сцены и потери — часть работы, и к этому нельзя привыкнуть полностью","Ночные смены, работа в праздники, физическая нагрузка","Решения приходится принимать быстро и с неполной информацией","Эмоциональное выгорание — реальный риск профессии"],"hard_ky":["Оор көрүнүштөр жана жоготуулар — иштин бөлүгү, буга толук көнүү мүмкүн эмес","Түнкү сменалар, майрамдарда иштөө, физикалык жүк","Чечимдерди тез жана толук эмес маалымат менен кабыл алууга туура келет","Эмоциялык күйүп бүтүү — кесиптин чыныгы тобокели"],"trial_task_ru":"Выучите за 20 минут один навык, который однажды может спасти жизнь: последовательность действий при потере сознания. Найдите обучающее видео авторитетной организации (например, Красного Полумесяца или Красного Креста) о восстановительном положении и порядке вызова помощи. Отработайте на подушке или согласившемся родственнике: проверка сознания и дыхания, вызов 103, поворот в устойчивое положение на боку. Запишите порядок шагов по памяти и сверьте с видео.","trial_task_ky":"Бир күнү өмүр сактап калышы мүмкүн болгон бир көндүмдү 20 мүнөттө үйрөнүңүз: адам эс-учун жоготкондогу аракеттердин ырааттуулугу. Абройлуу уюмдун (мисалы, Кызыл Жарым Ай же Кызыл Крест) калыбына келтирүү абалы жана жардам чакыруу тартиби жөнүндө окутуу видеосун табыңыз. Жаздыкта же макул болгон туугандын жардамы менен машыгыңыз: эс-учун жана дем алуусун текшерүү, 103кө чалуу, капталга туруктуу абалга буруу. Кадамдардын тартибин эстен жазып, видео менен салыштырыңыз.","study_directions_ru":["Лечебное дело (фельдшер)","Сестринское дело","Медицина неотложных состояний"],"study_directions_ky":["Дарылоо иши (фельдшер)","Медайым иши","Шашылыш абалдар медицинасы"],"linked_program_refs":[{"institution_photo_key":"medical-university-of-gdansk","program_hint":"Premedical Course"},{"institution_photo_key":"medical-university-of-gdansk","program_hint":"Bachelor of Nursing"}],"sources":["https://www.onetonline.org/link/summary/29-2043.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('33eb0b5e-e297-5165-87f6-fe78449898ed', 'tour-guide', '1.0.0', '{"id":"tour-guide","title_ru":"Гид и организатор путешествий","title_ky":"Гид жана саякат уюштуруучу","orvis_scales":["adventure","leadership"],"day_in_work_ru":"В семь утра гид уже на точке сбора: сегодня группа из восьми человек идёт к горному озеру. Перед выходом — короткий инструктаж и честная проверка: у всех ли есть вода, обувь и силы на шесть часов пути. На маршруте гид работает сразу на трёх ролях: рассказчик, который знает историю каждой долины; штурман, следящий за темпом и погодой; и старший, отвечающий за безопасность. На привале он замечает, что один участник отстаёт и молчит, — и незаметно перестраивает темп группы. К вечеру — возвращение, тёплое прощание и десяток фотографий, которые гости увезут домой. После сезона в горах гид водит городские экскурсии и готовит новые маршруты: разведка тропы без группы — обязательная часть профессии.","day_in_work_ky":"Таңкы жетиде гид чогулуу жеринде: бүгүн сегиз кишилик топ тоо көлүнө барат. Чыгаар алдында — кыска нускама жана чынчыл текшерүү: баарында суу, бут кийим жана алты сааттык жолго күч барбы. Маршрутта гид үч ролдо бирдей иштейт: ар бир өрөөндүн тарыхын билген аңгемечи; темпти жана аба ырайын байкаган штурман; жана коопсуздукка жооп берген улуу. Тыныгууда ал бир катышуучу артта калып, унчукпай баратканын байкайт — жана топтун темпин билинтпей өзгөртөт. Кечке маал — кайтуу, жылуу коштошуу жана коноктор үйүнө алып кете турган ондогон сүрөт. Тоолордогу сезондон кийин гид шаардык экскурсияларды жүргүзүп, жаңы маршруттарды даярдайт: жолду топсуз чалгындоо — кесиптин милдеттүү бөлүгү.","environment_ru":"Горы, тропы, города, музеи — офисом служит место, куда едут люди. Работа сезонная и физическая, с ранними подъёмами и полными днями на ногах. Постоянное общение с группами очень разных людей, включая иностранных гостей.","environment_ky":"Тоолор, жолдор, шаарлар, музейлер — кеңсе болуп адамдар бара турган жер кызмат кылат. Иш сезондук жана физикалык, эрте туруу жана күн бою бут үстүндө жүрүү менен. Ар кандай адамдардан турган топтор менен, анын ичинде чет элдик коноктор менен тынымсыз баарлашуу.","skills_ru":["Знание маршрутов, истории и природы своего края","Оценка рисков: погода, силы группы, состояние тропы","Первая помощь вдали от помощи","Умение вести и удерживать группу","Живой рассказ, который слушают","Иностранные языки для работы с туристами"],"skills_ky":["Өз аймагынын маршруттарын, тарыхын жана жаратылышын билүү","Тобокелдиктерди баалоо: аба ырайы, топтун күчү, жолдун абалы","Жардамдан алыс жерде биринчи жардам көрсөтүү","Топту жетектеп, кармай билүү","Уккулуктуу жандуу аңгеме","Туристтер менен иштөө үчүн чет тилдер"],"interesting_ru":["Рабочее место — самые красивые места страны","Ты показываешь людям Кыргызстан, и их восторг — твоя ежедневная награда","Туризм в Центральной Азии растёт, и хорошие гиды нарасхват"],"interesting_ky":["Жумуш орду — өлкөнүн эң кооз жерлери","Адамдарга Кыргызстанды көрсөтөсүң, алардын суктануусу — күнүмдүк сыйлыгың","Борбор Азияда туризм өсүүдө, жакшы гиддер талашта"],"hard_ru":["Сезонность: плотные месяцы работы сменяются месяцами затишья","Ответственность за безопасность группы лежит на тебе","Погода и настроение участников не подчиняются плану","Один и тот же маршрут приходится проходить десятки раз с тем же интересом"],"hard_ky":["Сезондуулук: тыгыз иш айлары тынч айлар менен алмашат","Топтун коопсуздугу үчүн жоопкерчилик сенде","Аба ырайы жана катышуучулардын маанайы планга баш ийбейт","Бир эле маршрутту ондогон жолу ошол эле кызыгуу менен өтүүгө туура келет"],"trial_task_ru":"Составьте мини-экскурсию по своему району на 20 минут. Выберите три точки, о которых вам есть что рассказать (старое здание, базар, вид на горы), и постройте между ними маршрут. Для каждой точки подготовьте по одной истории на две минуты и одному вопросу слушателям — вопросы держат внимание лучше фактов. Проведите экскурсию для родных и заметьте, в какой момент им стало скучно: это главный урок гида.","trial_task_ky":"Өз районуңуз боюнча 20 мүнөттүк мини-экскурсия түзүңүз. Айта турган сөзүңүз бар үч жерди тандаңыз (эски имарат, базар, тоо көрүнүшү) жана алардын ортосуна маршрут куруңуз. Ар бир жер үчүн эки мүнөттүк бирден окуя жана угуучуларга бирден суроо даярдаңыз — суроолор көңүлдү фактылардан жакшы кармайт. Экскурсияны туугандарыңызга өткөрүп, аларга кайсы учурда зериктирме болгонун байкаңыз: бул гиддин башкы сабагы.","study_directions_ru":["Туризм и гостеприимство","Международный туризм","География и краеведение"],"study_directions_ky":["Туризм жана меймандостук","Эл аралык туризм","География жана аймак таануу"],"linked_program_refs":[{"institution_photo_key":"taylors","program_hint":"Bachelor of International Hospitality Management (Honours)"}],"sources":["https://www.onetonline.org/link/summary/39-7011.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('313cf7cd-e654-5754-8b9f-132c99f9cf65', 'translator', '1.0.0', '{"id":"translator","title_ru":"Переводчик","title_ky":"Котормочу","orvis_scales":["erudition"],"day_in_work_ru":"Утро — за письменным переводом: договор на двадцать страниц, и каждая формулировка должна значить ровно то же, что в оригинале. Переводчик ведёт собственный словарь терминов проекта, чтобы «поставка» не превратилась на соседней странице в «доставку». Днём — устная работа: онлайн-встреча двух компаний, где он переводит последовательно, по несколько фраз, успевая держать в голове и смысл, и тон. Одна из сторон шутит — и вот это самое сложное: шутку нужно не перевести, а пересоздать. После встречи он честно записывает, какие термины вызвали заминку, и пополняет словарь. Вечером — полчаса чтения на рабочем языке: переводчик остаётся в форме, только пока язык вокруг него живой.","day_in_work_ky":"Таң — жазуу жүзүндөгү котормо менен: жыйырма беттик келишим, ар бир сөз айкашы так эле түп нускадагыдай маанини бериши керек. Котормочу «поставка» коңшу бетте «доставкага» айланып кетпеши үчүн долбоордун терминдеринин өз сөздүгүн жүргүзөт. Күндүзү — оозеки иш: эки компаниянын онлайн-жолугушуусу, ал ырааттуу которот, бир нече фразадан, маанини да, обонду да башында кармап. Тараптардын бири тамашалайт — эң кыйыны мына ушул: тамашаны которуу эмес, кайра жаратуу керек. Жолугушуудан кийин ал кайсы терминдер кыйынчылык жаратканын чын жазып, сөздүктү толуктайт. Кечинде — жумуш тилинде жарым саат окуу: котормочу тил айланасында жандуу болгондо гана формада калат.","environment_ru":"Дом, офис или переговорная — письменный перевод спокоен и одинок, устный полон людей и напряжения. Дедлайны постоянны, темы меняются от медицины до горного дела. Многие переводчики работают на себя с заказчиками из разных стран.","environment_ky":"Үй, кеңсе же сүйлөшүү бөлмөсү — жазуу котормосу тынч жана жалгыз, оозекиси адамдарга жана чыңалууга толо. Дедлайндар туруктуу, темалар медицинадан тоо-кен ишине чейин өзгөрөт. Көп котормочулар ар кайсы өлкөлөрдөгү буюртмачылар менен өз алдынча иштешет.","skills_ru":["Два языка на глубоком уровне, включая родной","Точность: смысл важнее красивого слова","Быстрый поиск и проверка терминов","Память и концентрация для устного перевода","Чувство стиля и контекста","Дисциплина фрилансера: сроки, договорённости, качество"],"skills_ky":["Эки тилди терең деңгээлде билүү, эне тилин кошкондо","Тактык: маани кооз сөздөн маанилүү","Терминдерди тез издөө жана текшерүү","Оозеки котормо үчүн эс тутум жана топтолуу","Стилди жана контекстти сезүү","Фрилансердин тартиби: мөөнөттөр, макулдашуулар, сапат"],"interesting_ru":["Ты становишься мостом, без которого два человека не поняли бы друг друга","Каждый проект — погружение в новую область знаний","Работа возможна из любой точки мира и на любую страну"],"interesting_ky":["Сен көпүрөгө айланасың — сенсиз эки адам бири-бирин түшүнмөк эмес","Ар бир долбоор — жаңы билим тармагына чөмүлүү","Дүйнөнүн каалаган жеринен каалаган өлкөгө иштөө мүмкүн"],"hard_ru":["Машинный перевод забирает простые заказы — остаются сложные, где спрос с тебя выше","Устный перевод — большое умственное напряжение без права на паузу","Доход фрилансера нестабилен, особенно в начале","Ошибка в важном документе может дорого стоить заказчику"],"hard_ky":["Машиналык котормо жөнөкөй буюртмаларды алып жатат — талап жогору татаалдары калат","Оозеки котормо — тыныгууга укуксуз чоң акыл чыңалуусу","Фрилансердин кирешеси туруксуз, айрыкча башында","Маанилүү документтеги ката буюртмачыга кымбатка турушу мүмкүн"],"trial_task_ru":"Переведите короткий текст двумя способами. Возьмите абзац из новости на языке, который учите, и сначала переведите его дословно, слово за словом. Потом отложите оригинал и перескажите тот же смысл так, как сказал бы носитель вашего языка. Сравните два варианта: где дословность звучит нелепо и что пришлось перестроить? Разница между этими текстами — и есть профессия переводчика.","trial_task_ky":"Кыска текстти эки жол менен которуңуз. Үйрөнүп жаткан тилиңиздеги жаңылыктан бир абзац алып, адегенде аны сөзмө-сөз которуңуз. Анан түп нусканы четке коюп, ошол эле маанини өз тилиңизде сүйлөгөн адам кандай айтмак болсо, ошондой айтып бериңиз. Эки вариантты салыштырыңыз: сөзмө-сөздүк кайсы жерде орой угулат жана эмнени кайра курууга туура келди? Бул эки тексттин айырмасы — котормочунун кесиби дал ушул.","study_directions_ru":["Перевод и переводоведение","Лингвистика","Иностранные языки"],"study_directions_ky":["Котормо жана котормо таануу","Лингвистика","Чет тилдер"],"linked_program_refs":[{"institution_photo_key":"xi-an-international-studies-university","program_hint":"Master of Translation"},{"institution_photo_key":"shanghai-international-studies-university","program_hint":"Chinese Language"},{"institution_photo_key":"nanjing-university","program_hint":"English"},{"institution_photo_key":"beijing-language-and-culture-university","program_hint":"Chinese Language Courses"}],"sources":["https://www.onetonline.org/link/summary/27-3091.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('d10ebeb0-6d79-52a1-8551-9ba95055502b', 'international-relations-analyst', '1.0.0', '{"id":"international-relations-analyst","title_ru":"Аналитик-международник","title_ky":"Эл аралык мамилелер боюнча аналитик","orvis_scales":["erudition","analysis"],"day_in_work_ru":"Утро начинается с чтения: сводки новостей по региону, за которым следит аналитик, отчёты международных организаций, заявления официальных лиц. Из потока он выбирает три события, которые действительно что-то меняют, и коротко объясняет почему. Днём — работа над запиской для руководства: соседняя страна меняет правила транзита грузов, и нужно оценить, что это значит для экономики и какие есть варианты ответа. Аналитик проверяет факты по первоисточникам: пресс-релизы, тексты соглашений, статистика таможни — пересказам он не доверяет. После обеда — обсуждение с коллегами, где его выводы разбирают жёсткими вопросами, и это полезно: слабое место лучше найти до публикации. Вечером он готовит короткое выступление для завтрашнего круглого стола — говорить понятно о сложном тоже часть профессии.","day_in_work_ky":"Таң окуудан башталат: аналитик байкаган аймак боюнча жаңылыктар топтому, эл аралык уюмдардын отчёттору, расмий адамдардын билдирүүлөрү. Агымдан ал чындап бир нерсени өзгөрткөн үч окуяны тандап, эмне үчүн экенин кыска түшүндүрөт. Күндүзү — жетекчилик үчүн маалымкат боюнча иш: коңшу өлкө жүк транзитинин эрежелерин өзгөртүп жатат, бул экономика үчүн эмнени билдирерин жана кандай жооп варианттары бар экенин баалоо керек. Аналитик фактыларды алгачкы булактардан текшерет: пресс-релиздер, келишимдердин тексттери, бажы статистикасы — кайра айтууларга ал ишенбейт. Түштөн кийин — кесиптештер менен талкуу, анын корутундуларын катуу суроолор менен талдашат, бул пайдалуу: алсыз жерди жарыялаганга чейин тапкан жакшы. Кечинде ал эртеңки тегерек стол үчүн кыска сөз даярдайт — татаал жөнүндө түшүнүктүү сүйлөө да кесиптин бөлүгү.","environment_ru":"Аналитический центр, министерство, международная организация или университет; много чтения, письма и обсуждений. Регулярные конференции и командировки. Языки — рабочий инструмент: чем их больше, тем шире доступные источники.","environment_ky":"Аналитикалык борбор, министрлик, эл аралык уюм же университет; көп окуу, жазуу жана талкуулар. Үзгүлтүксүз конференциялар жана командировкалар. Тилдер — жумушчу курал: канчалык көп болсо, жеткиликтүү булактар ошончолук кең.","skills_ru":["Глубокое чтение: документы, статистика, исследования","Проверка фактов по первоисточникам","Ясное письмо: сложное — коротко и точно","Иностранные языки, желательно несколько","Знание истории и экономики региона","Устойчивость к неопределённости: в политике редко есть точные ответы"],"skills_ky":["Терең окуу: документтер, статистика, изилдөөлөр","Фактыларды алгачкы булактардан текшерүү","Так жазуу: татаалды — кыска жана даана","Чет тилдер, мүмкүн болсо бир нече","Аймактын тарыхын жана экономикасын билүү","Белгисиздикке туруктуулук: саясатта так жооптор сейрек"],"interesting_ru":["Ты понимаешь, как на самом деле устроены события из новостей","Твои записки могут влиять на реальные решения государств и компаний","Профессия ведёт в дипломатию, международные организации и науку"],"interesting_ky":["Жаңылыктардагы окуялар чындыгында кантип түзүлгөнүн түшүнөсүң","Маалымкаттарың мамлекеттер менен компаниялардын чыныгы чечимдерине таасир этиши мүмкүн","Кесип дипломатияга, эл аралык уюмдарга жана илимге алып барат"],"hard_ru":["Прогнозы в политике часто не сбываются, и это видно всем","Карьера строится медленно: репутация аналитика зарабатывается годами","Много конкуренции за немного позиций","Приходится писать взвешенно даже о том, что вызывает сильные чувства"],"hard_ky":["Саясаттагы божомолдор көп учурда аткарылбайт, муну баары көрөт","Карьера жай курулат: аналитиктин аброю жылдар менен табылат","Аз сандагы орундар үчүн чоң атаандаштык","Күчтүү сезим жараткан нерсе жөнүндө да салмактуу жазууга туура келет"],"trial_task_ru":"Разберите одну международную новость как аналитик. Выберите событие этой недели с участием двух стран и найдите, как о нём пишут три разных источника: местный, из второй страны и международный. Выпишите: в чём все сходятся (это, скорее всего, факты) и в чём расходятся (это уже позиции). Закончите одним абзацем: что произошло, кому это выгодно, чего мы пока не знаем. Это формат настоящей аналитической записки.","trial_task_ky":"Бир эл аралык жаңылыкты аналитик катары талдаңыз. Ушул жуманын эки өлкө катышкан окуясын тандап, ал жөнүндө үч башка булак кантип жазганын табыңыз: жергиликтүү, экинчи өлкөнүкү жана эл аралык. Жазып чыгыңыз: баары эмнеде окшош (бул көбүнчө фактылар) жана эмнеде айырмаланат (бул болсо позициялар). Бир абзац менен бүтүрүңүз: эмне болду, бул кимге пайдалуу, азырынча эмнени билбейбиз. Бул чыныгы аналитикалык маалымкаттын форматы.","study_directions_ru":["Международные отношения","Политология","Мировая экономика"],"study_directions_ky":["Эл аралык мамилелер","Саясат таануу","Дүйнөлүк экономика"],"linked_program_refs":[{"institution_photo_key":"jagiellonian-university","program_hint":"International Relations and Area Studies"},{"institution_photo_key":"university-of-warsaw","program_hint":"International Relations"},{"institution_photo_key":"university-of-wroc-aw","program_hint":"International Relations — Global Studies"},{"institution_photo_key":"university-of-rome-tor-vergata","program_hint":"Global Governance"}],"sources":["https://www.onetonline.org/link/summary/19-3094.00"]}'::JSONB);

INSERT INTO platform_private.profession_cards (id, card_key, version, body)
VALUES ('b063c895-42a0-5515-8758-f634dafdb8cd', 'lawyer', '1.0.0', '{"id":"lawyer","title_ru":"Юрист","title_ky":"Юрист","orvis_scales":["erudition","leadership"],"day_in_work_ru":"День начинается с договора на тридцать страниц: клиент собирается подписать его завтра, и юрист ищет пункты, которые через год могут обернуться проблемой. Два он находит — про штрафы и про то, какой суд будет разбирать споры, — и предлагает формулировки безопаснее. Потом консультация: у семьи вопрос о наследстве, и юрист переводит их запутанную ситуацию на язык статей и сроков, а потом обратно — на человеческий. После обеда он готовится к завтрашнему заседанию: перечитывает материалы дела, выстраивает аргументы и продумывает, что скажет другая сторона. Час уходит на поиск практики: как суды уже решали похожие споры. Вечером юрист пишет короткое заключение — три страницы, от которых зависит сделка клиента.","day_in_work_ky":"Күн отуз беттик келишимден башталат: кардар аны эртең кол коюуга камынып жатат, юрист бир жылдан кийин көйгөйгө айланышы мүмкүн пункттарды издейт. Экөөнү табат — айыптар жөнүндө жана талаштарды кайсы сот карай турганы жөнүндө — жана коопсузураак формулировкаларды сунуштайт. Анан консультация: үй-бүлөдө мурас маселеси, юрист алардын чаташкан кырдаалын беренелер менен мөөнөттөрдүн тилине которот, анан кайра — адам тилине. Түштөн кийин ал эртеңки жыйынга даярданат: иштин материалдарын кайра окуп, аргументтерди куруп, экинчи тарап эмне айтарын ойлонот. Бир саат практика издөөгө кетет: соттор окшош талаштарды кантип чечкен. Кечинде юрист кыска корутунду жазат — кардардын бүтүмү көз каранды болгон үч барак.","environment_ru":"Кабинет, переговорная, суд; много документов, писем и встреч. Работа с людьми в напряжённых ситуациях — сделки, споры, риски. Специализации сильно различаются: корпоративный юрист, адвокат, юрист международной компании живут разными днями.","environment_ky":"Кабинет, сүйлөшүү бөлмөсү, сот; көп документтер, каттар жана жолугушуулар. Чыңалган кырдаалдардагы адамдар менен иш — бүтүмдөр, талаштар, тобокелдиктер. Адистиктер абдан айырмаланат: корпоративдик юрист, адвокат, эл аралык компаниянын юристи ар башка күндөрдө жашашат.","skills_ru":["Точное чтение: в документе важно каждое слово","Ясное письмо и структурная аргументация","Знание законодательства и умение быстро находить нормы","Переговоры и защита позиции","Конфиденциальность и профессиональная этика","Спокойствие в конфликтных ситуациях"],"skills_ky":["Так окуу: документте ар бир сөз маанилүү","Так жазуу жана түзүмдүү аргументация","Мыйзамдарды билүү жана нормаларды тез таба билүү","Сүйлөшүүлөр жана позицияны коргоо","Купуялык жана кесиптик этика","Чыр-чатак кырдаалдарда сабырдуулук"],"interesting_ru":["Ты реально защищаешь людей и бизнес от несправедливости и ошибок","Каждое дело — интеллектуальная задача с высокими ставками","Право нужно везде: от стартапов до международных организаций"],"interesting_ky":["Адамдарды жана бизнести адилетсиздиктен жана каталардан чындап коргойсуң","Ар бир иш — жогорку баадагы интеллектуалдык маселе","Укук бардык жерде керек: стартаптардан эл аралык уюмдарга чейин"],"hard_ru":["Огромные объёмы чтения и документов","Ответственность: за твоей ошибкой стоят чужие деньги и судьбы","Законы меняются, учиться приходится всю карьеру","В спорах не бывает двух победителей — часть работы связана с конфликтами"],"hard_ky":["Окуунун жана документтердин чоң көлөмү","Жоопкерчилик: катаңдын артында бирөөнүн акчасы жана тагдыры турат","Мыйзамдар өзгөрөт, бүт карьера бою окууга туура келет","Талашта эки жеңүүчү болбойт — иштин бир бөлүгү чыр-чатактарга байланыштуу"],"trial_task_ru":"Прочитайте один настоящий документ глазами юриста. Возьмите пользовательское соглашение любого приложения, которым пользуетесь, и найдите за 20 минут ответы на три вопроса: что сервис имеет право делать с вашими данными, при каких условиях вам могут закрыть аккаунт и куда жаловаться при споре. Выпишите ответы своими словами со ссылкой на номер пункта. Если на какой-то вопрос ответа нет — это тоже юридическая находка.","trial_task_ky":"Бир чыныгы документти юристтин көзү менен окуңуз. Өзүңүз колдонгон каалаган колдонмонун колдонуучу макулдашуусун алып, 20 мүнөттө үч суроого жооп табыңыз: сервис маалыматыңыз менен эмне кылууга укуктуу, кайсы шарттарда аккаунтуңузду жаап коюшу мүмкүн жана талаш болгондо кайда даттанса болот. Жоопторду пункттун номерине шилтеме менен өз сөзүңүз менен жазыңыз. Кайсы бир суроого жооп жок болсо — бул да юридикалык табылга.","study_directions_ru":["Юриспруденция","Международное право","Сравнительное право"],"study_directions_ky":["Юриспруденция","Эл аралык укук","Салыштырмалуу укук"],"linked_program_refs":[{"institution_photo_key":"wuhan-university","program_hint":"International Law"},{"institution_photo_key":"university-of-macerata","program_hint":"International, European and Comparative Legal Studies"}],"sources":["https://www.onetonline.org/link/summary/23-1011.00"]}'::JSONB);

DO $p199$
DECLARE
  seeded_module_id UUID;
  lessons_count INTEGER;
  exercises_count INTEGER;
  wrong_type_split INTEGER;
  cards_count INTEGER;
  uncovered_scales INTEGER;
BEGIN
  SELECT module.id INTO seeded_module_id FROM platform_private.learning_modules module
    WHERE module.module_key = 'en-m1-start' AND module.version = '1.0.0';
  IF seeded_module_id IS NULL THEN
    RAISE EXCEPTION 'P199 seed assertion failed: module row is missing';
  END IF;
  SELECT count(*) INTO lessons_count FROM platform_private.learning_lessons lesson
    WHERE lesson.module_id = seeded_module_id;
  IF lessons_count <> 12 THEN
    RAISE EXCEPTION 'P199 seed assertion failed: expected 12 lessons, found %', lessons_count;
  END IF;
  SELECT count(*), count(DISTINCT exercise.exercise_key) INTO exercises_count, wrong_type_split
    FROM platform_private.learning_exercises exercise
    JOIN platform_private.learning_lessons lesson ON lesson.id = exercise.lesson_id
    WHERE lesson.module_id = seeded_module_id;
  IF exercises_count <> 99 OR wrong_type_split <> 99 THEN
    RAISE EXCEPTION 'P199 seed assertion failed: expected 99 unique exercises, found %/%',
      exercises_count, wrong_type_split;
  END IF;
  SELECT count(*) INTO wrong_type_split FROM (
    SELECT exercise.exercise_type, count(*) AS n
    FROM platform_private.learning_exercises exercise
    JOIN platform_private.learning_lessons lesson ON lesson.id = exercise.lesson_id
    WHERE lesson.module_id = seeded_module_id
    GROUP BY exercise.exercise_type
  ) split
  WHERE (split.exercise_type, split.n) NOT IN (
    ('choice', 70), ('matching', 10),
    ('short_answer', 13), ('reading', 6));
  IF wrong_type_split <> 0 THEN
    RAISE EXCEPTION 'P199 seed assertion failed: exercise type composition drifted';
  END IF;
  SELECT count(*), count(DISTINCT card.card_key) INTO cards_count, wrong_type_split
    FROM platform_private.profession_cards card WHERE card.version = '1.0.0';
  IF cards_count <> 24 OR wrong_type_split <> 24 THEN
    RAISE EXCEPTION 'P199 seed assertion failed: expected 24 unique profession cards, found %/%',
      cards_count, wrong_type_split;
  END IF;
  SELECT count(*) INTO uncovered_scales FROM (
    SELECT scale.value AS scale_id, count(*) AS n
    FROM platform_private.profession_cards card
    CROSS JOIN LATERAL jsonb_array_elements_text(card.body -> 'orvis_scales') WITH ORDINALITY AS scale(value, ordinality)
    WHERE card.version = '1.0.0' AND scale.ordinality = 1
    GROUP BY scale.value
  ) primary_coverage
  WHERE primary_coverage.n <> 3;
  IF uncovered_scales <> 0 THEN
    RAISE EXCEPTION 'P199 seed assertion failed: every ORVIS scale must be primary for exactly 3 cards';
  END IF;
END $p199$;

SELECT 'P199_LEARNING_CONTENT_SEED_ASSERTED' AS p199_marker;

COMMIT;
